INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96056, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某种疾病的具体患者实例。", "primary_collocate": null, "pronunciation": "bìng lì", "ipa": "piŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "医院昨天发现了三个新病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病很少见，全国只有五个病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把这个病例写成了一篇报告。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市今天没有新的病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上介绍了一个特别的病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病例告诉我们，早点检查很重要。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这家医院一共接收了二十个病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全世界已经有上千个病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在研究这几个病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸说，本周又增加了两个病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "确诊病例", "label": "复合"}], "register": "书面", "sense_fingerprint": "某种疾病的具体患者实例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "病例", "is_correct": true, "explanation": "正确：bìng lì 指某种疾病的具体患者实例。"}, {"text": "病理", "is_correct": false, "explanation": "bìng lǐ 与 bìng lì 第二音节声调不同（第三声与第四声），意思是病理。"}, {"text": "兵力", "is_correct": false, "explanation": "bīng lì 与 bìng lì 第一音节声调不同（第一声与第四声），意思是兵力。"}, {"text": "冰梨", "is_correct": false, "explanation": "bīng lí 与 bìng lì 两个音节声调都不同，意思是一种梨。"}], "explanations": {"病例": "正确：bìng lì 指某种疾病的具体患者实例。", "病理": "bìng lǐ 与 bìng lì 第二音节声调不同（第三声与第四声），意思是病理。", "兵力": "bīng lì 与 bìng lì 第一音节声调不同（第一声与第四声），意思是兵力。", "冰梨": "bīng lí 与 bìng lì 两个音节声调都不同，意思是一种梨。"}, "sentence_index": null, "correct_answer": "病例"}, "level_3": {"options": [{"text": "病例", "is_correct": true, "explanation": "正确：“病例”指某种疾病的具体患者实例，与“发现新病例”相符。"}, {"text": "病房", "is_correct": false, "explanation": "搭配：“发现”不说“发现病房”，病房应说“新增”或“设立”。"}, {"text": "病床", "is_correct": false, "explanation": "搭配：“发现”不用于病床，病床是增设的设备。"}, {"text": "病魔", "is_correct": false, "explanation": "语域：“病魔”是文学比喻，不用于医院的正式病例统计。"}], "explanations": {"病例": "正确：“病例”指某种疾病的具体患者实例，与“发现新病例”相符。", "病房": "搭配：“发现”不说“发现病房”，病房应说“新增”或“设立”。", "病床": "搭配：“发现”不用于病床，病床是增设的设备。", "病魔": "语域：“病魔”是文学比喻，不用于医院的正式病例统计。"}, "sentence_index": 0, "correct_answer": "病例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给病例打了针。", "explanation": "这里应该用〈病人〉。“病例”指个案或记录，不能接受注射。"}, {"text": "病例感到很痛。", "explanation": "这里应该用〈病人〉。“病例”指疾病的个案或记录，不是人，不能感到疼痛。"}, {"text": "妻子陪着病例去医院。", "explanation": "这里应该用〈患者〉。“病例”指个案或记录，不能被人陪同去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病例", "is_correct": true, "explanation": "正确：“病例”指病人个案，符合“去年这家医院接收了二十个病例”的语境。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：医院接收的是病人，不会“接收”病毒本身。"}, {"text": "病菌", "is_correct": false, "explanation": "语义：“病菌”是微生物，不是医院接收的对象。"}, {"text": "病灶", "is_correct": false, "explanation": "搭配：“接收”不用于病灶，病灶是检查时发现的部位。"}], "explanations": {"病例": "正确：“病例”指病人个案，符合“去年这家医院接收了二十个病例”的语境。", "病毒": "语义：医院接收的是病人，不会“接收”病毒本身。", "病菌": "语义：“病菌”是微生物，不是医院接收的对象。", "病灶": "搭配：“接收”不用于病灶，病灶是检查时发现的部位。"}, "sentence_index": 6, "correct_answer": "病例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一个病例吃掉了。", "explanation": "这里应该用〈饭〉。“病例”是个案或记录，不能吃。"}, {"text": "这种病例很甜，我很喜欢。", "explanation": "这里应该用〈糖果〉。“病例”不是食物，不能用“甜”来形容。"}, {"text": "他的病例很高兴地笑了。", "explanation": "这里应该用〈他〉。“病例”指个案或记录，不会高兴地笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院这个月又确诊了十只病例。", "corrected_sentence": "这家医院这个月又确诊了十个病例。", "error_description": "错误：“病例”的量词应用“个”（或“例”），“只”只用于动物等，应改为“十个病例”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天新增了二十病例。", "corrected_sentence": "今天新增了二十个病例。", "error_description": "错误：数词与“病例”之间漏掉量词，应为“二十个病例”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
