INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96057, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发家是家里越来越有钱了。", "primary_collocate": null, "pronunciation": "fā jiā", "ipa": "fa⁵⁵ tɕja⁵⁵", "syllable_count": 2, "sentences": [{"text": "王老板是靠卖布发家的。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家农家乐靠旅游发家了。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家靠养鱼发家。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸说，他年轻时没钱，后来发家了。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想发家，所以每天都工作很晚。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都想发家，可是没有人会白白给你钱。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居靠开工厂发家，买了新房子。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小生活很苦，长大后才发家。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人靠捡废品发家的故事很有名。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠卖茶叶发家，现在有三家店。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发家致富", "label": "复合"}, {"form": "发了家", "label": "体标"}], "register": "口语", "sense_fingerprint": "家里越来越有钱，生活变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发家", "is_correct": true, "explanation": "正确：“发家”指靠经营变富，“靠卖布”后接“发家”正合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“靠卖布”说的是谋生，“唱歌”与卖布无关。"}, {"text": "迁走", "is_correct": false, "explanation": "语义：“迁走”指搬离，不能作为靠卖布致富的方式。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“靠”后面要接能带来收益的行为，“生病”不能这样搭配。"}], "explanations": {"发家": "正确：“发家”指靠经营变富，“靠卖布”后接“发家”正合句意。", "唱歌": "语义：“靠卖布”说的是谋生，“唱歌”与卖布无关。", "迁走": "语义：“迁走”指搬离，不能作为靠卖布致富的方式。", "生病": "搭配：“靠”后面要接能带来收益的行为，“生病”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "发家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年，我们这里的工业越来越发家了。", "explanation": "这里应该用〈发达〉。“发家”说的是家里富起来，工业的兴盛要用“发达”。"}, {"text": "这座城市的交通发家得很快。", "explanation": "这里应该用〈发展〉。“发家”只说家里富裕，城市交通的进步要用“发展”。"}, {"text": "这个学科近些年越来越发家了。", "explanation": "这里应该用〈兴旺〉。“发家”说的是家里富起来，学科的景气要用“兴旺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发家", "is_correct": true, "explanation": "正确：“发家”指靠经营变富，与“靠开工厂”“买了新房子”前后一致。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋与靠开工厂致富无关，句意不通。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”与“买了新房子”的富裕结果相矛盾。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“靠开工厂”后面要接能带来收益的结果，“咳嗽”不能这样搭配。"}], "explanations": {"发家": "正确：“发家”指靠经营变富，与“靠开工厂”“买了新房子”前后一致。", "下棋": "语义：下棋与靠开工厂致富无关，句意不通。", "失业": "语义：“失业”与“买了新房子”的富裕结果相矛盾。", "咳嗽": "搭配：“靠开工厂”后面要接能带来收益的结果，“咳嗽”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "发家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个庙会这几年越来越发家了。", "explanation": "这里应该用〈红火〉。“发家”说的是家里富起来，庙会的热闹要用“红火”。"}, {"text": "这些年艺术界越来越发家了，大家都很满意。", "explanation": "这里应该用〈繁荣〉。“发家”说的是家里富起来，艺术界的兴盛要用“繁荣”。"}, {"text": "我们的国家越来越发家了。", "explanation": "这里应该用〈富强〉。“发家”指家庭富起来，国家的强盛要用“富强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一家靠养猪了发家，全家搬进了城里。", "corrected_sentence": "他们一家靠养猪发了家，全家搬进了城里。", "error_description": "离合错误：“发家”拆开时，“了”要放在“发”后，应说“发了家”，不能说“了发家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一家靠修车发家很快，大家都很佩服。", "corrected_sentence": "这一家靠修车发家得很快，大家都很佩服。", "error_description": "补语错误：“发家得很快”中间要有“得”，不能说“发家很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
