INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96058, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使家业兴旺富裕起来。", "primary_collocate": null, "pronunciation": "fā jiā", "ipa": "fa⁵⁵ tɕja⁵⁵", "syllable_count": 2, "sentences": [{"text": "他靠做生意发家。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人是靠种茶叶发家的。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时靠开小店发家。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人想发家，但是没那么容易。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家是从卖水果开始发家的。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想发家，让父母过上好日子。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那户人家靠养牛发家了。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠努力工作发家，不是靠运气。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在南方做生意，很快就发家了。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他家是靠开饭馆发家的。", "target_word": "发家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发家致富", "label": "复合"}, {"form": "发了家", "label": "体标"}], "register": "口语", "sense_fingerprint": "靠做生意、种养等使家庭变富裕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发家", "is_correct": true, "explanation": "正确：“发家”指靠经营使家业富裕，与“靠做生意”相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“靠做生意”说的是谋生致富，“睡觉”与之无关。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”与靠做生意谋利的意思相反，句子说不通。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“靠”后面要接能带来收益的行为，“生病”不能作为靠的方式。"}], "explanations": {"发家": "正确：“发家”指靠经营使家业富裕，与“靠做生意”相合。", "睡觉": "语义：“靠做生意”说的是谋生致富，“睡觉”与之无关。", "失业": "语义：“失业”与靠做生意谋利的意思相反，句子说不通。", "生病": "搭配：“靠”后面要接能带来收益的行为，“生病”不能作为靠的方式。"}, "sentence_index": 0, "correct_answer": "发家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些年文坛越来越发家了，作品也多了。", "explanation": "这里应该用〈繁荣〉。“发家”说的是家业富起来，文坛的兴盛要用“繁荣”。"}, {"text": "这个地区的经济发家得很快。", "explanation": "这里应该用〈发展〉。“发家”只说家庭或个人富起来，地区经济的进步要用“发展”。"}, {"text": "这几年，这里的科技越来越发家了。", "explanation": "这里应该用〈发达〉。“发家”说的是家业富起来，科技的先进要用“发达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发家", "is_correct": true, "explanation": "正确：“发家”指靠养牛使家业富裕，符合句意。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：养牛与下雨无关，“靠养牛下雨”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“靠养牛”是谋生的方式，“唱歌”不能作为靠的结果。"}, {"text": "迁走", "is_correct": false, "explanation": "搭配：“靠养牛”后面接的应是致富或谋生的结果，“迁走”不能这样搭配。"}], "explanations": {"发家": "正确：“发家”指靠养牛使家业富裕，符合句意。", "下雨": "语义：养牛与下雨无关，“靠养牛下雨”说不通。", "唱歌": "语义：“靠养牛”是谋生的方式，“唱歌”不能作为靠的结果。", "迁走": "搭配：“靠养牛”后面接的应是致富或谋生的结果，“迁走”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "发家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的国家靠改革越来越发家了。", "explanation": "这里应该用〈富强〉。“发家”指家庭或个人的家业富起来，说国家的强盛要用“富强”。"}, {"text": "这个学科近些年越来越发家了，大家都很高兴。", "explanation": "这里应该用〈兴旺〉。“发家”说的是家业富裕，学科的景气要用“兴旺”。"}, {"text": "这个庙会今年特别发家了，摊子都摆到了街上。", "explanation": "这里应该用〈红火〉。“发家”说的是家业富裕，庙会的热闹要用“红火”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他靠做生意了发家，买了新房子。", "corrected_sentence": "他靠做生意发了家，买了新房子。", "error_description": "体标错误：“了”应放在离合词“发家”中间（发了家），不能放在“发家”前面（了发家）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一家靠养鸡发家很快，邻居都很羡慕。", "corrected_sentence": "他们一家靠养鸡发家得很快，邻居都很羡慕。", "error_description": "补语错误：“发家得很快”中间要用“得”连接补语，不能省掉“得”说“发家很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
