INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96071, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "精灵是故事里很小、很聪明、会变魔法的小生物。", "primary_collocate": null, "pronunciation": "jīng líng", "ipa": "tɕiŋ˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "故事里的精灵住在大树里。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个精灵挥了挥魔法棒。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个精灵很小，只有一片叶子那么大。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精灵用魔法把花变成了星星。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢书里那个聪明的精灵。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想看精灵怎么变魔法。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，精灵在故事中的森林里唱歌。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动画片里有一个会飞的精灵。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我讲了一个精灵的故事。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精灵送给小女孩一朵会发光的花。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小精灵", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事里会变魔法的聪明小生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96071, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精灵", "is_correct": true, "explanation": "精灵：故事里很小、很聪明、会变魔法的小生物。"}, {"text": "警铃", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是报警用的铃。"}, {"text": "清灵", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（送气与不送气），意思是清脆灵动。"}, {"text": "金陵", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（少了 ng），意思是南京的旧称。"}], "explanations": {"精灵": "精灵：故事里很小、很聪明、会变魔法的小生物。", "警铃": "jǐng（第三声）与 jīng（第一声）声调不同，意思是报警用的铃。", "清灵": "qīng 与 jīng 声母不同（送气与不送气），意思是清脆灵动。", "金陵": "jīn 与 jīng 韵母不同（少了 ng），意思是南京的旧称。"}, "sentence_index": null, "correct_answer": "精灵"}, "level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：“住在大树里”的主语应是会居住的生物，闹钟不能住在大树里。"}, {"text": "精灵", "is_correct": true, "explanation": "精灵：故事里很小、会变魔法的小生物，可以住在大树里。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“住”要求有生命的施事，“石头”不能作“住”的主语。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不会住在大树里，与“住”的对象不符。"}], "explanations": {"闹钟": "语义：“住在大树里”的主语应是会居住的生物，闹钟不能住在大树里。", "精灵": "精灵：故事里很小、会变魔法的小生物，可以住在大树里。", "石头": "配价：“住”要求有生命的施事，“石头”不能作“住”的主语。", "课本": "语义：课本不会住在大树里，与“住”的对象不符。"}, "sentence_index": 0, "correct_answer": "精灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在森林里遇见了一棵精灵，它对我笑了笑。", "explanation": "这里应该用〈个〉。棵用于树木，不用来数精灵这样的小生物。"}, {"text": "书店门口走出来一块精灵，把我吓了一跳。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数精灵。"}, {"text": "那个女人被人们叫作精灵，因为她总是用美貌迷惑男人。", "explanation": "这里用的是“迷惑男人的女妖”的意思，应该用〈妖精〉。精灵指故事里很小、很聪明、会变魔法的小生物，不指这种人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96071, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精灵", "is_correct": true, "explanation": "精灵：故事里很小、很聪明、会变魔法的小生物。"}, {"text": "精英", "is_correct": false, "explanation": "líng（第二声）与 yīng（第一声）声母和声调都不同，意思是精华、优秀的人。"}, {"text": "经营", "is_correct": false, "explanation": "líng 与 yíng 声母不同，意思是经营、管理。"}, {"text": "惊醒", "is_correct": false, "explanation": "líng 与 xǐng 声母和声调都不同，意思是从睡梦中醒来。"}], "explanations": {"精灵": "精灵：故事里很小、很聪明、会变魔法的小生物。", "精英": "líng（第二声）与 yīng（第一声）声母和声调都不同，意思是精华、优秀的人。", "经营": "líng 与 yíng 声母不同，意思是经营、管理。", "惊醒": "líng 与 xǐng 声母和声调都不同，意思是从睡梦中醒来。"}, "sentence_index": null, "correct_answer": "精灵"}, "level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：“唱歌”需要会唱的主体，冰箱不能唱歌。"}, {"text": "精灵", "is_correct": true, "explanation": "精灵：故事中的神奇小生物，可以在夜里的森林里唱歌。"}, {"text": "木头", "is_correct": false, "explanation": "配价：“唱歌”要求能发声的施事，“木头”不能作主语。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌不会唱歌，与“唱歌”的主语不符。"}], "explanations": {"冰箱": "语义：“唱歌”需要会唱的主体，冰箱不能唱歌。", "精灵": "精灵：故事中的神奇小生物，可以在夜里的森林里唱歌。", "木头": "配价：“唱歌”要求能发声的施事，“木头”不能作主语。", "课桌": "语义：课桌不会唱歌，与“唱歌”的主语不符。"}, "sentence_index": 6, "correct_answer": "精灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "半夜里，老房子的走廊上突然出现了一棵精灵，吓得大家不敢动。", "explanation": "这里应该用〈个〉。棵用于树木，不能用来数精灵。"}, {"text": "我的邻居是一位精灵，每天都在院子里浇花。", "explanation": "这里把人称作精灵，但精灵指故事里很小、会变魔法的小生物，不用来称呼邻居这样的人。"}, {"text": "妈妈给我买了一条精灵做礼物。", "explanation": "这里应该用〈个〉。条用于细长的东西，不能用来数精灵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在森林里看见三棵精灵。", "corrected_sentence": "我在森林里看见三个精灵。", "error_description": "量词错误：错误形式是“三棵精灵”，正确形式是“三个精灵”。“棵”用于树木，精灵要用“个”来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一棵会变魔法的精灵住在花园里。", "corrected_sentence": "一个会变魔法的精灵住在花园里。", "error_description": "量词错误：错误形式是“一棵会变魔法的精灵”，正确形式是“一个会变魔法的精灵”。“棵”用于树木，精灵要用“个”来数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
