INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "连比是数学里把三个或更多的数放在一起比。", "primary_collocate": null, "pronunciation": "lián bǐ", "ipa": "ljɛn˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "连比就是把三个数放在一起比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "配制蛋糕时，面粉、糖和油的连比是五比二比一。", "target_word": "连比", "complexity_tier": "T3", "furigana": "pèi zhì dàn gāo shí, miàn fěn, táng hé yóu de lián bǐ shì wǔ bǐ èr bǐ yī.", "sentence_source": "generated"}, {"text": "请写出这三条边的连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连比里至少要有三个数。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂连比，所以做错了这道题。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水、牛奶和糖的连比是十比五比一。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个班的人数连比是三比四比五。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天数学课学的是连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三种颜料的连比是一比一比二。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把两个比变成连比，再算答案。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連比", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "数学：三个或更多的数放在一起比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和", "is_correct": false, "explanation": "语义：“和”是加法的结果，不能说“就是把三个数放在一起比”。"}, {"text": "连比", "is_correct": true, "explanation": "连比：把三个或更多的数放在一起比，与句子的解释相合。"}, {"text": "乘积", "is_correct": false, "explanation": "语义：“乘积”是相乘的结果，不是把数放在一起比的关系。"}, {"text": "方程", "is_correct": false, "explanation": "搭配：“方程”通常与“解”搭配，不与“就是把……放在一起比”搭配。"}], "explanations": {"和": "语义：“和”是加法的结果，不能说“就是把三个数放在一起比”。", "连比": "连比：把三个或更多的数放在一起比，与句子的解释相合。", "乘积": "语义：“乘积”是相乘的结果，不是把数放在一起比的关系。", "方程": "搭配：“方程”通常与“解”搭配，不与“就是把……放在一起比”搭配。"}, "sentence_index": 0, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "甲和乙两个数的连比是三比四。", "explanation": "这里用错了〈连比〉。连比要求三个或三个以上的量，甲和乙只有两个数，两个数之间的比只能叫“比”。"}, {"text": "我在本子上写了一条连比。", "explanation": "这里应该用〈个〉。条用于细长的东西，不能用来数连比。"}, {"text": "这块布的长和宽的连比是三比二。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总数", "is_correct": false, "explanation": "语义：“总数”表示数量的总和，不能与“比”组成三个班人数的关系。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”表示两数相减的结果，不是三个班人数之间的比。"}, {"text": "连比", "is_correct": true, "explanation": "连比：三个或三个以上的量之间的比，与“三个班的人数……是三比四比五”相合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说的是人的重量，不能用来说“三个班的人数”。"}], "explanations": {"总数": "语义：“总数”表示数量的总和，不能与“比”组成三个班人数的关系。", "差": "语义：“差”表示两数相减的结果，不是三个班人数之间的比。", "连比": "连比：三个或三个以上的量之间的比，与“三个班的人数……是三比四比五”相合。", "体重": "搭配：“体重”说的是人的重量，不能用来说“三个班的人数”。"}, "sentence_index": 6, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的面粉与糖的连比是五比一。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}, {"text": "老师让我们画出一块连比。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数连比。"}, {"text": "他拿出一只连比给我看。", "explanation": "这里应该用〈个〉。只用于动物等，不能用来数连比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们写一条连比。", "corrected_sentence": "老师让我们写一个连比。", "error_description": "量词错误：错误形式是“一条连比”，正确形式是“一个连比”。“条”用于细长的东西，不用来数连比。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这个连比算了对。", "corrected_sentence": "我把这个连比算对了。", "error_description": "补语位置错误：“对”是结果补语，“了”应放在补语之后，错误形式是“算了对”，正确形式是“算对了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
