INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学上指三个或三个以上的量之间的比。", "primary_collocate": null, "pronunciation": "lián bǐ", "ipa": "ljɛn˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这三个数的连比是二比三比五。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样用连比表示三个量的关系。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红球、白球和黑球的个数连比是一比二比三。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要先求出三个角的连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "配水泥、沙子和石头时，要按连比来算。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲、乙、丙的连比是三比四比五。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两个比合成了一个连比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人的钱数连比是二比三比四。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学连比以前，你要先懂得什么是比。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长、宽、高的连比是四比三比二。", "target_word": "连比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連比", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "数学：三个以上的量之间的比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和", "is_correct": false, "explanation": "语义：“和”是加法的结果，不能与“比”组成比的关系。"}, {"text": "连比", "is_correct": true, "explanation": "连比：三个或三个以上的量之间的比，与“这三个数的……是二比三比五”相合。"}, {"text": "乘积", "is_correct": false, "explanation": "语义：“乘积”是相乘的结果，不是三个数之间的比。"}, {"text": "倍数", "is_correct": false, "explanation": "搭配：“倍数”一般与“是几倍”搭配，不与“比”的形式连用。"}], "explanations": {"和": "语义：“和”是加法的结果，不能与“比”组成比的关系。", "连比": "连比：三个或三个以上的量之间的比，与“这三个数的……是二比三比五”相合。", "乘积": "语义：“乘积”是相乘的结果，不是三个数之间的比。", "倍数": "搭配：“倍数”一般与“是几倍”搭配，不与“比”的形式连用。"}, "sentence_index": 0, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "甲和乙两个数的连比是三比四。", "explanation": "这里用错了〈连比〉。连比要求三个或三个以上的量，甲和乙只有两个数，两个数之间的比只能叫“比”。"}, {"text": "这块布的长和宽的连比是三比二。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}, {"text": "我算出一条连比。", "explanation": "这里应该用〈个〉。条用于细长的东西，不用来数连比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "语义：“面积”是平面的大小，不能由两个比合成。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热的程度，不能由两个比合成。"}, {"text": "连比", "is_correct": true, "explanation": "连比：把两个比合成的三个或更多量的比，与句中“合成”的结果相合。"}, {"text": "乐章", "is_correct": false, "explanation": "语域：“乐章”是文艺用语，与前面的数学语境不协调。"}], "explanations": {"面积": "语义：“面积”是平面的大小，不能由两个比合成。", "温度": "语义：“温度”是冷热的程度，不能由两个比合成。", "连比": "连比：把两个比合成的三个或更多量的比，与句中“合成”的结果相合。", "乐章": "语域：“乐章”是文艺用语，与前面的数学语境不协调。"}, "sentence_index": 6, "correct_answer": "连比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种饮料的水与糖的连比是五比一。", "explanation": "这里应该用〈比〉。连比要求三个或三个以上的量，只有两个量时用“比”。"}, {"text": "他写下了一块连比。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数连比。"}, {"text": "他写了一只连比。", "explanation": "这里应该用〈个〉。只用于动物等，不能用来数连比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他算出了一条连比。", "corrected_sentence": "他算出了一个连比。", "error_description": "量词错误：错误形式是“一条连比”，正确形式是“一个连比”。“条”用于细长的东西，不能用来数连比。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这三个数的连比算了对。", "corrected_sentence": "这三个数的连比算对了。", "error_description": "补语位置错误：“对”是结果补语，“了”应放在补语之后，错误形式是“算了对”，正确形式是“算对了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
