INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命运；指碰巧得到的好或坏的机会。", "primary_collocate": null, "pronunciation": "yùn qi", "ipa": "yn˥˩ tɕʰi", "syllable_count": 2, "sentences": [{"text": "我想去试试运气。", "target_word": "运气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想碰碰运气，看能不能买到票。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事只能看运气了。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想靠运气，想靠自己努力。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的运气一直不错，总能遇到贵人。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，不只是运气，也靠努力。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能一直有好运气。", "target_word": "运气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次能进决赛，运气成分不小。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去碰碰运气，说不定能找到工作。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己的运气不好，总是遇到麻烦。", "target_word": "运气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "運氣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "碰巧得到的机会或命运", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '985b8fb7-0352-4226-b681-027abeaba146') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运气", "is_correct": true, "explanation": "“运气”指碰巧得到的机会，“试试运气”是常用说法，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“试试”不搭配天气，不说“试试天气”。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位不能拿来尝试，句子要的是碰运气的机会。"}, {"text": "尴尬", "is_correct": false, "explanation": "搭配：“试试”后接的是可以尝试的事物，“尴尬”不能被尝试。"}], "explanations": {"运气": "“运气”指碰巧得到的机会，“试试运气”是常用说法，符合句意。", "天气": "搭配：“试试”不搭配天气，不说“试试天气”。", "座位": "语义：座位不能拿来尝试，句子要的是碰运气的机会。", "尴尬": "搭配：“试试”后接的是可以尝试的事物，“尴尬”不能被尝试。"}, "sentence_index": 0, "correct_answer": "运气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用运气搬动了那块大石头。", "explanation": "这里应该用〈力气〉。“运气”是碰巧的机会，不能当作搬东西的力量。"}, {"text": "这位作家的运气很高，写得很好。", "explanation": "这里应该用〈才华〉。“运气”不能用来形容人的写作能力，要用“才华”。"}, {"text": "他的运气胖了五斤，医生让他多运动。", "explanation": "这里应该用〈身体〉。“运气”是抽象的机会，不能像身体一样长胖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运气", "is_correct": true, "explanation": "“运气”指碰巧得到的好机会，“有好运气”符合句意。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“有好……”后接的是可以拥有的好事物，“饥饿”不能被拥有。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡不是可以“一直有好”的东西，句子说的是人的机遇。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本与句子中“碰巧的机会”的含义不符。"}], "explanations": {"运气": "“运气”指碰巧得到的好机会，“有好运气”符合句意。", "饥饿": "搭配：“有好……”后接的是可以拥有的好事物，“饥饿”不能被拥有。", "灯泡": "语义：灯泡不是可以“一直有好”的东西，句子说的是人的机遇。", "课本": "语义：课本与句子中“碰巧的机会”的含义不符。"}, "sentence_index": 6, "correct_answer": "运气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车运气很快，一会儿就到了。", "explanation": "这里应该用〈速度〉。“运气”不能用来形容快慢。"}, {"text": "他把运气挂在墙上，像挂一幅画。", "explanation": "这里应该用〈照片〉。“运气”是抽象的机会或命运，不能像照片一样挂在墙上。"}, {"text": "这碗汤运气很鲜，大家都喜欢。", "explanation": "这里应该用〈味道〉。“运气”是偶然的机会或命运，不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一张彩票，想试试一只运气。", "corrected_sentence": "我买了一张彩票，想试试运气。", "error_description": "量词错误：“运气”不能用“只”计量，应直接说“试试运气”，去掉多余的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次成功，运气的成分大很。", "corrected_sentence": "这次成功，运气的成分很大。", "error_description": "语序错误：“很”应放在形容词“大”前面，说“很大”，不能说“大很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
