INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96109, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阐述是把一件事的道理讲清楚。", "primary_collocate": null, "pronunciation": "chǎn shù", "ipa": "tʂʰan˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "老师把这个问题的道理阐述得很清楚。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上阐述了自己的想法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你阐述一下这件事的原因。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她阐述的道理让大家都听懂了。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生向病人阐述了治疗的方法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用简单的话阐述这个道理。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授慢慢阐述着自己的看法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在文章里阐述了保护环境的重要性。", "target_word": "阐述", "complexity_tier": "T3", "furigana": "chǎnshù", "sentence_source": "generated"}, {"text": "你能不能阐述一下你的理由？", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理阐述完计划，大家开始提问。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阐述了", "label": "体标：了"}, {"form": "阐述过", "label": "体标：过"}, {"form": "阐述着", "label": "体标：着"}], "register": "书面", "sense_fingerprint": "把事情的道理讲清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82205d4-7b8d-4232-8d7a-689624c1de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96109, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增加", "is_correct": false, "explanation": "语义：“增加”指数量变多，不能说把道理“增加得很清楚”。"}, {"text": "阐述", "is_correct": true, "explanation": "正确：“阐述得很清楚”指把道理讲明白，与句中“道理”“很清楚”相合。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”与“讲清楚”意思相反，道理不能说“丢失得很清楚”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面，不能用来处理“道理”。"}], "explanations": {"增加": "语义：“增加”指数量变多，不能说把道理“增加得很清楚”。", "阐述": "正确：“阐述得很清楚”指把道理讲明白，与句中“道理”“很清楚”相合。", "丢失": "语义：“丢失”与“讲清楚”意思相反，道理不能说“丢失得很清楚”。", "打扫": "搭配：“打扫”的对象是房间、地面，不能用来处理“道理”。"}, "sentence_index": 0, "correct_answer": "阐述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天晚上阐述一个很长的故事。", "explanation": "这里应该用〈讲〉。“阐述”用于讲清道理、观点，讲故事要用〈讲〉。"}, {"text": "作家阐述了江南的美丽风景。", "explanation": "这里应该用〈描写〉。“阐述”用于道理、观点，描绘风景要用〈描写〉。"}, {"text": "她用音乐阐述了心里的悲伤。", "explanation": "这里应该用〈表达〉。“阐述”用于道理、观点，抒发情感要用〈表达〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是有形的东西，不能用于“看法”。"}, {"text": "阐述", "is_correct": true, "explanation": "正确：“阐述着自己的看法”指讲出并论述自己的观点，与句中“老教授”“慢慢”相合。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品，不能用于“看法”。"}, {"text": "打听", "is_correct": false, "explanation": "语义：“打听”是询问消息，与“老教授讲出自己的看法”的语境不合。"}], "explanations": {"擦": "搭配：“擦”的对象是有形的东西，不能用于“看法”。", "阐述": "正确：“阐述着自己的看法”指讲出并论述自己的观点，与句中“老教授”“慢慢”相合。", "收藏": "搭配：“收藏”的对象是物品，不能用于“看法”。", "打听": "语义：“打听”是询问消息，与“老教授讲出自己的看法”的语境不合。"}, "sentence_index": 6, "correct_answer": "阐述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她阐述了小时候的一次旅行。", "explanation": "这里应该用〈叙述〉。“阐述”用于讲清道理或观点，记叙经历要用〈叙述〉。"}, {"text": "校长阐述了放假的消息。", "explanation": "这里应该用〈宣布〉。“阐述”的对象是道理、观点，宣告消息要用〈宣布〉。"}, {"text": "他向朋友阐述天气太热。", "explanation": "这里应该用〈抱怨〉。“阐述”用于讲清道理、观点，抱怨不满要用〈抱怨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这些想法阐述很透彻。", "corrected_sentence": "她把这些想法阐述得很透彻。", "error_description": "补语错误：“把”字句中“阐述”后带描写性补语“很透彻”时，要用“得”连接（状态补语），应说“阐述得很透彻”，不能说“阐述很透彻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向父母阐述的自己的打算。", "corrected_sentence": "他向父母阐述了自己的打算。", "error_description": "“了”误作“的”：“阐述”后应接表示完成的“了”，说“阐述了自己的打算”，不能用结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
