INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "详细而明白地论述。", "primary_collocate": null, "pronunciation": "chǎn shù", "ipa": "tʂʰan˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他在书中阐述了自己的教育观点。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者阐述过很多经济问题。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文第二部分阐述了研究的结果。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告阐述了公司明年的发展目标。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在演讲中阐述了对环境的看法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书阐述了中国历史的变化。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章先阐述问题，再提出办法。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家在会议上阐述了新的政策。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章阐述得又详细又明白。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家阐述过自己的写作经验。", "target_word": "阐述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阐述了", "label": "体标：了"}, {"form": "阐述过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "在文章或发言中详细论述观点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82205d4-7b8d-4232-8d7a-689624c1de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是有形的物体，不能用于“观点”。"}, {"text": "阐述", "is_correct": true, "explanation": "正确：“在书中阐述自己的教育观点”指详细论述观点，与“书中”“教育观点”相合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对器物的损坏，与“教育观点”的论述无关。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品，不能用于“观点”。"}], "explanations": {"搬运": "搭配：“搬运”的对象是有形的物体，不能用于“观点”。", "阐述": "正确：“在书中阐述自己的教育观点”指详细论述观点，与“书中”“教育观点”相合。", "修理": "语义：“修理”针对器物的损坏，与“教育观点”的论述无关。", "收藏": "搭配：“收藏”的对象是物品，不能用于“观点”。"}, "sentence_index": 0, "correct_answer": "阐述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师阐述了新买的书包。", "explanation": "这里应该用〈展示〉。“阐述”用于详细论述道理、观点，把物品拿给别人看要用〈展示〉。"}, {"text": "画家阐述了秋天的树林。", "explanation": "这里应该用〈描绘〉。“阐述”用于论述道理、观点，描绘景物要用〈描绘〉。"}, {"text": "他用眼神阐述了愤怒。", "explanation": "这里应该用〈表达〉。“阐述”用于论述道理、观点，表达情绪要用〈表达〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是有形的东西，不能用于“问题”。"}, {"text": "阐述", "is_correct": true, "explanation": "正确：“先阐述问题，再提出办法”指先讲清问题的道理，与后半句的语境相合。"}, {"text": "观赏", "is_correct": false, "explanation": "语义：“观赏”指欣赏美好的事物，与“先……再提出办法”的分析语境不合。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”的对象是物体，不能用于“问题”。"}], "explanations": {"擦": "搭配：“擦”的对象是有形的东西，不能用于“问题”。", "阐述": "正确：“先阐述问题，再提出办法”指先讲清问题的道理，与后半句的语境相合。", "观赏": "语义：“观赏”指欣赏美好的事物，与“先……再提出办法”的分析语境不合。", "烧": "搭配：“烧”的对象是物体，不能用于“问题”。"}, "sentence_index": 6, "correct_answer": "阐述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向妈妈阐述了昨天买的衣服。", "explanation": "这里应该用〈介绍〉。“阐述”用于详细论述道理、观点，向别人讲解物品要用〈介绍〉。"}, {"text": "他向别人阐述消息。", "explanation": "这里应该用〈打听〉。“阐述”的对象是道理、观点，询问消息要用〈打听〉。"}, {"text": "她向朋友阐述工作太忙。", "explanation": "这里应该用〈抱怨〉。“阐述”用于讲清道理、观点，诉说工作的辛苦要用〈抱怨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把自己的理论阐述了很清楚。", "corrected_sentence": "她把自己的理论阐述得很清楚。", "error_description": "补语错误：“阐述”后带描写性补语“很清楚”时，要用“得”连接（状态补语），不能用“了”。正确为“阐述得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位教授你阐述了研究思路。", "corrected_sentence": "这位教授向你阐述了研究思路。", "error_description": "介词漏用：“阐述”引出听者时通常要用介词“向”，应说“向你阐述”，不能省去“向”直接接代词“你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头部是身体最上面带着脸的那一块。", "primary_collocate": null, "pronunciation": "tóu bù", "ipa": "tʰoʊ˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "头部在身体的最上面。", "target_word": "头部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "头部有眼睛、鼻子和嘴。", "target_word": "头部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "画人的时候，先画头部。", "target_word": "头部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "头部连着脖子和身体。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的头部比身体大一些。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师指着图，说这是人的头部。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人的头部有头发、耳朵和脸。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用手摸了摸孩子的头部。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他戴上帽子，盖住了头部。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图只画了头部，没有画身体。", "target_word": "头部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭部", "label": "繁体"}], "register": "书面", "sense_fingerprint": "身体最上面带着脸的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '985b8fb7-0352-4226-b681-027abeaba146') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头部", "is_correct": true, "explanation": "“头部”是身体最上面的部分，与“在身体的最上面”相符。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚在身体最下面，与“最上面”正好相反。"}, {"text": "腰", "is_correct": false, "explanation": "语义：腰在身体中部，不在最上面。"}, {"text": "脚趾", "is_correct": false, "explanation": "搭配：“在身体的最上面”只用于上部的部位，脚趾位于最下端，不能这样说。"}], "explanations": {"头部": "“头部”是身体最上面的部分，与“在身体的最上面”相符。", "脚": "语义：脚在身体最下面，与“最上面”正好相反。", "腰": "语义：腰在身体中部，不在最上面。", "脚趾": "搭配：“在身体的最上面”只用于上部的部位，脚趾位于最下端，不能这样说。"}, "sentence_index": 0, "correct_answer": "头部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他剪短了头部。", "explanation": "这里应该用〈头发〉。剪的是头发，头部指整个部位，不能剪短。"}, {"text": "他戴上头部，出门了。", "explanation": "这里应该用〈帽子〉。戴的是帽子，头部是身体部位，不能戴。"}, {"text": "他睁开头部看了看。", "explanation": "这里应该用〈眼睛〉。能睁开的是眼睛，头部不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头部", "is_correct": true, "explanation": "“头部”是身体的一部分，人的身上有头发、耳朵和脸，与句意相符。"}, {"text": "手", "is_correct": false, "explanation": "语义：手上没有头发、耳朵和脸，不能这样描述。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“有”后接的是身体部位，“声音”不能有头发、耳朵和脸。"}, {"text": "脖子", "is_correct": false, "explanation": "语义：脖子上没有耳朵和脸，与句子描述的对象不符。"}], "explanations": {"头部": "“头部”是身体的一部分，人的身上有头发、耳朵和脸，与句意相符。", "手": "语义：手上没有头发、耳朵和脸，不能这样描述。", "声音": "搭配：“有”后接的是身体部位，“声音”不能有头发、耳朵和脸。", "脖子": "语义：脖子上没有耳朵和脸，与句子描述的对象不符。"}, "sentence_index": 6, "correct_answer": "头部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有远大的头部。", "explanation": "这里应该用〈理想〉。理想是心中的目标，头部是身体部位，不能说远大。"}, {"text": "他做了一个头部。", "explanation": "这里应该用〈梦〉。做的是梦，头部是身体部位，不能做。"}, {"text": "他讲了一个头部。", "explanation": "这里应该用〈故事〉。讲的是故事，头部是身体部位，不能讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张图的很头部画得很清楚。", "corrected_sentence": "这张图的头部画得很清楚。", "error_description": "“很”是程度副词，不能直接修饰名词“头部”；应删去“头部”前面的“很”，说“这张图的头部画得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生检查过他的头部们。", "corrected_sentence": "医生检查过他的头部。", "error_description": "“们”只能用在指人的名词或代词之后，不能加在“头部”后；应删去“们”，说“医生检查过他的头部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
