INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96120, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物的头所在的部位。", "primary_collocate": null, "pronunciation": "tóu bù", "ipa": "tʰoʊ˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "他的头部受了伤。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只狗的头部是白色的。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑车要保护好头部。", "target_word": "头部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生检查了病人的头部。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鸟的头部有一圈红色的羽毛。", "target_word": "头部", "complexity_tier": "T3", "furigana": "zhè zhǒng niǎo de tóu bù yǒu yì quān hóng sè de yǔ máo", "sentence_source": "generated"}, {"text": "球打到了他的头部，他很疼。", "target_word": "头部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫的头部很小，身体却很大。", "target_word": "头部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的头部没有大问题。", "target_word": "头部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里，这匹马的头部很漂亮。", "target_word": "头部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时要小心，别伤到头部。", "target_word": "头部", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭部", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或动物头所在的身体部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '985b8fb7-0352-4226-b681-027abeaba146') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头部", "is_correct": true, "explanation": "“头部”指头的部位，可以受伤，与“他的”和“受了伤”搭配。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高指身体的高矮，不能说“受了伤”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的品质，不是身体部位，无法受伤。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：身材指身体的胖瘦和样子，不能说“受了伤”。"}], "explanations": {"头部": "“头部”指头的部位，可以受伤，与“他的”和“受了伤”搭配。", "身高": "搭配：身高指身体的高矮，不能说“受了伤”。", "性格": "语义：性格是人的品质，不是身体部位，无法受伤。", "身材": "搭配：身材指身体的胖瘦和样子，不能说“受了伤”。"}, "sentence_index": 0, "correct_answer": "头部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头部白了。", "explanation": "这里应该用〈头发〉。头部指整个头的部位，不能说它变白；头发变白要用“头发”。"}, {"text": "他的头部很聪明。", "explanation": "这里应该用〈头脑〉。头部是身体部位，不能说聪明；表示智力要用“头脑”。"}, {"text": "他摇了摇头部，表示不同意。", "explanation": "这里应该用〈脑袋〉。头部是书面和医学用语，不用于表示“不同意”的摇动动作；口语中说“摇脑袋”更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头部", "is_correct": true, "explanation": "“头部”是身体的一部分，可以说“小”，与“身体却很大”形成对比。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不能说“很小”，与“身体却很大”也对不上。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温说高低，不说“很小”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：名字不说大小，“很小”用在这里不通。"}], "explanations": {"头部": "“头部”是身体的一部分，可以说“小”，与“身体却很大”形成对比。", "颜色": "搭配：颜色不能说“很小”，与“身体却很大”也对不上。", "体温": "搭配：体温说高低，不说“很小”。", "名字": "搭配：名字不说大小，“很小”用在这里不通。"}, "sentence_index": 6, "correct_answer": "头部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他张开头部说话。", "explanation": "这里应该用〈嘴〉。说话时张开的是嘴，头部太笼统，不能这样用。"}, {"text": "他戴着头部去上学。", "explanation": "这里应该用〈头盔〉。戴在头上的是头盔或帽子，头部是身体部位，不能戴。"}, {"text": "这件事一直留在他的头部里。", "explanation": "这里应该用〈脑海〉。事情留在心里要说脑海，头部是身体部位，不能当作记忆的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他摔倒后，很头部疼。", "corrected_sentence": "他摔倒后，头部疼。", "error_description": "“很”是程度副词，不能直接修饰名词“头部”；删去“很”即可，说“他摔倒后，头部疼。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的的头部撞到了池壁。", "corrected_sentence": "他的头部撞到了池壁。", "error_description": "“的”多出一个；“他的”后只需一个“的”，应删去多余的“的”，说“他的头部撞到了池壁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
