INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一层是楼房最下面的那一层。", "primary_collocate": null, "pronunciation": "yì céng", "ipa": "i˥˩ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我家住在一层。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一层是商店，二层是饭店。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯到一层了。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一层等你。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的一层有银行。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一层太吵，我想住高一点。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到一层的大厅来。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一层的房间有小院子。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先去一层买水果。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一层的门口有两只猫。", "target_word": "一层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一層", "label": "繁体"}], "register": "通用", "sense_fingerprint": "楼房最下面的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大厅", "is_correct": false, "explanation": "搭配：“住在”后面要接居住的场所，“大厅”是公共场所，不能说住在大厅。"}, {"text": "一层", "is_correct": true, "explanation": "正确：“一层”指楼房最下面的一层，可以作“住在”的处所。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”是运送人的设备，不是居住的地方，“住在电梯”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，句子说的是“家”住的楼层，与厨房的意思不符。"}], "explanations": {"大厅": "搭配：“住在”后面要接居住的场所，“大厅”是公共场所，不能说住在大厅。", "一层": "正确：“一层”指楼房最下面的一层，可以作“住在”的处所。", "电梯": "语义：“电梯”是运送人的设备，不是居住的地方，“住在电梯”说不通。", "厨房": "语义：“厨房”是做饭的地方，句子说的是“家”住的楼层，与厨房的意思不符。"}, "sentence_index": 0, "correct_answer": "一层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在一层的顶楼，每天要爬十几层台阶。", "explanation": "“一层”指楼房最下面的一层，不可能是顶楼；这里把它用成了最高层的意思。"}, {"text": "这栋楼的一层是地下室，比地面还低。", "explanation": "“一层”是地面上的第一层，这里把它用成了地下的意思。"}, {"text": "他每次都在一层拿到第一名。", "explanation": "“一层”只表示楼房的最下层，这里把它用成了比赛名次或等级的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阳台", "is_correct": false, "explanation": "语义：“阳台”是楼房外的平台，里面没有大厅，“阳台的大厅”说不通。"}, {"text": "一层", "is_correct": true, "explanation": "正确：“一层的大厅”指楼房第一层的大厅，修饰语搭配得当。"}, {"text": "院子", "is_correct": false, "explanation": "语义：“院子”是房前屋后的空地，不会有大厅，“院子的大厅”说不通。"}, {"text": "卫生间", "is_correct": false, "explanation": "搭配：“卫生间”与“大厅”不搭配，“卫生间的大厅”这种修饰关系不成立。"}], "explanations": {"阳台": "语义：“阳台”是楼房外的平台，里面没有大厅，“阳台的大厅”说不通。", "一层": "正确：“一层的大厅”指楼房第一层的大厅，修饰语搭配得当。", "院子": "语义：“院子”是房前屋后的空地，不会有大厅，“院子的大厅”说不通。", "卫生间": "搭配：“卫生间”与“大厅”不搭配，“卫生间的大厅”这种修饰关系不成立。"}, "sentence_index": 6, "correct_answer": "一层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的一层是最高的一层。", "explanation": "这里把“一层”用成了最高位置的意思；“一层”只指楼房最下面的一层。"}, {"text": "这栋楼的一层比顶楼还高。", "explanation": "这里把“一层”用成了楼层很高的意思；“一层”只指楼房最下面的一层，位置上不可能高于顶层。"}, {"text": "我们在一层的最顶层开会。", "explanation": "这里把“一层”用成了最高处的意思；“一层”只指最下面的一层，不能用在顶层的位置上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市一层。", "corrected_sentence": "这家超市在一层。", "error_description": "错误：漏掉了“在”。处所词“一层”前需要用“在”引出地点，应说“这家超市在一层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你在的一层门口等我。", "corrected_sentence": "请你在一层门口等我。", "error_description": "错误：“的”放在了“一层”之前，多了一个“的”。正确：应说“在一层门口”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
