INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "受欢迎是大家都喜欢你，愿意和你在一起。", "primary_collocate": null, "pronunciation": "shòu huān yíng", "ipa": "ʂou̯˥˩ xwan˥ iŋ˧˥", "syllable_count": 3, "sentences": [{"text": "他很会说话，所以很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李爱笑，在班上很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对人友好，在公司很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想受欢迎，就要多帮助别人。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁在你们班最受欢迎？", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱说谎的人不受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会讲笑话，每次聚会都很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的老师很受欢迎，每天都有学生来问问题。", "target_word": "受欢迎", "complexity_tier": "T3", "furigana": "shòu huānyíng", "sentence_source": "generated"}, {"text": "我弟弟很受欢迎，朋友很多。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人太自私，就不会受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不受欢迎", "label": "否定"}, {"form": "最受欢迎", "label": "最高级"}], "register": "中性", "sense_fingerprint": "受欢迎：人被大家喜欢，愿意相处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82205d4-7b8d-4232-8d7a-689624c1de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受欢迎", "is_correct": true, "explanation": "符合语境：前半句“很会说话”说明他受人喜欢，「很受欢迎」顺接。"}, {"text": "木讷", "is_correct": false, "explanation": "语义：“木讷”形容人不善言辞，与“很会说话”矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，与“会说话”没有关系，句子不通。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不能用来形容人。"}], "explanations": {"受欢迎": "符合语境：前半句“很会说话”说明他受人喜欢，「很受欢迎」顺接。", "木讷": "语义：“木讷”形容人不善言辞，与“很会说话”矛盾。", "矮小": "体貌：“矮小”形容身材，与“会说话”没有关系，句子不通。", "陡峭": "搭配：“陡峭”形容地势，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "受欢迎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的呼吸很受欢迎。", "explanation": "这里应该用〈平稳〉。受欢迎说的是人被大家喜欢，不用来形容呼吸的状态。"}, {"text": "他的牙齿很受欢迎。", "explanation": "这里应该用〈整齐〉。受欢迎说的是人被大家喜欢，不用来形容牙齿的样子。"}, {"text": "他的眼睛很受欢迎。", "explanation": "这里应该用〈明亮〉。受欢迎说的是人被大家喜欢，不用来形容眼睛的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受欢迎", "is_correct": true, "explanation": "符合语境：「会讲笑话」「每次聚会」都说明他被大家喜欢，「很受欢迎」恰当。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”与“会讲笑话”的表现相反，句子前后矛盾。"}, {"text": "古雅", "is_correct": false, "explanation": "语域：“古雅”是书面或文学用语，不用于这样的日常描述。"}, {"text": "愚笨", "is_correct": false, "explanation": "语义：“愚笨”说人的智力，与“会讲笑话”的表现矛盾。"}], "explanations": {"受欢迎": "符合语境：「会讲笑话」「每次聚会」都说明他被大家喜欢，「很受欢迎」恰当。", "沉默": "语义：“沉默”与“会讲笑话”的表现相反，句子前后矛盾。", "古雅": "语域：“古雅”是书面或文学用语，不用于这样的日常描述。", "愚笨": "语义：“愚笨”说人的智力，与“会讲笑话”的表现矛盾。"}, "sentence_index": 6, "correct_answer": "受欢迎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很受欢迎。", "explanation": "这里应该用〈红润〉。受欢迎说的是人被大家喜欢，不用来形容脸色。"}, {"text": "他的身高很受欢迎。", "explanation": "这里应该用〈高〉。受欢迎不用来说身高的高矮。"}, {"text": "她受欢迎地站了起来。", "explanation": "这里应该用〈高兴〉。受欢迎表示被大家喜爱，不能用来描述动作的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很被受欢迎。", "corrected_sentence": "他很受欢迎。", "error_description": "错误：“很被受欢迎”；正确：“很受欢迎”。“受”已含被动义，再加“被”属于重复，应删去“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很受欢迎老师，学生都喜欢他。", "corrected_sentence": "这位很受欢迎的老师，学生都喜欢他。", "error_description": "错误：“很受欢迎老师”；正确：“很受欢迎的老师”。“受欢迎”作定语修饰名词时，后面需要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
