INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96162, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "得到大家喜爱和接受。", "primary_collocate": null, "pronunciation": "shòu huān yíng", "ipa": "ʂou̯˥˩ xwan˥ iŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这本书在年轻人中很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜非常受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的新歌在网上很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，冰淇淋特别受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏为什么这么受欢迎？", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影在国外也很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小车不太受欢迎，卖得很少。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年最受欢迎的礼物是什么？", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旅游路线最近很受欢迎。", "target_word": "受欢迎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不受欢迎", "label": "否定"}, {"form": "最受欢迎", "label": "最高级"}], "register": "中性", "sense_fingerprint": "受欢迎：事物被大家喜爱和接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82205d4-7b8d-4232-8d7a-689624c1de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受欢迎", "is_correct": true, "explanation": "符合语境：「很受欢迎」说这本书被年轻人喜爱，与“在年轻人中”相符。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”形容人年纪大，与“年轻人”矛盾，不能用来形容这本书。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”说的是人的感受，书不会感到寂寞，句子不通。"}, {"text": "狡猾", "is_correct": false, "explanation": "搭配：“狡猾”用来形容人或动物的性格，不能用来形容书。"}], "explanations": {"受欢迎": "符合语境：「很受欢迎」说这本书被年轻人喜爱，与“在年轻人中”相符。", "年迈": "语义：“年迈”形容人年纪大，与“年轻人”矛盾，不能用来形容这本书。", "寂寞": "语义：“寂寞”说的是人的感受，书不会感到寂寞，句子不通。", "狡猾": "搭配：“狡猾”用来形容人或动物的性格，不能用来形容书。"}, "sentence_index": 0, "correct_answer": "受欢迎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很受欢迎。", "explanation": "这里应该用〈好〉。受欢迎说的是事物被大家喜爱和接受，不用来评价人的脾气好坏。"}, {"text": "这次考试的成绩很受欢迎。", "explanation": "这里应该用〈理想〉。受欢迎只说人或事物被大家喜爱，不用来评价成绩的高低。"}, {"text": "他受欢迎地走进了教室。", "explanation": "这里应该用〈高兴〉。受欢迎说的是事物被大家喜爱，不能表示人的心情或动作方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受欢迎", "is_correct": true, "explanation": "符合语境：这部电影在国外也受到喜爱，「很受欢迎」正合适。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不用来形容电影。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”通常形容山坡或道路，不能用来说电影。"}, {"text": "贫穷", "is_correct": false, "explanation": "语义：“贫穷”说人或地区的经济状况，电影不能是贫穷的。"}], "explanations": {"受欢迎": "符合语境：这部电影在国外也受到喜爱，「很受欢迎」正合适。", "矮小": "体貌：“矮小”形容身材，不用来形容电影。", "陡峭": "搭配：“陡峭”通常形容山坡或道路，不能用来说电影。", "贫穷": "语义：“贫穷”说人或地区的经济状况，电影不能是贫穷的。"}, "sentence_index": 6, "correct_answer": "受欢迎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的天气很受欢迎。", "explanation": "这里应该用〈舒服〉。受欢迎说的是被大家喜爱，不用来描述天气的舒适程度。"}, {"text": "这次活动受欢迎地推迟了。", "explanation": "这里应该用〈推迟〉。受欢迎是形容词，表示被大家喜爱，不能用来修饰“推迟”这类动作。"}, {"text": "这个房间的面积很受欢迎。", "explanation": "这里应该用〈宽敞〉。受欢迎不用来描述面积的大小，应说房间「很宽敞」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款包包受欢迎不，卖得很慢。", "corrected_sentence": "这款包包不受欢迎，卖得很慢。", "error_description": "语序错误：否定副词“不”要放在“受欢迎”前面，应说“不受欢迎”，不能放在后面说“受欢迎不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种很受欢迎手机，卖得很快。", "corrected_sentence": "这种很受欢迎的手机，卖得很快。", "error_description": "错误：“很受欢迎手机”；正确：“很受欢迎的手机”。“受欢迎”作定语修饰名词时，后面需要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
