INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96169, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "境界是一个人的想法或本领达到的高度。", "primary_collocate": null, "pronunciation": "jìng jiè", "ipa": "tɕiŋ˥˩ tɕje˥˩", "syllable_count": 2, "sentences": [{"text": "他的书法已经到了很高的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的教学境界让我佩服。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习外语要追求更高的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钢琴水平达到了新的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人做事，都有不同的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画已经进入了一种新境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法比我们高一个境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练了十年，他的太极拳进入了新境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位棋手的棋艺已经是另一种境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想达到老师那样的境界。", "target_word": "境界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种境界", "label": "量词"}, {"form": "一个境界", "label": "量词"}], "register": "书面", "sense_fingerprint": "人的想法或本领所达到的高度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82205d4-7b8d-4232-8d7a-689624c1de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "境界", "is_correct": true, "explanation": "正确：听到的是“境界”（jìngjiè），指人的思想或本领所达到的高度。"}, {"text": "竞价", "is_correct": false, "explanation": "第二音节 jià 与 jiè 韵母不同，“竞价”意思是竞争出价。"}, {"text": "定界", "is_correct": false, "explanation": "dìng 与 jìng 声母不同（d 与 j），“定界”意思是划定边界。"}, {"text": "警戒", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，“警戒”意思是戒备、警惕。"}, {"text": "竞技", "is_correct": false, "explanation": "第二音节 jì 与 jiè 的区别在韵母（少了 e 音），“竞技”意思是体育比赛。"}], "explanations": {"境界": "正确：听到的是“境界”（jìngjiè），指人的思想或本领所达到的高度。", "竞价": "第二音节 jià 与 jiè 韵母不同，“竞价”意思是竞争出价。", "定界": "dìng 与 jìng 声母不同（d 与 j），“定界”意思是划定边界。", "警戒": "jǐng（第三声）与 jìng（第四声）声调不同，“警戒”意思是戒备、警惕。", "竞技": "第二音节 jì 与 jiè 的区别在韵母（少了 e 音），“竞技”意思是体育比赛。"}, "sentence_index": null, "correct_answer": "境界"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”没有高低之分，“很高的颜色”说不通。"}, {"text": "境界", "is_correct": true, "explanation": "正确：“很高的境界”指书法达到的高度，与句中“书法已经到了”相合。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“行李”不能用“很高的”修饰，与“书法”的造诣无关。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不表示达到的高度，与书法的水平不合。"}], "explanations": {"颜色": "语义：“颜色”没有高低之分，“很高的颜色”说不通。", "境界": "正确：“很高的境界”指书法达到的高度，与句中“书法已经到了”相合。", "行李": "搭配：“行李”不能用“很高的”修饰，与“书法”的造诣无关。", "作业": "语义：“作业”不表示达到的高度，与书法的水平不合。"}, "sentence_index": 0, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他陷入了困难的境界，很久走不出来。", "explanation": "这里应该用〈境地〉。“境界”指思想或本领达到的高度，不能说“陷入”它，处于困境要用〈境地〉。"}, {"text": "事故造成的损失达到了严重的境界。", "explanation": "这里应该用〈程度〉。“境界”指思想或本领的高度，损失的严重程度要用〈程度〉。"}, {"text": "这件衣服的境界很大，穿着不合身。", "explanation": "这里应该用〈尺寸〉。“境界”指思想或本领达到的高度，衣服的大小要用〈尺寸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：“房间”不能比较高低，“高一个房间”说不通。"}, {"text": "境界", "is_correct": true, "explanation": "正确：“高一个境界”指想法的层次高出一级，与“比我们”的比较相合。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”是时间段，不能说“高”。"}, {"text": "盘子", "is_correct": false, "explanation": "搭配：“盘子”不能用来比较“想法”的高低。"}], "explanations": {"房间": "语义：“房间”不能比较高低，“高一个房间”说不通。", "境界": "正确：“高一个境界”指想法的层次高出一级，与“比我们”的比较相合。", "学期": "语义：“学期”是时间段，不能说“高”。", "盘子": "搭配：“盘子”不能用来比较“想法”的高低。"}, "sentence_index": 6, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司的境界很高。", "explanation": "这里应该用〈地位〉。“境界”指思想或本领达到的高度，职位的高低要用〈地位〉。"}, {"text": "气球一直升到很高的境界。", "explanation": "这里应该用〈高度〉。“境界”不指物体的高低，气球升起的高低要用〈高度〉。"}, {"text": "这次考试他取得了很好的境界。", "explanation": "这里应该用〈成绩〉。“境界”不指考试得分，考试的成绩要用〈成绩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的琴艺已经达到了一条很高的境界。", "corrected_sentence": "她的琴艺已经达到了一种很高的境界。", "error_description": "量词错误：“境界”应搭配“种”或“个”，“条”用于细长的东西，不能修饰“境界”。正确为“一种很高的境界”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大师的修养我们高出一个境界。", "corrected_sentence": "这位大师的修养比我们高出一个境界。", "error_description": "主语错位：「我们」被当作主语，句意变成「我们」比大师高出一个境界，与原意相反；比较句应说「比我们高出一个境界」，用「比」引出比较对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
