INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妓女是靠出卖身体来赚钱的女人。", "primary_collocate": null, "pronunciation": "jì nǚ", "ipa": "tɕi˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "书中的妓女靠这份工作养活家人。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧社会的妓女生活非常苦。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想帮助那些妓女找新工作。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者采访过一些妓女。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说自己不想再做妓女了。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个妓女每天晚上都在街上等人。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许有人强迫妓女接客。", "target_word": "妓女", "complexity_tier": "T3", "furigana": "fǎ lǜ bù yǔn xǔ yǒu rén qiáng pò jì nǚ jiē kè。", "sentence_source": "generated"}, {"text": "妓女也是人，她们也想过好日子。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老电影里常有妓女这样的人物。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会组织帮助妓女学习新的本领。", "target_word": "妓女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个妓女", "label": "量词"}, {"form": "一名妓女", "label": "量词"}], "register": "书面", "sense_fingerprint": "靠出卖身体赚钱的女人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82205d4-7b8d-4232-8d7a-689624c1de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96175, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妓女", "is_correct": true, "explanation": "正确。读作 jì nǚ，意思是靠出卖身体赚钱的女人。"}, {"text": "侄女", "is_correct": false, "explanation": "zhí（第二声）与 jì（第四声）声母和声调都不同，意思是侄女。"}, {"text": "义女", "is_correct": false, "explanation": "yì 与 jì 声母不同（y/j），声调相同，意思是认作的女儿。"}, {"text": "纪律", "is_correct": false, "explanation": "lǜ（第四声）与 nǚ（第三声）声母不同（l/n）且声调不同，意思是规章制度。"}, {"text": "寄语", "is_correct": false, "explanation": "yǔ 与 nǚ 声母不同（y/n），声调相同，意思是托人转达的话。"}], "explanations": {"妓女": "正确。读作 jì nǚ，意思是靠出卖身体赚钱的女人。", "侄女": "zhí（第二声）与 jì（第四声）声母和声调都不同，意思是侄女。", "义女": "yì 与 jì 声母不同（y/j），声调相同，意思是认作的女儿。", "纪律": "lǜ（第四声）与 nǚ（第三声）声母不同（l/n）且声调不同，意思是规章制度。", "寄语": "yǔ 与 nǚ 声母不同（y/n），声调相同，意思是托人转达的话。"}, "sentence_index": null, "correct_answer": "妓女"}, "level_3": {"options": [{"text": "妓女", "is_correct": true, "explanation": "正确。“靠这份工作养活家人”的正是靠出卖身体赚钱的女人。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝不需要靠工作养活家人，与“靠这份工作”矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“养活家人”的主体须是能工作的人，小猫不能充当。"}, {"text": "公主", "is_correct": false, "explanation": "语义：公主不靠工作赚钱，与“靠这份工作养活家人”矛盾。"}], "explanations": {"妓女": "正确。“靠这份工作养活家人”的正是靠出卖身体赚钱的女人。", "皇帝": "语义：皇帝不需要靠工作养活家人，与“靠这份工作”矛盾。", "小猫": "配价：“养活家人”的主体须是能工作的人，小猫不能充当。", "公主": "语义：公主不靠工作赚钱，与“靠这份工作养活家人”矛盾。"}, "sentence_index": 0, "correct_answer": "妓女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者采访过一株妓女。", "explanation": "这里应该用〈个〉。妓女指人，量词要用“个”或“位”，“株”只用于植物。"}, {"text": "记者采访过一台妓女。", "explanation": "这里应该用〈个〉。“台”用于机器等物品，不能用来指人。"}, {"text": "记者采访过一辆妓女。", "explanation": "这里应该用〈个〉。“辆”用于车辆，妓女是人，不能用它来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96175, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "妓女", "is_correct": true, "explanation": "正确。读作 jì nǚ，意思是靠出卖身体赚钱的女人。"}, {"text": "子女", "is_correct": false, "explanation": "zǐ（第三声）与 jì（第四声）声母和声调都不同，意思是子女。"}, {"text": "侍女", "is_correct": false, "explanation": "shì 与 jì 声母不同（sh/j），声调相同，意思是在身边服侍的女子。"}, {"text": "妻女", "is_correct": false, "explanation": "qī（第一声）与 jì（第四声）声母不同（q/j）、声调也不同，意思是妻子和女儿。"}, {"text": "婢女", "is_correct": false, "explanation": "bì 与 jì 声母不同（b/j），声调相同，意思是旧时的女仆。"}], "explanations": {"妓女": "正确。读作 jì nǚ，意思是靠出卖身体赚钱的女人。", "子女": "zǐ（第三声）与 jì（第四声）声母和声调都不同，意思是子女。", "侍女": "shì 与 jì 声母不同（sh/j），声调相同，意思是在身边服侍的女子。", "妻女": "qī（第一声）与 jì（第四声）声母不同（q/j）、声调也不同，意思是妻子和女儿。", "婢女": "bì 与 jì 声母不同（b/j），声调相同，意思是旧时的女仆。"}, "sentence_index": null, "correct_answer": "妓女"}, "level_3": {"options": [{"text": "妓女", "is_correct": true, "explanation": "正确。被强迫“接客”的正是以出卖身体为生的女子。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是购买服务的人，不会被强迫“接客”，与语境不符。"}, {"text": "小狗", "is_correct": false, "explanation": "配价：“强迫”的对象须能被要求接客，小狗不能充当该角色。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察不以“接客”为职业，与语境不符。"}], "explanations": {"妓女": "正确。被强迫“接客”的正是以出卖身体为生的女子。", "顾客": "语义：顾客是购买服务的人，不会被强迫“接客”，与语境不符。", "小狗": "配价：“强迫”的对象须能被要求接客，小狗不能充当该角色。", "警察": "语义：警察不以“接客”为职业，与语境不符。"}, "sentence_index": 6, "correct_answer": "妓女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了升职，甘当政治妓女，出卖了自己的立场。", "explanation": "这里用的是比喻义：“政治妓女”指为了利益出卖立场、迎合权势的人，不指以出卖身体为生的女子。"}, {"text": "她是一名妓女，专门替弱者打官司。", "explanation": "这里应该用〈女律师〉。妓女指以出卖身体为生的女子，不指替人打官司的律师。"}, {"text": "这位妓女采访了市长，写成了一篇长报道。", "explanation": "这里应该用〈女记者〉。妓女指以出卖身体为生的女子，不指采访并写报道的记者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位妓女们很善良。", "corrected_sentence": "那位妓女很善良。", "error_description": "错误在于“那位”与“们”同时使用：“那位”表示单数的敬称，“们”表示复数，二者不能搭配。应说“那位妓女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会组织为每一只妓女提供培训。", "corrected_sentence": "社会组织为每一个妓女提供培训。", "error_description": "错误：“每一只妓女”；正确：“每一个妓女”。“只”多用于动物等，妓女是人，量词应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d16b5b-91fb-48aa-97b5-fc1cb2fcb482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
