INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96185, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "座位是可以坐的地方。", "primary_collocate": null, "pronunciation": "zuò wèi", "ipa": "tsuo˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "电影院里的座位很舒服，我们坐了三个小时。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个座位有人吗？我可以坐这里吗？", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车上我的座位靠着窗户。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书包放在旁边的座位上。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的座位都坐满了。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人上车后，年轻人给他让了座位。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的座位在第三排，看得很清楚。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按照票上的号码找座位。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭馆里没有空座位，我们只好等一等。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢坐在妈妈旁边的座位上。", "target_word": "座位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座位号", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以坐的地方，如教室、电影院、火车里的座位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96185, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "座位", "is_correct": true, "explanation": "座位是供人坐的地方，既能“很舒服”，又能“坐了三个小时”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用品，不能使人感到“舒服”，与“很舒服”冲突。"}, {"text": "黑板", "is_correct": false, "explanation": "配价：“坐了三个小时”要求可以坐的对象，黑板不能用来坐。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是用来吃的，不能用“坐”来计时，与“坐了三个小时”冲突。"}], "explanations": {"座位": "座位是供人坐的地方，既能“很舒服”，又能“坐了三个小时”。", "课本": "语义：课本是学习用品，不能使人感到“舒服”，与“很舒服”冲突。", "黑板": "配价：“坐了三个小时”要求可以坐的对象，黑板不能用来坐。", "饭菜": "语义：饭菜是用来吃的，不能用“坐”来计时，与“坐了三个小时”冲突。"}, "sentence_index": 0, "correct_answer": "座位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块黑板的座位在教室中间。", "explanation": "这里应该用〈位置〉。座位指供人坐的地方，物品所在的位置要用位置。"}, {"text": "他在公司的座位很高。", "explanation": "这里应该用〈职位〉。座位指供人坐的地方，工作的级别要用职位。"}, {"text": "我买了一只座位。", "explanation": "这里应该用〈个〉。座位要用“个”计量，“只”用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座位", "is_correct": true, "explanation": "座位是供人坐的位子，“在第三排”和“看得很清楚”都说得通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能说“我们的窗户在第三排”指人的位置。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体数据，不是位置，与“在第三排”冲突。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”没有位置义，不能用“我们的价格在第三排”来说。"}], "explanations": {"座位": "座位是供人坐的位子，“在第三排”和“看得很清楚”都说得通。", "窗户": "语义：窗户是建筑部件，不能说“我们的窗户在第三排”指人的位置。", "身高": "语义：身高是身体数据，不是位置，与“在第三排”冲突。", "价格": "搭配：“价格”没有位置义，不能用“我们的价格在第三排”来说。"}, "sentence_index": 6, "correct_answer": "座位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个座位能坐二十个人。", "explanation": "这里应该用〈包间〉。座位只供一人坐，不能指能坐二十人的地方。"}, {"text": "他住在座位里。", "explanation": "这里应该用〈宿舍〉。座位只是供人坐的地方，不能用来住。"}, {"text": "这个座位很会唱歌。", "explanation": "这里应该用〈歌手〉。座位是供人坐的地方，不能唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一张座位，就坐下了。", "corrected_sentence": "我找到了一个座位，就坐下了。", "error_description": "“座位”计量用“个”，“张”用于纸、票等扁平的东西，应为“一个座位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个座位是我，请你换一个。", "corrected_sentence": "这个座位是我的，请你换一个。", "error_description": "“座位”是物，不能直接说“是我”；表示所属应说“是我的”，应为“这个座位是我的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
