INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96197, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "感兴趣是觉得这件事有意思，想知道更多。", "primary_collocate": null, "pronunciation": "gǎn xìng qù", "ipa": "kan˨˩˦ ɕiŋ˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "我对历史很感兴趣。", "target_word": "感兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你对什么运动感兴趣？", "target_word": "感兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟对做饭一点儿也不感兴趣。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对中国音乐很感兴趣，常常听。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这本书感兴趣，可以借我吗？", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明对动物特别感兴趣，想当医生。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对这个工作感兴趣的人可以给我打电话。", "target_word": "感兴趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么对学中文感兴趣？", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以前对画画不感兴趣，现在很喜欢。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对新来的老师很感兴趣，问了很多问题。", "target_word": "感兴趣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不感兴趣", "label": "否定"}, {"form": "感興趣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对某事觉得有意思、想了解更多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：「吃」不能接「历史」，「对历史很吃」不通。"}, {"text": "感兴趣", "is_correct": true, "explanation": "正确：「感兴趣」表示对历史觉得有意思，可以被「很」修饰。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」是不及物动词，不能带「对历史」的对象。"}, {"text": "没兴趣", "is_correct": false, "explanation": "搭配：「没兴趣」不能被「很」修饰，「很没兴趣」不通。"}], "explanations": {"吃": "语义：「吃」不能接「历史」，「对历史很吃」不通。", "感兴趣": "正确：「感兴趣」表示对历史觉得有意思，可以被「很」修饰。", "睡": "配价：「睡」是不及物动词，不能带「对历史」的对象。", "没兴趣": "搭配：「没兴趣」不能被「很」修饰，「很没兴趣」不通。"}, "sentence_index": 0, "correct_answer": "感兴趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对去世的爷爷很感兴趣，每天都哭着说想他。", "explanation": "这里应该用〈思念〉。感兴趣表示有兴趣想了解，每天哭着想念去世的爷爷应说思念。"}, {"text": "我对打雷很感兴趣，一打雷就躲进被子里。", "explanation": "这里应该用〈害怕〉。感兴趣是有兴趣，一打雷就躲进被子说明是害怕。"}, {"text": "我对这种广告很感兴趣，看见就生气。", "explanation": "这里应该用〈反感〉。感兴趣表示有兴趣，看见就生气表示反感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：「对这个工作睡觉的人」意思荒谬，睡觉和工作没有关系。"}, {"text": "感兴趣", "is_correct": true, "explanation": "正确：「感兴趣」修饰「的人」，指对这个工作有兴趣的人。"}, {"text": "吃饱", "is_correct": false, "explanation": "语义：「吃饱」与「对这个工作」搭不上，句子不通。"}, {"text": "出差", "is_correct": false, "explanation": "配价：「出差」是不及物动词，不能用「对这个工作」引出对象。"}], "explanations": {"睡觉": "语义：「对这个工作睡觉的人」意思荒谬，睡觉和工作没有关系。", "感兴趣": "正确：「感兴趣」修饰「的人」，指对这个工作有兴趣的人。", "吃饱": "语义：「吃饱」与「对这个工作」搭不上，句子不通。", "出差": "配价：「出差」是不及物动词，不能用「对这个工作」引出对象。"}, "sentence_index": 6, "correct_answer": "感兴趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从小对数学很感兴趣，一看见作业就头疼。", "explanation": "这里应该用〈讨厌〉。感兴趣表示有兴趣想了解，一看见作业就头疼表示讨厌。"}, {"text": "奶奶对小时候住过的老房子很感兴趣，说起来就流泪。", "explanation": "这里应该用〈怀念〉。感兴趣表示想了解，说起来就流泪表示怀念。"}, {"text": "这个老板对加班很感兴趣，每天都抱怨。", "explanation": "这里应该用〈厌烦〉。感兴趣是有兴趣，每天抱怨加班表示厌烦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她音乐很感兴趣。", "corrected_sentence": "她对音乐很感兴趣。", "error_description": "「感兴趣」的对象要用介词「对」引出，应说「对音乐很感兴趣」，漏了「对」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对这门课很感兴趣过。", "corrected_sentence": "我对这门课很感兴趣。", "error_description": "体标与程度搭配错误：「很」表示程度，与经历体「过」不能同时修饰「感兴趣」，应说「我对这门课很感兴趣」；要说曾经，可以说「我以前对这门课感兴趣过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
