INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96198, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "对某事物有兴趣、有好感。", "primary_collocate": null, "pronunciation": "gǎn xìng qù", "ipa": "kan˨˩˦ ɕiŋ˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "他对我说的事很感兴趣。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们对新玩具都很感兴趣。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只对便宜的东西感兴趣。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都对她的故事感兴趣。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对中国菜感兴趣吗？", "target_word": "感兴趣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她对那个男孩有好感，也对他的工作感兴趣。", "target_word": "感兴趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥对汽车最感兴趣，每天都看汽车杂志。", "target_word": "感兴趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对这次旅行很感兴趣，马上买了票。", "target_word": "感兴趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是感兴趣，我们一起去看看。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板对这个新办法不太感兴趣。", "target_word": "感兴趣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不感兴趣", "label": "否定"}, {"form": "感興趣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对某事物有兴趣、有好感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：「喝」不能接「事」，「很喝」也不通。"}, {"text": "感兴趣", "is_correct": true, "explanation": "正确：「感兴趣」表示对他说的事有兴趣，合乎句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」和「他对我说的事」搭不上，句子荒谬。"}, {"text": "出差", "is_correct": false, "explanation": "配价：「出差」是不及物动词，不能带「对我说的事」作对象。"}], "explanations": {"喝": "语义：「喝」不能接「事」，「很喝」也不通。", "感兴趣": "正确：「感兴趣」表示对他说的事有兴趣，合乎句意。", "睡觉": "语义：「睡觉」和「他对我说的事」搭不上，句子荒谬。", "出差": "配价：「出差」是不及物动词，不能带「对我说的事」作对象。"}, "sentence_index": 0, "correct_answer": "感兴趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们对新玩具很感兴趣，一拿到就扔在地上。", "explanation": "这里应该用〈厌烦〉。感兴趣表示有好感，拿到玩具就扔在地上是厌烦。"}, {"text": "他看见孩子受伤，急得直哭，他对孩子的伤很感兴趣。", "explanation": "这里应该用〈心疼〉。此义项的感兴趣表示有兴趣、有好感，对受伤的孩子表达的是心疼，不能用感兴趣。"}, {"text": "他对这种行为很感兴趣，每天都骂人。", "explanation": "这里应该用〈鄙视〉。感兴趣表示有好感，每天骂人是鄙视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：后半句「每天都看汽车杂志」与「讨厌」矛盾，不合句意。"}, {"text": "感兴趣", "is_correct": true, "explanation": "正确：「感兴趣」表示对汽车有兴趣，与「每天都看」一致。"}, {"text": "厌烦", "is_correct": false, "explanation": "语义：「厌烦」与「每天都看汽车杂志」矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」不及物，不能说「对汽车最散步」。"}], "explanations": {"讨厌": "语义：后半句「每天都看汽车杂志」与「讨厌」矛盾，不合句意。", "感兴趣": "正确：「感兴趣」表示对汽车有兴趣，与「每天都看」一致。", "厌烦": "语义：「厌烦」与「每天都看汽车杂志」矛盾。", "散步": "配价：「散步」不及物，不能说「对汽车最散步」。"}, "sentence_index": 6, "correct_answer": "感兴趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对体育很感兴趣，一上体育课就想请假。", "explanation": "这里应该用〈讨厌〉。感兴趣表示有兴趣，一上体育课就想请假是讨厌。"}, {"text": "外婆对家乡的老街很感兴趣，说起来就流泪。", "explanation": "这里应该用〈怀念〉。感兴趣表示有兴趣、有好感，说起来就流泪表示怀念。"}, {"text": "他对那件旧衣服很感兴趣，一看就扔掉。", "explanation": "这里应该用〈嫌弃〉。感兴趣表示有兴趣，一看就扔掉是嫌弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这个节目很感兴趣。", "corrected_sentence": "她对这个节目很感兴趣。", "error_description": "「感兴趣」的对象要用介词「对」引出，应说「对这个节目很感兴趣」，漏了「对」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很感兴趣的看着我。", "corrected_sentence": "他很感兴趣地看着我。", "error_description": "「感兴趣」后面修饰动词「看着」要用「地」，不能用「的」，应说「很感兴趣地看着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
