INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一地区使用的、有别于通用语的地方话。", "primary_collocate": null, "pronunciation": "fāng yán", "ipa": "faŋ˥˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个地区有自己的方言。", "target_word": "方言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "方言和普通话有很多不同。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多孩子只会说普通话，不会说方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请我们用方言说一个故事。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个地方的方言都有自己的特点。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家喜欢在书里写方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的方言比北方的复杂。", "target_word": "方言", "complexity_tier": "T3", "furigana": "fāng yán", "sentence_source": "generated"}, {"text": "学校里要说普通话，回家可以说方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把家乡的方言教给了女儿。", "target_word": "方言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去过的小城里，人们都说方言。", "target_word": "方言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种方言", "label": "量词"}, {"form": "方言区", "label": "复合"}], "register": "中性", "sense_fingerprint": "某地区使用、有别于通用语的地方话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。fāng yán 指某地区使用、有别于通用语的地方话。"}, {"text": "放言", "is_correct": false, "explanation": "放言（fàng yán）第一音节声调与 fāng 不同，意思是毫无顾忌地发表言论。"}, {"text": "放眼", "is_correct": false, "explanation": "放眼（fàng yǎn）两个音节的声调都与 fāng yán 不同，意思是向远处看。"}, {"text": "房檐", "is_correct": false, "explanation": "房檐（fáng yán）第一音节声调与 fāng 不同，意思是屋顶向外伸出的部分。"}, {"text": "方眼", "is_correct": false, "explanation": "方眼（fāng yǎn）第二音节声调与 yán 不同，意思是方形的小孔。"}], "explanations": {"方言": "正确。fāng yán 指某地区使用、有别于通用语的地方话。", "放言": "放言（fàng yán）第一音节声调与 fāng 不同，意思是毫无顾忌地发表言论。", "放眼": "放眼（fàng yǎn）两个音节的声调都与 fāng yán 不同，意思是向远处看。", "房檐": "房檐（fáng yán）第一音节声调与 fāng 不同，意思是屋顶向外伸出的部分。", "方眼": "方眼（fāng yǎn）第二音节声调与 yán 不同，意思是方形的小孔。"}, "sentence_index": null, "correct_answer": "方言"}, "level_3": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。“这个地区有自己的”后面接的是地区的语言特点，方言符合这个语境。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“有自己的”不接身体部位来指地区的特点。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：地区没有“自己的冰箱”这种说法，讲不通。"}, {"text": "三角形", "is_correct": false, "explanation": "语义：三角形是几何图形，不属于一个地区的特点。"}], "explanations": {"方言": "正确。“这个地区有自己的”后面接的是地区的语言特点，方言符合这个语境。", "手指": "搭配：“有自己的”不接身体部位来指地区的特点。", "冰箱": "语义：地区没有“自己的冰箱”这种说法，讲不通。", "三角形": "语义：三角形是几何图形，不属于一个地区的特点。"}, "sentence_index": 0, "correct_answer": "方言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份国际条约用的是一种方言。", "explanation": "这里应该用〈语言〉。国际条约需要通行的语言，方言只在某一地区通行。"}, {"text": "这门全国通用的方言，各地的人都能听懂。", "explanation": "这里应该用〈普通话〉。方言只在某一地区通行，不能说“全国通用”。"}, {"text": "他想出了一个好方言，很快解决了问题。", "explanation": "这里应该用〈方法〉。方言指地方话，不能指解决问题的办法；办法要用“方法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。“南方的方言比北方的复杂”指两地方言的差异，符合这个语境。"}, {"text": "小鸡", "is_correct": false, "explanation": "语义：小鸡不是可以比较“复杂”程度的事物，“南方的小鸡比北方的复杂”讲不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“南方的月亮比北方的复杂”讲不通，月亮不是可比较复杂程度的事物。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：星期一是日期，不是可以比较“复杂”程度的事物，讲不通。"}], "explanations": {"方言": "正确。“南方的方言比北方的复杂”指两地方言的差异，符合这个语境。", "小鸡": "语义：小鸡不是可以比较“复杂”程度的事物，“南方的小鸡比北方的复杂”讲不通。", "月亮": "语义：“南方的月亮比北方的复杂”讲不通，月亮不是可比较复杂程度的事物。", "星期一": "语义：星期一是日期，不是可以比较“复杂”程度的事物，讲不通。"}, "sentence_index": 6, "correct_answer": "方言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去过的小城里，人们都说一架方言。", "explanation": "这里应该用〈种〉。〈架〉用于飞机、机器等有架子的东西，方言要用“一种方言”。"}, {"text": "我们去过的小城里，人们都说一张方言。", "explanation": "这里应该用〈种〉。〈张〉用于纸、桌子等平面的东西，不能用来数方言。"}, {"text": "我们去过的小城里，人们都说一本方言。", "explanation": "这里应该用〈种〉。〈本〉用于书籍、本子，方言要用“一种方言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶总是说的方言。", "corrected_sentence": "奶奶总是说方言。", "error_description": "结构助词错误：“说方言”是动宾结构作谓语，中间不能插入“的”；“说的方言”是定语结构，不能单独作谓语。正确说法是“奶奶总是说方言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会说一条方言，很难懂。", "corrected_sentence": "他会说一种方言，很难懂。", "error_description": "量词错误：“方言”应该用量词“种”，不能用“条”。正确说法是“一种方言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
