INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个地区统一使用的标准计时制度。", "primary_collocate": null, "pronunciation": "biāo zhǔn shí", "ipa": "piɑʊ̯˥ ʈʂuən˨˩˦ ʂʐ̩˧˥", "syllable_count": 3, "sentences": [{"text": "中国虽然很大，但全国只用一个标准时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天过后，这里又改回标准时了。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国东部的标准时比北京晚十三个小时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国很大，国内分成好几个标准时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天用标准时，夏天用夏令时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的标准时是东八区时间。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律规定，全国都要用同一种标准时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本和韩国的标准时一样，都比北京快一小时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去英国时，手机会自动改成那里的标准时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家改了标准时，所有的钟都要重新调。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "标准时间", "label": "复合"}], "register": "中性", "sense_fingerprint": "标准时：某个地区统一规定使用的计时制度，与夏令时相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准时", "is_correct": true, "explanation": "正确。“全国只用一个”后面接的是全国统一使用的计时制度，标准时符合这个语境。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯不是计时制度，全国不能“只用一个地毯”来计时。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭不是计时制度，全国不会“只用一个晚饭”来计时，讲不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“只用一个”的对象应是计时制度，冰箱与计时无关。"}], "explanations": {"标准时": "正确。“全国只用一个”后面接的是全国统一使用的计时制度，标准时符合这个语境。", "地毯": "语义：地毯不是计时制度，全国不能“只用一个地毯”来计时。", "晚饭": "语义：晚饭不是计时制度，全国不会“只用一个晚饭”来计时，讲不通。", "冰箱": "搭配：“只用一个”的对象应是计时制度，冰箱与计时无关。"}, "sentence_index": 0, "correct_answer": "标准时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天过后，这里又改回一只标准时了。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对的东西，标准时要用“一个标准时”。"}, {"text": "法律规定，全国都要用同一把标准时。", "explanation": "这里应该用〈种〉。〈把〉用于有柄或能握住的东西，“同一种标准时”才对。"}, {"text": "美国东部的一张标准时比北京晚十三个小时。", "explanation": "这里应该用〈个〉。〈张〉用于纸、桌子等平面的东西，标准时不能用这个量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准时", "is_correct": true, "explanation": "正确。“法律规定，全国都要用同一种”后面接的是统一规定的计时制度，标准时符合这个语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以由法律统一规定使用的东西。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓不能被法律规定为全国统一使用的对象。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“同一种”不接“海洋”，海洋也不是统一规定的计时方式。"}], "explanations": {"标准时": "正确。“法律规定，全国都要用同一种”后面接的是统一规定的计时制度，标准时符合这个语境。", "天气": "语义：天气不是可以由法律统一规定使用的东西。", "草莓": "语义：草莓不能被法律规定为全国统一使用的对象。", "海洋": "搭配：“同一种”不接“海洋”，海洋也不是统一规定的计时方式。"}, "sentence_index": 6, "correct_answer": "标准时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美国和中国之间的标准时是十三个小时。", "explanation": "这里应该用〈时差〉。时差是两地之间的时间差距，标准时是一套计时制度，不表示时间的长短。"}, {"text": "墙上的标准时慢了五分钟。", "explanation": "这里应该用〈时钟〉。标准时是计时制度，不能说“标准时慢了”，说钟慢要用时钟。"}, {"text": "他的标准时很高，大家都很佩服。", "explanation": "这里应该用〈水准〉。标准时指地区的计时制度，不能用来说人的能力高；能力高低要用“水准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全国只用一把标准时。", "corrected_sentence": "全国只用一种标准时。", "error_description": "量词错误：“标准时”这里应该用量词“种”，不能用“把”。正确说法是“一种标准时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全国明年开始采用了标准时。", "corrected_sentence": "全国明年开始采用标准时。", "error_description": "时态错误：“明年”指将来，不能与表示完成的“了”搭配，这里应说“明年开始采用标准时”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
