INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海域是海里的一大片地方。", "primary_collocate": null, "pronunciation": "hǎi yù", "ipa": "xaɪ̯˨˩˦ y˥˩", "syllable_count": 2, "sentences": [{"text": "这片海域里有很多鱼。", "target_word": "海域", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "渔民出海，到远处的海域打鱼。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海域很深，船不能随便进去。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风来了，船都要离开这片海域。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海域夏天常常有大风。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家在那片海域发现了一种新鱼。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那片海域很热闹，到处都是小船。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水很清，这片海域适合潜水。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海域有很多岛，也有很多鸟。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开船在这片海域里走了一天。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "海域：海里的一大片地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96225, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：海里的一大片地方。"}, {"text": "海鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是海里的鱼。"}, {"text": "海路", "is_correct": false, "explanation": "lù 与 yù 声母不同（l 与零声母），意思是海上的航线。"}, {"text": "海雾", "is_correct": false, "explanation": "wù 与 yù 韵母不同（u 与 ü），意思是海上的雾。"}, {"text": "海雨", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是海上的雨。"}], "explanations": {"海域": "海域：海里的一大片地方。", "海鱼": "yú（第二声）与 yù（第四声）声调不同，意思是海里的鱼。", "海路": "lù 与 yù 声母不同（l 与零声母），意思是海上的航线。", "海雾": "wù 与 yù 韵母不同（u 与 ü），意思是海上的雾。", "海雨": "yǔ（第三声）与 yù（第四声）声调不同，意思是海上的雨。"}, "sentence_index": null, "correct_answer": "海域"}, "level_3": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：海里的一大片地方，与“很多鱼”相符。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原不在水里，不会有很多鱼。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空里不会有鱼，这句话不通。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠里没有水，不会有很多鱼。"}], "explanations": {"海域": "海域：海里的一大片地方，与“很多鱼”相符。", "草原": "语义：草原不在水里，不会有很多鱼。", "天空": "语义：天空里不会有鱼，这句话不通。", "沙漠": "语义：沙漠里没有水，不会有很多鱼。"}, "sentence_index": 0, "correct_answer": "海域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球表面大部分被海域覆盖。", "explanation": "这里应该用〈海洋〉。海域指海里划出的一片范围，不指覆盖全球的大片海水。"}, {"text": "海域一下一下地拍打着礁石。", "explanation": "这里应该用〈海浪〉。海域指海里划出的一片范围，不会拍打礁石，拍打礁石的是「海浪」。"}, {"text": "海域的岸边停着很多渔船。", "explanation": "这里应该用〈海岸〉。海域指海里的一片范围，不指陆地与海的交界处，停船的岸边要说「海岸」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96225, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：海里的一大片地方。"}, {"text": "海陆", "is_correct": false, "explanation": "lù 与 yù 声母不同（l 与零声母），意思是海洋与陆地。"}, {"text": "海渔", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是海上捕鱼。"}, {"text": "海物", "is_correct": false, "explanation": "wù 与 yù 韵母不同（u 与 ü），意思是海里的物产。"}, {"text": "海语", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是海上的语言。"}], "explanations": {"海域": "海域：海里的一大片地方。", "海陆": "lù 与 yù 声母不同（l 与零声母），意思是海洋与陆地。", "海渔": "yú（第二声）与 yù（第四声）声调不同，意思是海上捕鱼。", "海物": "wù 与 yù 韵母不同（u 与 ü），意思是海里的物产。", "海语": "yǔ（第三声）与 yù（第四声）声调不同，意思是海上的语言。"}, "sentence_index": null, "correct_answer": "海域"}, "level_3": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：海里的一大片地方，与“到处都是小船”相符。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林里没有水面，不会到处都是小船。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠里没有水，不可能到处都是小船。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋建在陆地上，不会到处都是小船。"}], "explanations": {"海域": "海域：海里的一大片地方，与“到处都是小船”相符。", "森林": "语义：森林里没有水面，不会到处都是小船。", "沙漠": "语义：沙漠里没有水，不可能到处都是小船。", "房屋": "语义：房屋建在陆地上，不会到处都是小船。"}, "sentence_index": 6, "correct_answer": "海域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只海域属于我国。", "explanation": "这里应该用〈片〉。“只”用于动物或船只，海域是一大片，要用“片”。"}, {"text": "一座海域很深。", "explanation": "这里应该用〈片〉。“座”用于山、楼等体积大而固定的东西，不用于海域。"}, {"text": "一颗海域很干净。", "explanation": "这里应该用〈片〉。“颗”用于颗粒状、圆形的小东西，海域要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX