INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的船在片海域里航行。", "corrected_sentence": "我们的船在这片海域里航行。", "error_description": "指示词缺失：“片”作量词，前面需要“这/那/一”等限定词，不能直接说“片海域”。正确说法是“我们的船在这片海域里航行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民在那条海域里撒网。", "corrected_sentence": "渔民在那片海域里撒网。", "error_description": "量词错误：“海域”是一大片，量词要用“片”，“条”用于长条形事物，应说“那片海域”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
