INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "灭是火或灯不亮了，没有了。", "primary_collocate": null, "pronunciation": "miè", "ipa": "mjɛ˥˩", "syllable_count": 1, "sentences": [{"text": "风一吹，蜡烛就灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里的灯忽然灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灭了，大家都回家了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮以后，路灯就灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "篝火慢慢灭了，天也黑了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一进门，屋里的灯就灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "炉子里的火不小心灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电没了，所有的灯都灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下得很大，火很快就灭了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜡烛灭了，房间一下子黑了。", "target_word": "灭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭了", "label": "体标"}, {"form": "熄灭", "label": "复合"}], "register": "中性", "sense_fingerprint": "灭：火或灯自己不亮了、熄了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：火或灯自己不亮了、熄了。"}, {"text": "裂", "is_correct": false, "explanation": "liè 与 miè 声母不同（l 与 m），同为第四声，意思是破开、裂开。"}, {"text": "谢", "is_correct": false, "explanation": "xiè 与 miè 声母不同（x 与 m），同为第四声，意思是感谢、凋谢。"}, {"text": "密", "is_correct": false, "explanation": "mì 与 miè 韵母不同（-i 与 -ie），意思是紧密、秘密。"}], "explanations": {"灭": "灭：火或灯自己不亮了、熄了。", "裂": "liè 与 miè 声母不同（l 与 m），同为第四声，意思是破开、裂开。", "谢": "xiè 与 miè 声母不同（x 与 m），同为第四声，意思是感谢、凋谢。", "密": "mì 与 miè 韵母不同（-i 与 -ie），意思是紧密、秘密。"}, "sentence_index": null, "correct_answer": "灭"}, "level_3": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：火或灯自己不亮了，与“风一吹”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：蜡烛不会唱歌，风一吹不会让蜡烛“唱”。"}, {"text": "跑", "is_correct": false, "explanation": "语义：蜡烛不会自己跑开，这句话说不通。"}, {"text": "拿", "is_correct": false, "explanation": "语义：风一吹不会让蜡烛被拿走，这句话说不通。"}], "explanations": {"灭": "灭：火或灯自己不亮了，与“风一吹”相符。", "唱": "语义：蜡烛不会唱歌，风一吹不会让蜡烛“唱”。", "跑": "语义：蜡烛不会自己跑开，这句话说不通。", "拿": "语义：风一吹不会让蜡烛被拿走，这句话说不通。"}, "sentence_index": 0, "correct_answer": "灭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山上的雪慢慢灭了。", "explanation": "这里应该用〈化〉。「灭」在这里指火或灯不亮了，雪融化要用「化」。"}, {"text": "他一按门铃，门铃就灭了。", "explanation": "这里应该用〈响〉。「灭」指火或灯不亮了，门铃按下后有声音要用「响」。"}, {"text": "他的脸色慢慢灭了。", "explanation": "这里应该用〈变〉。「灭」指火或灯不亮了，脸色改变要用「变」，如「脸色慢慢变白」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：火或灯自己不亮了、熄了。"}, {"text": "列", "is_correct": false, "explanation": "liè 与 miè 声母不同（l 与 m），意思是排列、列车。"}, {"text": "谢", "is_correct": false, "explanation": "xiè 与 miè 声母不同（x 与 m），同为第四声，意思是感谢、凋谢。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 miè 声母不同（j 与 m），同为第四声，意思是边界。"}, {"text": "切", "is_correct": false, "explanation": "qiè 与 miè 声母不同（q 与 m），同为第四声，意思是切割。"}], "explanations": {"灭": "灭：火或灯自己不亮了、熄了。", "列": "liè 与 miè 声母不同（l 与 m），意思是排列、列车。", "谢": "xiè 与 miè 声母不同（x 与 m），同为第四声，意思是感谢、凋谢。", "界": "jiè 与 miè 声母不同（j 与 m），同为第四声，意思是边界。", "切": "qiè 与 miè 声母不同（q 与 m），同为第四声，意思是切割。"}, "sentence_index": null, "correct_answer": "灭"}, "level_3": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：火自己熄了，与“不小心”相符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：火不会睡觉，“炉子里的火睡了”说不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”需要文字之类的对象，不能与“火”搭配。"}, {"text": "笑", "is_correct": false, "explanation": "语义：火不会笑，这句话说不通。"}], "explanations": {"灭": "灭：火自己熄了，与“不小心”相符。", "睡": "语义：火不会睡觉，“炉子里的火睡了”说不通。", "写": "搭配：“写”需要文字之类的对象，不能与“火”搭配。", "笑": "语义：火不会笑，这句话说不通。"}, "sentence_index": 6, "correct_answer": "灭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雾气慢慢灭了。", "explanation": "这里应该用〈消失〉。“灭”在这里指火或灯熄了，雾气消散要用“消失”。"}, {"text": "发动机突然灭了。", "explanation": "这里应该用〈停〉。发动机停转不说“灭”，“灭”多用于火、灯。"}, {"text": "电灭了，屋子一下子黑了。", "explanation": "这里应该用〈没〉。停电要说“没了”，不说“电灭了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外的路灯已经了灭。", "corrected_sentence": "窗外的路灯已经灭了。", "error_description": "“了”的位置错误：“了”应放在“灭”之后，应说“已经灭了”，不能说“已经了灭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一阵风过去，油灯灭就了。", "corrected_sentence": "一阵风过去，油灯就灭了。", "error_description": "语序错误：副词“就”应放在动词“灭”前，应说“就灭了”，不能说“灭就了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
