INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96230, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "点燃", "is_correct": true, "explanation": "点燃与“熄灭”的意思相反：一个使火着起来，一个使火灭掉。"}, {"text": "打开", "is_correct": false, "explanation": "打开是“关闭”的反义词，与“灭”（使火熄掉）没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是移动东西，与“使火熄掉”没有反义关系。"}, {"text": "修补", "is_correct": false, "explanation": "修补是使损坏的东西恢复，与“使火熄掉”没有反义关系。"}], "correct_answer": "点燃", "explanations": {"点燃": "点燃与“熄灭”的意思相反：一个使火着起来，一个使火灭掉。", "打开": "打开是“关闭”的反义词，与“灭”（使火熄掉）没有反义关系。", "搬运": "搬运是移动东西，与“使火熄掉”没有反义关系。", "修补": "修补是使损坏的东西恢复，与“使火熄掉”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "熄灭；消失；使不存在。", "primary_collocate": null, "pronunciation": "miè", "ipa": "mjɛ˥˩", "syllable_count": 1, "sentences": [{"text": "他用水把火灭了。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把房间里的蚊子都灭了。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见家里有蚂蚁，我就把它们灭掉。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府下令把这种病毒灭了。", "target_word": "灭", "complexity_tier": "T3", "furigana": "zhèngfǔ xiàlìng bǎ zhè zhǒng bìngdú miè le.", "sentence_source": "generated"}, {"text": "一场大雨把山上的火灭了。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，要把炉子里的火灭了。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民想办法把田里的害虫灭了。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员很快就把大火灭了。", "target_word": "灭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能灭蟑螂。", "target_word": "灭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一口气就把蜡烛灭了。", "target_word": "灭", "complexity_tier": "T3", "furigana": "tā yì kǒu qì jiù bǎ làzhú miè le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭了", "label": "体标"}, {"form": "灭掉", "label": "复合"}, {"form": "消灭", "label": "复合"}], "register": "中性", "sense_fingerprint": "灭：使火熄掉、使害虫等不存在，或希望等消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee16b8a-c760-4fa8-bd63-f5d965e5639e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96230, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：使火熄掉、使害虫等不存在。"}, {"text": "列", "is_correct": false, "explanation": "liè 与 miè 声母不同（l 与 m），同为第四声，意思是排列、列车。"}, {"text": "谢", "is_correct": false, "explanation": "xiè 与 miè 声母不同（x 与 m），同为第四声，意思是感谢、凋谢。"}, {"text": "密", "is_correct": false, "explanation": "mì 与 miè 韵母不同（-i 与 -ie），意思是紧密、秘密。"}], "explanations": {"灭": "灭：使火熄掉、使害虫等不存在。", "列": "liè 与 miè 声母不同（l 与 m），同为第四声，意思是排列、列车。", "谢": "xiè 与 miè 声母不同（x 与 m），同为第四声，意思是感谢、凋谢。", "密": "mì 与 miè 韵母不同（-i 与 -ie），意思是紧密、秘密。"}, "sentence_index": null, "correct_answer": "灭"}, "level_3": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：使火熄掉，与“用水”相符。"}, {"text": "点", "is_correct": false, "explanation": "语义：用水不能把火点着，“点”与“用水把火……了”说的动作相反。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“用水把火烧了”说不通，水不会让火烧起来。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”与“用水”不搭，吹火要用嘴或风箱，不用水。"}], "explanations": {"灭": "灭：使火熄掉，与“用水”相符。", "点": "语义：用水不能把火点着，“点”与“用水把火……了”说的动作相反。", "烧": "语义：“用水把火烧了”说不通，水不会让火烧起来。", "吹": "搭配：“吹”与“用水”不搭，吹火要用嘴或风箱，不用水。"}, "sentence_index": 0, "correct_answer": "灭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把空调灭了，然后去睡觉。", "explanation": "这里应该用〈关〉。「灭」多用于火、灯、害虫、病毒等，关空调要用「关」。"}, {"text": "他把桌上的灰尘灭掉了。", "explanation": "这里应该用〈擦〉。「灭」用于火、灯、害虫、病毒等，桌上的灰尘要用「擦」去掉。"}, {"text": "他把收音机里的声音灭了。", "explanation": "这里应该用〈停〉。「灭」用于火、灯、害虫、病毒等，声音停止要用「停」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96230, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：使火熄掉、使害虫等不存在。"}, {"text": "猎", "is_correct": false, "explanation": "liè 与 miè 声母不同（l 与 m），同为第四声，意思是打猎。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 miè 声母不同（j 与 m），同为第四声，意思是边界。"}, {"text": "切", "is_correct": false, "explanation": "qiè 与 miè 声母不同（q 与 m），同为第四声，意思是切割。"}, {"text": "媚", "is_correct": false, "explanation": "mèi 与 miè 韵母不同（-ei 与 -ie），同为第四声，意思是讨好、可爱。"}], "explanations": {"灭": "灭：使火熄掉、使害虫等不存在。", "猎": "liè 与 miè 声母不同（l 与 m），同为第四声，意思是打猎。", "界": "jiè 与 miè 声母不同（j 与 m），同为第四声，意思是边界。", "切": "qiè 与 miè 声母不同（q 与 m），同为第四声，意思是切割。", "媚": "mèi 与 miè 韵母不同（-ei 与 -ie），同为第四声，意思是讨好、可爱。"}, "sentence_index": null, "correct_answer": "灭"}, "level_3": {"options": [{"text": "灭", "is_correct": true, "explanation": "灭：使害虫等不存在，与“想办法”相符。"}, {"text": "养", "is_correct": false, "explanation": "语义：农民不会想办法把害虫养起来，这句话说不通。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”一般搭配作物，不说“种害虫”。"}, {"text": "放", "is_correct": false, "explanation": "语义：“想办法把害虫放了”的意思与除虫相反，不合语境。"}], "explanations": {"灭": "灭：使害虫等不存在，与“想办法”相符。", "养": "语义：农民不会想办法把害虫养起来，这句话说不通。", "种": "搭配：“种”一般搭配作物，不说“种害虫”。", "放": "语义：“想办法把害虫放了”的意思与除虫相反，不合语境。"}, "sentence_index": 6, "correct_answer": "灭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猎人在山上把野兔灭了。", "explanation": "这里应该用〈杀〉。“灭”用于火、灯、害虫、病毒等被彻底除掉，打猎杀动物要用“杀”。"}, {"text": "工人灭了墙上的污渍。", "explanation": "这里应该用〈清除〉。污渍不是火、害虫或病毒，不能说“灭”，要用“清除”。"}, {"text": "他把牛奶灭了，然后去上班。", "explanation": "这里应该用〈喝〉。「灭」指火、灯熄灭或害虫、病毒被消灭，喝牛奶要用「喝」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们已经把老鼠掉灭了。", "corrected_sentence": "工人们已经把老鼠灭掉了。", "error_description": "补语语序错误：结果补语“掉”要放在“灭”之后，应说“灭掉”，不能说“掉灭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用湿布把炉子里的火了灭。", "corrected_sentence": "妈妈用湿布把炉子里的火灭了。", "error_description": "“了”的位置错误：“了”应放在动词“灭”之后，应说“灭了”，不能说“了灭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5354bab9-6a50-4ab9-b0d8-8d6ccd6ec25b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
