INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体是能看到、能摸到的东西。", "primary_collocate": null, "pronunciation": "wù tǐ", "ipa": "u˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "盲人用手摸物体，就能知道它的形状。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气是看不到的，所以不是物体。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子、书和手机都是我们能摸到的物体。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外飞过一个不明物体。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把危险的物体放到孩子拿不到的地方。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛可以帮我们看见远处的物体。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰是一种很硬的物体。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用布盖着桌上的物体，不让我们看。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物体有大有小，颜色也不一样。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线太暗，我看不清前面的物体。", "target_word": "物体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "能看到、能摸到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物体", "is_correct": true, "explanation": "“物体”指能看到、能摸到的东西，盲人用手能摸到的正是这类东西。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，不能用手摸。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“摸”一般搭配有形体的东西，不能与“声音”搭配。"}, {"text": "光线", "is_correct": false, "explanation": "语义：光线看不见也摸不着，盲人无法用手摸到它。"}], "explanations": {"物体": "“物体”指能看到、能摸到的东西，盲人用手能摸到的正是这类东西。", "空气": "语义：空气看不见、摸不着，不能用手摸。", "声音": "搭配：“摸”一般搭配有形体的东西，不能与“声音”搭配。", "光线": "语义：光线看不见也摸不着，盲人无法用手摸到它。"}, "sentence_index": 0, "correct_answer": "物体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋子里飘着一股奇怪的物体。", "explanation": "这里应该用〈气味〉。“物体”指能看到、能摸到的东西，气味闻得到却看不见、摸不着，应说“气味”。"}, {"text": "他是一个很好的物体。", "explanation": "这里应该用〈人〉。“物体”指实物，不用来指人，形容人应说“人”。"}, {"text": "他提出了一个物体。", "explanation": "这里应该用〈计划〉。“物体”是实物，不能提出；“提出”的对象是计划、建议等，应说“计划”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气体", "is_correct": false, "explanation": "语义：气体没有固定形状，不能说“很硬”。"}, {"text": "物体", "is_correct": true, "explanation": "“物体”是有形状的实物，冰是一种很硬的实物。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很硬”不修饰“颜色”，不能说“很硬的颜色”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“很硬”不修饰“味道”，不能说“很硬的味道”。"}], "explanations": {"气体": "语义：气体没有固定形状，不能说“很硬”。", "物体": "“物体”是有形状的实物，冰是一种很硬的实物。", "颜色": "搭配：“很硬”不修饰“颜色”，不能说“很硬的颜色”。", "味道": "搭配：“很硬”不修饰“味道”，不能说“很硬的味道”。"}, "sentence_index": 6, "correct_answer": "物体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空气是一种物体，我们看不见它。", "explanation": "这里应该用〈气体〉。“物体”指能看到、能摸到的东西，空气看不见、摸不着，应说“气体”。"}, {"text": "我们听到了一种奇怪的物体。", "explanation": "这里应该用〈声音〉。“物体”是能看到、能摸到的东西，声音只能听到，不能说“听到物体”。"}, {"text": "院子里种着很多物体。", "explanation": "这里应该用〈植物〉。“物体”指实物，不指可以种植的东西，说“种着”应用“植物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用手摸到一个小小物体。", "corrected_sentence": "我用手摸到一个小小的物体。", "error_description": "结构助词错误：重叠形容词“小小”作定语修饰“物体”时要加“的”，应说“小小的物体”，“小小物体”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手里拿着那根物体。", "corrected_sentence": "他手里拿着那个物体。", "error_description": "量词错误：“物体”是能看到、能摸到的实物，量词用“个”。“根”用于细长的东西，“那根物体”错误，应改为“那个物体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
