INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产单位是做出东西来的工厂或地方。", "primary_collocate": null, "pronunciation": "shēng chǎn dān wèi", "ipa": "ʂɤŋ˥ tʂʰan˨˩ tan˥ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "那个生产单位在城东，做各种饮料。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有一个生产单位，专门做面包。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位里到处是机器。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观生产单位时，要戴安全帽。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位做的衣服很便宜。", "target_word": "生产单位", "complexity_tier": "T3", "furigana": "zhè ge shēng chǎn dān wèi zuò de yī fu hěn pián yi", "sentence_source": "generated"}, {"text": "学生们坐车去生产单位看工人做玩具。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产单位的院子里停着很多大卡车。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位晚上也开着灯，工人在加班。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的生产单位建在河边。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天骑车去生产单位上班。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "做出东西来的工厂或场所，有机器和工人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1bf783-abf4-4cfc-89ce-bf2c333a7842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产单位", "is_correct": true, "explanation": "正确：指做出饮料的工厂，符合“在城东”“做各种饮料”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不做饮料，与“做各种饮料”矛盾。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“做各种饮料”的主体一般是工厂，不说学校做饮料。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆是展示文物的地方，不做饮料，与句意不符。"}], "explanations": {"生产单位": "正确：指做出饮料的工厂，符合“在城东”“做各种饮料”。", "图书馆": "语义：图书馆不做饮料，与“做各种饮料”矛盾。", "学校": "搭配：“做各种饮料”的主体一般是工厂，不说学校做饮料。", "博物馆": "语义：博物馆是展示文物的地方，不做饮料，与句意不符。"}, "sentence_index": 0, "correct_answer": "生产单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家附近新开了一条生产单位。", "explanation": "这里应该用〈个〉。生产单位是工厂，量词用“个”；“条”用于线状事物。"}, {"text": "这个生产单位是我的好朋友。", "explanation": "这里应该用〈朋友〉。生产单位指做东西的工厂或地方，不指人，不能用来称呼朋友。"}, {"text": "这个生产单位每天都有很多人来游泳。", "explanation": "这里应该用〈游泳馆〉。生产单位是做东西的工厂或地方，不是供人游泳的场所；游泳要去游泳馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产单位", "is_correct": true, "explanation": "正确：指工厂，有院子，院子里可以停大卡车，符合句意。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是托幼机构，院子里不会停着很多大卡车。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：茶馆是供人饮茶的场所，院子里一般不会停着很多大卡车。"}, {"text": "电影院", "is_correct": false, "explanation": "搭配：电影院不需要让大卡车停在院子里，这种说法不符合场所特点。"}], "explanations": {"生产单位": "正确：指工厂，有院子，院子里可以停大卡车，符合句意。", "幼儿园": "语义：幼儿园是托幼机构，院子里不会停着很多大卡车。", "茶馆": "语义：茶馆是供人饮茶的场所，院子里一般不会停着很多大卡车。", "电影院": "搭配：电影院不需要让大卡车停在院子里，这种说法不符合场所特点。"}, "sentence_index": 6, "correct_answer": "生产单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把生产单位装进了书包。", "explanation": "生产单位是工厂，是大型场所，不能装进书包；指可以装进书包的东西时应说“笔记本”等。"}, {"text": "他每天骑车去生产单位上学。", "explanation": "这里应该用〈学校〉。上学要去学校；生产单位是工厂，不是学习的地方，不能说“上学”。"}, {"text": "他每天骑车去生产单位买书。", "explanation": "这里应该用〈书店〉。工厂生产东西，不卖书，买书要去书店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条生产单位下个月开工。", "corrected_sentence": "那个生产单位下个月开工。", "error_description": "量词错误：“生产单位”的量词用“个”，不用“条”（“条”用于线状事物）。正确说法是“那个生产单位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个生产单位地产品很受欢迎。", "corrected_sentence": "这个生产单位的产品很受欢迎。", "error_description": "错误：“地”。正确：“的”。“生产单位”修饰“产品”是定语，要用“的”；“地”用于状语，不能连接定语和中心语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
