INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从事生产的组织或部门。", "primary_collocate": null, "pronunciation": "shēng chǎn dān wèi", "ipa": "ʂɤŋ˥ tʂʰan˨˩ tan˥ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "这个生产单位有三百名工人。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要求每个生产单位都注意安全。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有五个生产单位。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产单位的负责人明天开会。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位去年完成了任务。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的各个生产单位每月都要检查一次设备。", "target_word": "生产单位", "complexity_tier": "T3", "furigana": "gōng sī de gè gè shēng chǎn dān wèi měi yuè dōu yào jiǎn chá yí cì shè bèi", "sentence_source": "generated"}, {"text": "领导来生产单位了解工人的情况。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个生产单位当会计。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个生产单位都要写工作报告。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位的管理很严格。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "从事生产的组织或部门，强调管理和任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1bf783-abf4-4cfc-89ce-bf2c333a7842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产单位", "is_correct": true, "explanation": "正确：生产单位指从事生产的组织或部门，可以有三百名工人，符合句意。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：茶馆是供人饮茶的场所，不从事生产，一般不会有三百名工人。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是教育机构，不从事生产劳动，与“工人”不合。"}, {"text": "博物馆", "is_correct": false, "explanation": "搭配：博物馆的工作人员称“工作人员”，不称“工人”，与句中的说法不符。"}], "explanations": {"生产单位": "正确：生产单位指从事生产的组织或部门，可以有三百名工人，符合句意。", "茶馆": "语义：茶馆是供人饮茶的场所，不从事生产，一般不会有三百名工人。", "幼儿园": "语义：幼儿园是教育机构，不从事生产劳动，与“工人”不合。", "博物馆": "搭配：博物馆的工作人员称“工作人员”，不称“工人”，与句中的说法不符。"}, "sentence_index": 0, "correct_answer": "生产单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司新开了一条生产单位。", "explanation": "这里应该用〈个〉。生产单位是组织或部门，量词用“个”；“条”用于线状事物，如生产线。"}, {"text": "这个生产单位每晚都演出，观众很多。", "explanation": "这里应该用〈剧院〉。生产单位是从事生产的组织或部门，不演出节目；演出要在剧院。"}, {"text": "他是我们公司最能干的生产单位。", "explanation": "这里应该用〈员工〉。生产单位指组织或部门，不指人，不能用来称呼某个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产单位", "is_correct": true, "explanation": "正确：这里指从事生产的组织，领导来此了解工人的情况，符合句意。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：茶馆是饮茶的场所，不从事生产，没有需要领导了解情况的工人。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店的人员是理发师，不称“工人”，与句中的“工人的情况”不合。"}, {"text": "诊所", "is_correct": false, "explanation": "搭配：诊所的工作人员是医护人员，不称“工人”，与“了解工人的情况”不搭。"}], "explanations": {"生产单位": "正确：这里指从事生产的组织，领导来此了解工人的情况，符合句意。", "茶馆": "语义：茶馆是饮茶的场所，不从事生产，没有需要领导了解情况的工人。", "理发店": "语义：理发店的人员是理发师，不称“工人”，与句中的“工人的情况”不合。", "诊所": "搭配：诊所的工作人员是医护人员，不称“工人”，与“了解工人的情况”不搭。"}, "sentence_index": 6, "correct_answer": "生产单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都去生产单位存钱。", "explanation": "这里应该用〈银行〉。生产单位是从事生产的组织，不办存款业务；存钱要去银行。"}, {"text": "这个生产单位有三百名学生，每天都上课。", "explanation": "这里应该用〈学校〉。生产单位是工厂或部门，没有“学生”，上课要去学校。"}, {"text": "我把这个生产单位放进了口袋。", "explanation": "生产单位指组织或部门，不是可以放进口袋的物品；放进口袋的应是“笔记本”之类的小物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产单位下个月要搬到新地方。", "corrected_sentence": "这个生产单位下个月要搬到新地方。", "error_description": "量词错误：“生产单位”指组织或部门，量词应用“个”，不用“条”（“条”用于线状事物）。正确说法是“这个生产单位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个生产单位的很大，每天都有很多工人。", "corrected_sentence": "这个生产单位很大，每天都有很多工人。", "error_description": "多余的“的”：“生产单位”与“很大”之间不需要“的”。正确说法是“这个生产单位很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解散是原来在一起的人，各自走开。", "primary_collocate": null, "pronunciation": "jiě sàn", "ipa": "tɕje˨˩˦ san˥˩", "syllable_count": 2, "sentences": [{"text": "队伍走到学校门口就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说一声“解散”，同学们就各自回家了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到“解散”的口令，大家马上跑开了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "训练结束，教练一挥手，大家就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开完会，大家在门口说了再见就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游行的人群到广场后就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站了半个小时后，同学们终于解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "升旗仪式一结束，学生们就解散回教室了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "集合了一个小时，大家才解散回家。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，队员们在球场上解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "解散了", "label": "体标"}, {"form": "解散过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不及物：聚在一起的人各自走开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1bf783-abf4-4cfc-89ce-bf2c333a7842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解散", "is_correct": true, "explanation": "正确：“解散”指人群各自走开，与“队伍走到学校门口”的语境合理。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：队伍不能“游泳”，句子说不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”是生理动作，与队伍到门口的意思无关。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主语是学生，队伍不能毕业。"}], "explanations": {"解散": "正确：“解散”指人群各自走开，与“队伍走到学校门口”的语境合理。", "游泳": "语义：队伍不能“游泳”，句子说不通。", "呼吸": "语义：“呼吸”是生理动作，与队伍到门口的意思无关。", "毕业": "搭配：“毕业”的主语是学生，队伍不能毕业。"}, "sentence_index": 0, "correct_answer": "解散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理决定解散这位员工的职务。", "explanation": "这里应该用〈解除〉。解散指原来在一起的人各自走开，不能带“职务”这种宾语；解除职务要用解除。"}, {"text": "教练一挥手，大家就解散了操场。", "explanation": "这里应该用〈离开〉。解散表示人群各自走开，不带处所宾语“操场”。"}, {"text": "会议结束后，大家又解散在一起了。", "explanation": "这里应该用〈集合〉。解散表示各自走开，与“在一起”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解散", "is_correct": true, "explanation": "正确：“解散”指人群各自走开，“站了半个小时后终于”之后正是散开的时候。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光的消失，不能用于同学。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”只说液体凝固，不能用于同学。"}, {"text": "殉职", "is_correct": false, "explanation": "语域：“殉职”是正式语域，指为公殉难，与同学的日常语境不合。"}], "explanations": {"解散": "正确：“解散”指人群各自走开，“站了半个小时后终于”之后正是散开的时候。", "熄灭": "语义：“熄灭”指火或光的消失，不能用于同学。", "结冰": "语义：“结冰”只说液体凝固，不能用于同学。", "殉职": "语域：“殉职”是正式语域，指为公殉难，与同学的日常语境不合。"}, "sentence_index": 6, "correct_answer": "解散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛结束后，队员们把比赛解散了。", "explanation": "这里应该用〈结束〉。解散表示人群各自走开，不能用来处理比赛。"}, {"text": "比赛结束后，观众们解散了球场。", "explanation": "这里应该用〈撤离〉。解散不带处所宾语“球场”。"}, {"text": "比赛结束后，队员们解散成一排。", "explanation": "这里应该用〈站成一排〉。解散表示各自走开，不能表示排成一排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出结束后，观众们很快就解散了现场。", "corrected_sentence": "演出结束后，观众们很快就解散了。", "error_description": "错误：多了宾语“现场”。正确：“解散了”。不及物的“解散”表示各自走开，不带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后，同学们都解散家回了。", "corrected_sentence": "下课后，同学们都解散回家了。", "error_description": "错误：“家回”。正确：“回家”。“回家”是动宾短语，接在“解散”之后，词序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
