INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "较真是特别认真，一点也不马虎。", "primary_collocate": null, "pronunciation": "jiào zhēn", "ipa": "tɕjɑʊ˥˩ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "经理对每份文件都很较真。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥做实验时非常较真。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她较真起来，连标点也要检查。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生很较真，每个数字都看三遍。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李对时间很较真，从来不迟到。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做饭也这么较真，盐都要称一称。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很较真，所以大家都不敢马虎。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画画时很较真，一条线要画很久。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很较真，把钱数了三遍。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做翻译就要较真，一个词也不能错。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "较真儿", "label": "儿化"}, {"form": "较了真", "label": "体标"}], "register": "口语", "sense_fingerprint": "做事特别认真，一点也不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1bf783-abf4-4cfc-89ce-bf2c333a7842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较真", "is_correct": true, "explanation": "正确：“较真”表示做事特别认真，符合“每份文件都很”的语境。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：“偷懒”指不认真做事，与“对每份文件都很”的认真态度相反。"}, {"text": "敷衍", "is_correct": false, "explanation": "语义：“敷衍”指做事马虎应付，与认真对待文件的语境矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事不仔细，与“较真”的认真态度正相反。"}], "explanations": {"较真": "正确：“较真”表示做事特别认真，符合“每份文件都很”的语境。", "偷懒": "语义：“偷懒”指不认真做事，与“对每份文件都很”的认真态度相反。", "敷衍": "语义：“敷衍”指做事马虎应付，与认真对待文件的语境矛盾。", "马虎": "语义：“马虎”指做事不仔细，与“较真”的认真态度正相反。"}, "sentence_index": 0, "correct_answer": "较真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位医生很较真地哭了起来。", "explanation": "较真是对事的认真态度，不表示情绪；这里应该用〈伤心〉。"}, {"text": "这台机器很较真，每次都出故障。", "explanation": "较真说的是人对事的态度，机器不能较真；这里应该用〈结实〉之类的词。"}, {"text": "他很较真地摔了一跤。", "explanation": "“较真”形容人做事认真，不能用来修饰摔跤这种意外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较真", "is_correct": true, "explanation": "正确：“较真”指对小事也不放松，符合“老板很”的严格语境。"}, {"text": "迁就", "is_correct": false, "explanation": "语义：“迁就”指顺从、不坚持，与“大家都不敢马虎”的语境矛盾。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”指不加约束，与“大家都不敢马虎”的严格氛围相反。"}, {"text": "纵容", "is_correct": false, "explanation": "搭配：“纵容”通常接对象，如“纵容某人”，不单说“老板很纵容”。"}], "explanations": {"较真": "正确：“较真”指对小事也不放松，符合“老板很”的严格语境。", "迁就": "语义：“迁就”指顺从、不坚持，与“大家都不敢马虎”的语境矛盾。", "放纵": "语义：“放纵”指不加约束，与“大家都不敢马虎”的严格氛围相反。", "纵容": "搭配：“纵容”通常接对象，如“纵容某人”，不单说“老板很纵容”。"}, "sentence_index": 6, "correct_answer": "较真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗很较真地摇了摇尾巴。", "explanation": "“较真”形容人对事的认真态度，不能用来修饰摇尾巴这种动作；这里应该去掉〈较真〉。"}, {"text": "今天很较真地下了一场雨。", "explanation": "“较真”形容人对事认真，不能用来修饰天气。"}, {"text": "他很较真地长高了两厘米。", "explanation": "“较真”形容人对事的认真态度，不能用来形容身高的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位会计是个很较真人，账目一分钱都不放过。", "corrected_sentence": "这位会计是个很较真的人，账目一分钱都不放过。", "error_description": "定语错误：动词性短语“较真”修饰名词时要加“的”，应说“很较真的人”，不说“很较真人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟同事较真很，最后还是没说服对方。", "corrected_sentence": "他跟同事较真得很，最后还是没说服对方。", "error_description": "状态补语错误：“很”不能直接跟在动词“较真”后，要用“得”连接，应说“较真得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
