INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "第一等的；水平、质量属于最高等级的。", "primary_collocate": null, "pronunciation": "yī liú", "ipa": "i˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他是世界一流的科学家。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司有一流的设备。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一流的演员要认真练习。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队的水平是一流的。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去一流的大学读书。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的质量是一流的。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的唱功一流，全国有名。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有一流的医生。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用一流的技术做汽车。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请了一流的老师教孩子。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一流的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "水平、质量属于最高等级的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc1bf783-abf4-4cfc-89ce-bf2c333a7842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。"}, {"text": "一里", "is_correct": false, "explanation": "lǐ（第三声）与 liú 韵母和声调都不同，意思是一里，是距离单位。"}, {"text": "一楼", "is_correct": false, "explanation": "lóu 与 liú 韵母不同（-ou 与 -iu），意思是楼房的第一层。"}, {"text": "医疗", "is_correct": false, "explanation": "liáo 与 liú 韵母不同（-iao 与 -iu），意思是治病、诊疗。"}, {"text": "一溜", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是一行、一排。"}], "explanations": {"一流": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。", "一里": "lǐ（第三声）与 liú 韵母和声调都不同，意思是一里，是距离单位。", "一楼": "lóu 与 liú 韵母不同（-ou 与 -iu），意思是楼房的第一层。", "医疗": "liáo 与 liú 韵母不同（-iao 与 -iu），意思是治病、诊疗。", "一溜": "liù（第四声）与 liú（第二声）声调不同，意思是一行、一排。"}, "sentence_index": null, "correct_answer": "一流"}, "level_3": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确：“一流”表示水平最高，符合“是世界……的科学家”的语境。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指某个地方，与“世界”的范围相矛盾。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，不能用来形容科学家。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”是味道，不能用来形容人或科学家。"}], "explanations": {"一流": "正确：“一流”表示水平最高，符合“是世界……的科学家”的语境。", "本地": "语义：“本地”指某个地方，与“世界”的范围相矛盾。", "雪白": "体貌：“雪白”形容颜色，不能用来形容科学家。", "辣": "搭配：“辣”是味道，不能用来形容人或科学家。"}, "sentence_index": 0, "correct_answer": "一流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我一流的同学，我们常一起吃饭。", "explanation": "这里误用“一流”形容同学关系。“一流”只评价水平或质量，不能说同学之间的亲疏，这里应改用〈要好〉。"}, {"text": "这场比赛的观众数量是一流的。", "explanation": "这里应该用〈很多〉。“一流”不用来形容观众人数等数量。"}, {"text": "这件毛衣的价格是一流的，只要五十块。", "explanation": "这里应该用〈便宜〉。价格的高低不能用“一流”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。"}, {"text": "遗留", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是留下来、残存。"}, {"text": "一连", "is_correct": false, "explanation": "lián（第二声）与 liú 声调相同，韵母不同（-ian 与 -iu），意思是连续不断。"}, {"text": "一轮", "is_correct": false, "explanation": "lún（第二声）与 liú 声调相同，韵母不同（-un 与 -iu），意思是一个循环或一圈。"}, {"text": "一例", "is_correct": false, "explanation": "lì（第四声）与 liú 韵母和声调都不同，意思是一个例子。"}], "explanations": {"一流": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。", "遗留": "yí（第二声）与 yī（第一声）声调不同，意思是留下来、残存。", "一连": "lián（第二声）与 liú 声调相同，韵母不同（-ian 与 -iu），意思是连续不断。", "一轮": "lún（第二声）与 liú 声调相同，韵母不同（-un 与 -iu），意思是一个循环或一圈。", "一例": "lì（第四声）与 liú 韵母和声调都不同，意思是一个例子。"}, "sentence_index": null, "correct_answer": "一流"}, "level_3": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确：“一流”表示水平最高，符合“她的唱功……，全国有名”的语境。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材或规模，不能用来形容唱功。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，与“唱功”搭配不通。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，用来说唱功意思不通。"}], "explanations": {"一流": "正确：“一流”表示水平最高，符合“她的唱功……，全国有名”的语境。", "高大": "搭配：“高大”形容身材或规模，不能用来形容唱功。", "矮小": "体貌：“矮小”形容身材，与“唱功”搭配不通。", "透明": "语义：“透明”形容物体能透光，用来说唱功意思不通。"}, "sentence_index": 6, "correct_answer": "一流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的颜色是一流的，特别鲜艳。", "explanation": "这里应该用〈漂亮〉。“一流”评价的是水平或质量的等级，颜色只能用漂亮这类词描述，不能用“一流”来评等级。"}, {"text": "他才十二岁，年纪是一流的。", "explanation": "这里应该用〈年轻〉。年纪有大小，没有“一流”之分。"}, {"text": "这袋米的重量是一流的，我一个人拿不动。", "explanation": "这里应该用〈沉〉。“一流”评价水平或质量的等级，重量只分多少，不分等级，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是国内一流地画家，作品很受欢迎。", "corrected_sentence": "她是国内一流的画家，作品很受欢迎。", "error_description": "“一流”修饰名词时要用“的”，不用“地”：应说“一流的画家”。“地”是修饰动词的状语标记，用在名词前面不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她钢琴弹一流，常常参加比赛。", "corrected_sentence": "她钢琴弹得一流，常常参加比赛。", "error_description": "“一流”作补语描述“弹”的水平，动词和它之间要用“得”：应说“弹得一流”，说“弹一流”是漏掉了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3d19eb-d0ae-4dd9-8706-270170fd54c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
