INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做不好事情的时候，说出来的不是真的理由。", "primary_collocate": null, "pronunciation": "jiè kǒu", "ipa": "tɕjɛ⁵¹ kʰoʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "考试没考好，他说是笔坏了，这是借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作做不好，别总拿忙当借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次输球，都有一堆借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队输了比赛，教练不接受任何借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业没写完，他的借口是狗吃了本子。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败了就认错，不要再找借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说路上堵车，其实是睡过头的借口。", "target_word": "借口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了事还找借口，老师很生气。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "项目没完成，他编了一个借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想进步的人，从不给失败找借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "事情没做好时说出的不真实的理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39a6f9bc-591a-4f48-89d4-a7b21a9a7282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "借口", "is_correct": true, "explanation": "“借口”指推托的说辞，此处指“笔坏了”这一说法，符合句意。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是题目的正确解法，与“笔坏了”这类推托说辞不符。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“这是成绩”不能指代推托的说辞，成绩是考试结果本身。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与考试没考好无关，“这是天气”不能作为推托的说法。"}], "explanations": {"借口": "“借口”指推托的说辞，此处指“笔坏了”这一说法，符合句意。", "答案": "语义：“答案”是题目的正确解法，与“笔坏了”这类推托说辞不符。", "成绩": "搭配：“这是成绩”不能指代推托的说辞，成绩是考试结果本身。", "天气": "语义：天气与考试没考好无关，“这是天气”不能作为推托的说法。"}, "sentence_index": 0, "correct_answer": "借口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给出了一个真实的借口，教练听后很满意。", "explanation": "这里应该用〈理由〉。“借口”指不真实的推托理由，不能用“真实的”修饰；说明真实情况要用〈理由〉。"}, {"text": "教练在下半场换了新借口，球队很快扳平了比分。", "explanation": "这里应该用〈战术〉。“借口”指推托的说辞，不能用来扭转比赛；调整比赛打法要用〈战术〉。"}, {"text": "他的简历里写满了借口，招聘的人很满意。", "explanation": "这里应该用〈经历〉。“借口”不能写进简历；简历里列出工作经验和过往工作要用〈经历〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "借口", "is_correct": true, "explanation": "“借口”指推托的理由，此处指“路上堵车”这一假托，符合句意。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是叫醒用的器具，不能作为“睡过头”的推托说法。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，与“睡过头”的推托无关，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“睡过头的座位”不成搭配，“座位”不能用“睡过头”来修饰。"}], "explanations": {"借口": "“借口”指推托的理由，此处指“路上堵车”这一假托，符合句意。", "闹钟": "语义：闹钟是叫醒用的器具，不能作为“睡过头”的推托说法。", "早餐": "语义：早餐是食物，与“睡过头”的推托无关，句意不通。", "座位": "搭配：“睡过头的座位”不成搭配，“座位”不能用“睡过头”来修饰。"}, "sentence_index": 6, "correct_answer": "借口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题有很多解决借口。", "explanation": "这里应该用〈办法〉。“借口”是推托的说辞，不能用来解决问题；“解决”要搭配〈办法〉。"}, {"text": "他制定了学习借口。", "explanation": "这里应该用〈计划〉。“制定”搭配计划、方案，不能用于借口。"}, {"text": "工人把借口一块块码好，准备砌墙。", "explanation": "这里应该用〈砖〉。“借口”是推托的说辞，不能用来砌墙；砌墙的材料要用〈砖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总为失败找出一张新借口。", "corrected_sentence": "他总为失败找出一个新借口。", "error_description": "错误：“一张新借口”；正确：“一个新借口”。“借口”的量词是“个”，“张”不用于借口。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是找一只借口，大家都不再相信他了。", "corrected_sentence": "他总是找一个借口，大家都不再相信他了。", "error_description": "错误：“一只借口”；正确：“一个借口”。“借口”的量词是“个”，“只”不用于借口。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
