INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96311, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大树的大枝上又长出来的小枝。", "primary_collocate": null, "pronunciation": "fēn zhī", "ipa": "fən˥ ʈ͡ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "这棵树的大枝上长出了很多分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟站在一根细细的分支上。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，树的分支轻轻地动。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，每个分支上都长出了新叶。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他剪掉了苹果树多余的分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根分支太细，承受不住你的重量。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树的主干上有许多分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪压在分支上，树枝弯了下来。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们捡了一些干分支回家生火。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的这个分支上结了三个果子。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "树的大枝上再长出的小枝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '835b18fe-03f2-4221-8887-eff8b608d335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分支", "is_correct": true, "explanation": "分支（fēn zhī）：大树的大枝上长出的小枝，是本题要听出的词。"}, {"text": "分子", "is_correct": false, "explanation": "fēn zǐ 与 fēn zhī 的声母不同（z 与 zh），声调也不同（第三声与第一声），意思是分子，不是树枝。"}, {"text": "分值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是分数的价值，与树枝无关。"}, {"text": "分制", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是计分的制度。"}, {"text": "分章", "is_correct": false, "explanation": "zhāng 与 zhī 韵母不同（ang 与 i），意思是把书分成章节。"}, {"text": "分词", "is_correct": false, "explanation": "cí 与 zhī 声母不同（c 与 zh），声调也不同，意思是词的切分或语法中的分词。"}, {"text": "分时", "is_correct": false, "explanation": "shí 与 zhī 声母不同（sh 与 zh），声调也不同，意思是按时间段划分。"}], "explanations": {"分支": "分支（fēn zhī）：大树的大枝上长出的小枝，是本题要听出的词。", "分子": "fēn zǐ 与 fēn zhī 的声母不同（z 与 zh），声调也不同（第三声与第一声），意思是分子，不是树枝。", "分值": "zhí（第二声）与 zhī（第一声）声调不同，意思是分数的价值，与树枝无关。", "分制": "zhì（第四声）与 zhī（第一声）声调不同，意思是计分的制度。", "分章": "zhāng 与 zhī 韵母不同（ang 与 i），意思是把书分成章节。", "分词": "cí 与 zhī 声母不同（c 与 zh），声调也不同，意思是词的切分或语法中的分词。", "分时": "shí 与 zhī 声母不同（sh 与 zh），声调也不同，意思是按时间段划分。"}, "sentence_index": null, "correct_answer": "分支"}, "level_3": {"options": [{"text": "分支", "is_correct": true, "explanation": "分支：大枝上长出的小枝，与“这棵树的大枝上长出了很多”的语境吻合。"}, {"text": "树干", "is_correct": false, "explanation": "语义：树干是树的主干，不会从大枝上再长出来，与句中“大枝上长出”的语境矛盾。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“长出”的主体是植物或其器官，不能说长出河流。"}, {"text": "岩石", "is_correct": false, "explanation": "语义：岩石是矿物，不会从树的大枝上长出来，与植物生长的语境不符。"}], "explanations": {"分支": "分支：大枝上长出的小枝，与“这棵树的大枝上长出了很多”的语境吻合。", "树干": "语义：树干是树的主干，不会从大枝上再长出来，与句中“大枝上长出”的语境矛盾。", "河流": "搭配：“长出”的主体是植物或其器官，不能说长出河流。", "岩石": "语义：岩石是矿物，不会从树的大枝上长出来，与植物生长的语境不符。"}, "sentence_index": 0, "correct_answer": "分支"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天一到，这棵老树的分支一颗颗地掉在地上，滚得满地都是。", "explanation": "这里应该用〈果子〉。分支是枝条，不会一颗颗地掉下来、滚得满地都是；会这样掉落的是果子。"}, {"text": "秋天到了，这棵树的分支慢慢变黄，一片片地从树上掉下来。", "explanation": "这里应该用〈树叶〉。分支是枝条，不会一片片地飘落；变黄、掉落的是树叶。"}, {"text": "这棵大树的分支从地面笔直地向上长，粗得要三个人才能合抱。", "explanation": "这里应该用〈树干〉。分支是从树干上分出的细枝，从地面笔直向上、粗到要多人合抱的是树干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分支", "is_correct": true, "explanation": "分支：主干旁伸出的枝杈，与“大树的主干上有许多”的语境吻合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会长在树的主干上，与“大树的主干”的语境矛盾。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：电线通常说“架设”或“拉”，“主干上有许多电线”不自然。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学生的用品，不会挂在树的主干上，句子在语义上不成立。"}], "explanations": {"分支": "分支：主干旁伸出的枝杈，与“大树的主干上有许多”的语境吻合。", "窗户": "语义：窗户不会长在树的主干上，与“大树的主干”的语境矛盾。", "电线": "搭配：电线通常说“架设”或“拉”，“主干上有许多电线”不自然。", "书包": "语义：书包是学生的用品，不会挂在树的主干上，句子在语义上不成立。"}, "sentence_index": 6, "correct_answer": "分支"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树的分支扎进土里，吸收地下的水分。", "explanation": "这里应该用〈树根〉。分支长在树干上、伸向空中；扎进土里吸收水分的是树根。"}, {"text": "春天到了，这棵桃树的分支一瓣瓣地落在草地上，像下了一场小雨。", "explanation": "这里应该用〈花瓣〉。分支是枝条，不会一瓣瓣地飘落；桃花瓣才会这样落下来。"}, {"text": "这棵树的一根分支又圆又密，远远望去像一把撑开的大伞。", "explanation": "这里应该用〈树冠〉。单根枝条不能又圆又密地撑成伞状；整棵树枝叶连成的圆形轮廓才叫树冠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的老树伸出几只细长的分支。", "corrected_sentence": "院子里的老树伸出几根细长的分支。", "error_description": "量词错误：“分支”是细长的枝条，应搭配“根”；“只”多用于动物或成对的东西。应把“几只”改为“几根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鸟窝搭在一根矮矮的分支里。", "corrected_sentence": "鸟窝搭在一根矮矮的分支上。", "error_description": "方位词错误：枝条上的位置应说“上”，“里”表示在某物内部，树枝不是容器。应把“分支里”改为“分支上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
