INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分别处理、安排；筹划处置。", "primary_collocate": null, "pronunciation": "qū chǔ", "ipa": "tɕʰy⁵⁵ ʈʂʰu²¹⁴", "syllable_count": 2, "sentences": [{"text": "这批旧货要分开区处，能用的留下。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂长把积压的事务逐项区处。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "账目复杂，会计分类区处，花了三天。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不同的投诉，客服要分别区处。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县官区处灾后事宜，十分得力。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗留的问题，由专人区处。", "target_word": "区处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把几份急件按轻重缓急区处。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些文件有的存档，有的销毁，由秘书区处。", "target_word": "区处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪封路，村长连夜区处各家的困难。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他处事公正，各类纠纷都区处得当。", "target_word": "区处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "区处了", "label": "体标"}], "register": "书面", "sense_fingerprint": "分别处理、安排；筹划处置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39a6f9bc-591a-4f48-89d4-a7b21a9a7282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区处", "is_correct": true, "explanation": "“区处”指分别处理、安排，此处指分开处置旧货，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与处理旧货无关，“要分开唱”句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：旧货不能被“吃”，“分开吃”不成搭配。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与处理旧货无关，句意不通。"}], "explanations": {"区处": "“区处”指分别处理、安排，此处指分开处置旧货，符合句意。", "唱": "语义：“唱”与处理旧货无关，“要分开唱”句意不通。", "吃": "搭配：旧货不能被“吃”，“分开吃”不成搭配。", "睡": "语义：“睡”与处理旧货无关，句意不通。"}, "sentence_index": 0, "correct_answer": "区处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把蛋糕区处成小块。", "explanation": "这里应该用〈切〉。“区处”指处理、安排，把蛋糕切成小块要用〈切〉。"}, {"text": "他把成熟的苹果区处下来。", "explanation": "这里应该用〈摘〉。“区处”不指从树上取下果实，摘苹果要用〈摘〉。"}, {"text": "理发师把头发区处短了。", "explanation": "这里应该用〈剪〉。“区处”不指修剪头发，把头发剪短要用〈剪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区处", "is_correct": true, "explanation": "“区处”指分别处理、安排，此处指按轻重缓急处置急件，符合句意。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”与处理急件无关，“按轻重缓急喂”句意不通。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：急件不能被“卖”，“卖急件”不成搭配。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”与处置文件无关，“按轻重缓急踢”句意不通。"}], "explanations": {"区处": "“区处”指分别处理、安排，此处指按轻重缓急处置急件，符合句意。", "喂": "语义：“喂”与处理急件无关，“按轻重缓急喂”句意不通。", "卖": "搭配：急件不能被“卖”，“卖急件”不成搭配。", "踢": "语义：“踢”与处置文件无关，“按轻重缓急踢”句意不通。"}, "sentence_index": 6, "correct_answer": "区处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用纸巾把桌子区处得亮亮的。", "explanation": "这里应该用〈擦〉。“区处”指分别处理、安排，不指擦拭桌面；擦干净桌面要用〈擦〉。"}, {"text": "他把地区处干净。", "explanation": "这里应该用〈扫〉。“区处”不指清扫地面，把地弄干净要用〈扫〉。"}, {"text": "奶奶区处了一件毛衣。", "explanation": "这里应该用〈织〉。“区处”不指编织衣物，织毛衣要用〈织〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些书要先分开区处过。", "corrected_sentence": "这些书要先分开区处。", "error_description": "错误：“要……区处过”；正确：“要……区处”。“过”表示已经历的事，不能用于“要”引出的尚未发生的动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把堆积的文件逐份区处了完。", "corrected_sentence": "老板把堆积的文件逐份区处完了。", "error_description": "错误：“区处了完”；正确：“区处完了”。结果补语“完”应紧跟动词“区处”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
