INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西在全部里面占了多少。", "primary_collocate": null, "pronunciation": "zhàn bǐ", "ipa": "ʈʂan⁵¹ pi²¹⁴", "syllable_count": 2, "sentences": [{"text": "这个月，房租的占比最大。", "target_word": "占比", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "苹果在水果销量中的占比不高。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女生在我们班的占比是六成。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工资在家庭收入里占比很高。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭的占比，比交通的占比高。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老年人的占比每年都在上升。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请算一下每种菜的占比。", "target_word": "占比", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家的开支里，教育的占比最大。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店网上订单的占比已经过半。", "target_word": "占比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色衣服在衣柜里的占比不到一半。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某样东西在全部中占多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39a6f9bc-591a-4f48-89d4-a7b21a9a7282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利息", "is_correct": false, "explanation": "搭配：“利息”指借款或存款产生的钱，不能说“房租的利息”。"}, {"text": "占比", "is_correct": true, "explanation": "“占比”指某部分在全部中所占的比例，与“最大”搭配，说明房租在开支中所占份额最多。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：“时刻”指某个时间点，不能与“最大”搭配表示程度。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，与房租无关，不能说“房租的人口”。"}], "explanations": {"利息": "搭配：“利息”指借款或存款产生的钱，不能说“房租的利息”。", "占比": "“占比”指某部分在全部中所占的比例，与“最大”搭配，说明房租在开支中所占份额最多。", "时刻": "语义：“时刻”指某个时间点，不能与“最大”搭配表示程度。", "人口": "语义：“人口”指人的数量，与房租无关，不能说“房租的人口”。"}, "sentence_index": 0, "correct_answer": "占比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张地图按占比画得很准确。", "explanation": "这里应该用〈比例〉。“按比例画”指按同样的缩放比例画图，“占比”指部分在整体中所占的份额，不能用来说明缩放。"}, {"text": "这种液体的占比是一点二。", "explanation": "这里应该用〈比重〉。“占比”不会超过整体，而比重是物质密度与水密度的比值，可以是一点二。"}, {"text": "这条河的占比很长。", "explanation": "这里应该用〈长度〉。“占比”表示部分在整体中的比例，不能用来描述河流的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不能用于“每种菜”。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”用于人或动植物，不能说“每种菜的性别”。"}, {"text": "占比", "is_correct": true, "explanation": "“占比”指每种菜在全部中所占的比例，是这句话要算的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物存在的时间，不能用于菜品。"}], "explanations": {"体重": "搭配：“体重”指人或动物的重量，不能用于“每种菜”。", "性别": "语义：“性别”用于人或动植物，不能说“每种菜的性别”。", "占比": "“占比”指每种菜在全部中所占的比例，是这句话要算的对象。", "年龄": "语义：“年龄”指人或生物存在的时间，不能用于菜品。"}, "sentence_index": 6, "correct_answer": "占比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的占比是三比一。", "explanation": "这里应该用〈比分〉。“占比”指部分在整体中所占的份额，不能表示比赛的得分。"}, {"text": "这两个数的占比是二。", "explanation": "这里应该用〈比值〉。“占比”指部分占整体的份额，不表示两数相除的结果。"}, {"text": "这辆车的占比很快。", "explanation": "这里应该用〈速度〉。“占比”描述部分与整体的比例，不能用来说明快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月，水电费的占比了最大。", "corrected_sentence": "这个月，水电费的占比最大。", "error_description": "“占比”是名词，后面不能直接加“了”。应改为“这个月，水电费的占比最大。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试，理科占比的最大。", "corrected_sentence": "这次考试，理科占比最大。", "error_description": "“占比最大”中“占比”后不能加“的”，加了“的”后结构不通顺。应改为“这次考试，理科占比最大。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
