INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一部分在整体中所占的比例。", "primary_collocate": null, "pronunciation": "zhàn bǐ", "ipa": "ʈʂan⁵¹ pi²¹⁴", "syllable_count": 2, "sentences": [{"text": "农业在国内生产总值中的占比逐年下降。", "target_word": "占比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的绿地占比达到了四成。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男性读者的占比从三成升到五成。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "进口产品的占比越来越小。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司总收入中，海外市场的占比是多少？", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青年员工在公司的占比约为四成。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新能源车在新车销量中的占比大大提高。", "target_word": "占比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告列出了各部门预算的占比。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的成本占比过高，需要降低。", "target_word": "占比", "complexity_tier": "T3", "furigana": "zhè jiā gōngsī de chéngběn zhànbǐ guò gāo, xūyào jiàngdī", "sentence_source": "generated"}, {"text": "全班同学中，近视的占比超过一半。", "target_word": "占比", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "部分在整体中所占的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39a6f9bc-591a-4f48-89d4-a7b21a9a7282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指生物存活的时间，不能用于国内生产总值这类经济指标。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”指劳动报酬，不能说“在国内生产总值中的工资”。"}, {"text": "占比", "is_correct": true, "explanation": "“占比”指农业在国内生产总值中所占的比例，与“逐年下降”搭配，说明比例在减少。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，与经济指标无关。"}], "explanations": {"寿命": "语义：“寿命”指生物存活的时间，不能用于国内生产总值这类经济指标。", "工资": "搭配：“工资”指劳动报酬，不能说“在国内生产总值中的工资”。", "占比": "“占比”指农业在国内生产总值中所占的比例，与“逐年下降”搭配，说明比例在减少。", "温度": "语义：“温度”指冷热程度，与经济指标无关。"}, "sentence_index": 0, "correct_answer": "占比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种金属的占比是七点八。", "explanation": "这里应该用〈比重〉。“占比”不会超过整体，而比重是物质密度与水密度之比，铁的比重就是七点八。"}, {"text": "药品要按照占比加水稀释。", "explanation": "这里应该用〈比例〉。“按比例”指按一定配比加水，“占比”指部分占整体的份额，不能表示配比。"}, {"text": "这把椅子的占比很贵。", "explanation": "这里应该用〈价格〉。“占比”描述部分与整体的份额，不能用来说明价钱的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高度，不能用于新能源车。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物的岁数，与车辆的销量无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“大大提高”搭配。"}, {"text": "占比", "is_correct": true, "explanation": "“占比”指新能源车在新车销量中所占的比例，“大大提高”说明这个比例明显增长。"}], "explanations": {"身高": "体貌：“身高”指人的身体高度，不能用于新能源车。", "年龄": "语义：“年龄”指人或生物的岁数，与车辆的销量无关。", "颜色": "搭配：“颜色”不能与“大大提高”搭配。", "占比": "“占比”指新能源车在新车销量中所占的比例，“大大提高”说明这个比例明显增长。"}, "sentence_index": 6, "correct_answer": "占比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的占比是三比一。", "explanation": "这里应该用〈比分〉。“占比”指部分在整体中所占的份额，不能表示比赛的得分。"}, {"text": "这两个数的占比是二。", "explanation": "这里应该用〈比值〉。“占比”指部分占整体的份额，不表示两数相除的结果。"}, {"text": "这箱苹果的占比很重。", "explanation": "这里应该用〈重量〉。“占比”描述部分与整体的比例，不能用来说明轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一年，外贸的占比了逐年上升。", "corrected_sentence": "这一年，外贸的占比逐年上升。", "error_description": "“占比”是名词，后面不能直接加“了”。应改为“这一年，外贸的占比逐年上升。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新能源车在新车销量中占比了大大提高。", "corrected_sentence": "新能源车在新车销量中占比大大提高。", "error_description": "“占比”是名词，后面不能直接加“了”。应改为“新能源车在新车销量中占比大大提高。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
