INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某些国家两院制议会中的上议院，如美国参议院。", "primary_collocate": null, "pronunciation": "cān yì yuàn", "ipa": "tsʰan˥ i˥˩ ɥæn˥˩", "syllable_count": 3, "sentences": [{"text": "美国国会有两个院，参议院是其中一个。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国参议院一共有一百位参议员。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统的计划要先得到参议院同意。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议院和众议院一起组成国会。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经在参议院工作了二十年。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议院的人数比众议院少。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位参议员代表他的州进入参议院。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参议院投票后，这个法律才能生效。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国的参议院每个州有两个名额。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想成为参议院里最年轻的一位。", "target_word": "参议院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "参议员", "label": "复合"}], "register": "正式", "sense_fingerprint": "两院制议会中的上议院，如美国参议院", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参议院", "is_correct": true, "explanation": "“参议院”是两院制议会中的一院，正是句中“两个院”中的其中一个。"}, {"text": "国会", "is_correct": false, "explanation": "语义：“国会”是两院的总称，不能与“两个院”中的一个并列。"}, {"text": "议员", "is_correct": false, "explanation": "语义：议员是人，不是议会中的一个院，不能作为“两个院”的其中一个。"}, {"text": "州", "is_correct": false, "explanation": "搭配：“其中一个”指“两个院”中的一个，“州”不能作为院的并列成分。"}], "explanations": {"参议院": "“参议院”是两院制议会中的一院，正是句中“两个院”中的其中一个。", "国会": "语义：“国会”是两院的总称，不能与“两个院”中的一个并列。", "议员": "语义：议员是人，不是议会中的一个院，不能作为“两个院”的其中一个。", "州": "搭配：“其中一个”指“两个院”中的一个，“州”不能作为院的并列成分。"}, "sentence_index": 0, "correct_answer": "参议院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参议院的病房很干净。", "explanation": "这里应该用〈医院〉。参议院是立法机构，没有病房，“病房很干净”应说“医院”。"}, {"text": "参议院的利率很低。", "explanation": "这里应该用〈银行〉。参议院不决定利率，利率属于银行的业务，应说“银行”。"}, {"text": "参议院的牛奶很新鲜。", "explanation": "这里应该用〈超市〉。参议院不卖食品，“牛奶很新鲜”是超市商品的特点，应说“超市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，参议员代表州去那里与句意不符。"}, {"text": "参议院", "is_correct": true, "explanation": "“参议院”是议会机构，参议员代表州进入参议院，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是存放食物的电器，与参议员的政治活动不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“进入”的处所应为场所或机构，不能说“进入眼睛”。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，参议员代表州去那里与句意不符。", "参议院": "“参议院”是议会机构，参议员代表州进入参议院，符合句意。", "冰箱": "语义：冰箱是存放食物的电器，与参议员的政治活动不符。", "眼睛": "搭配：“进入”的处所应为场所或机构，不能说“进入眼睛”。"}, "sentence_index": 6, "correct_answer": "参议院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想当最年轻的参议院。", "explanation": "这里应该用〈参议员〉。参议院是机构，不能用来指担任职务的人，应说“参议员”。"}, {"text": "这起官司要由参议院来审理。", "explanation": "这里应该用〈法院〉。参议院负责立法，审理官司应说“法院”。"}, {"text": "参议院负责执行法律。", "explanation": "这里应该用〈政府〉。参议院是立法机构，执行法律由政府负责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只美国参议院有一百个席位。", "corrected_sentence": "这个美国参议院有一百个席位。", "error_description": "量词错误：“参议院”是机构，量词应用“个”，说“这个美国参议院”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经访问过过美国的参议院。", "corrected_sentence": "他曾经访问过美国的参议院。", "error_description": "体标记重复：“过”只用一次，紧跟动词“访问”，说“访问过美国的参议院”，“过过”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
