INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不能忍受；承受不住。", "primary_collocate": null, "pronunciation": "shòu bu liǎo", "ipa": "ʂoʊ̯˥˩ pu liɑʊ̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "今天太热了，我真的受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里太吵了，我一分钟也受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天抽烟，我受不了那个味道。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙疼得厉害，他疼得受不了，去看医生。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板要求太多，工作压力大，他受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天这么冷，没有暖气我可受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我受不了他一直说别人的坏话。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么重的行李，小孩一个人肯定受不了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里又闷又臭，大家都受不了，开了窗。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的坏脾气，同事们早就受不了了。", "target_word": "受不了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受得了", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "对热、吵、痛、压力等不能忍受，承受不住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '835b18fe-03f2-4221-8887-eff8b608d335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受不了", "is_correct": true, "explanation": "受不了：承受不住天热，与“今天太热了”的语境吻合。"}, {"text": "享受", "is_correct": false, "explanation": "配价：“享受”需要带宾语，单独用在这里说不通。"}, {"text": "满意", "is_correct": false, "explanation": "语义：“满意”表示称心，与“太热”的抱怨语境相反，句子矛盾。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：“乐意”表示愿意，与“太热”的语境不符，单独说在这里不通顺。"}], "explanations": {"受不了": "受不了：承受不住天热，与“今天太热了”的语境吻合。", "享受": "配价：“享受”需要带宾语，单独用在这里说不通。", "满意": "语义：“满意”表示称心，与“太热”的抱怨语境相反，句子矛盾。", "乐意": "语义：“乐意”表示愿意，与“太热”的语境不符，单独说在这里不通顺。"}, "sentence_index": 0, "correct_answer": "受不了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到父亲离开的消息，她心里难受，却受不了地笑了起来。", "explanation": "这里应该用〈忍不住〉。“受不了”表示承受不住，不能表示控制不住地笑出来，应说“忍不住笑了起来”。"}, {"text": "这件事他默默受不了十年，从不抱怨。", "explanation": "这里应该用〈忍耐〉。“受不了”表示承受不住、忍不下去，不能表示长期压住不说，与“从不抱怨”也对不上。"}, {"text": "看着亲人受苦，他冷静得受不了，脸上一点表情都没有。", "explanation": "这里应该用〈冷静〉。“受不了”表示承受不住，不能用来形容冷静得一点表情都没有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受不了", "is_correct": true, "explanation": "受不了：承受不住他的唠叨，与“他一直说别人的坏话”引起的烦扰相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱，与“说别人的坏话”的厌烦语气相反。"}, {"text": "赞同", "is_correct": false, "explanation": "语义：“赞同”表示认可，不能用来表示忍不住某人的坏话，句意矛盾。"}, {"text": "钦佩", "is_correct": false, "explanation": "语域：“钦佩”偏书面，与口语的抱怨语境不符，而且语义也相反。"}], "explanations": {"受不了": "受不了：承受不住他的唠叨，与“他一直说别人的坏话”引起的烦扰相合。", "欣赏": "语义：“欣赏”表示喜爱，与“说别人的坏话”的厌烦语气相反。", "赞同": "语义：“赞同”表示认可，不能用来表示忍不住某人的坏话，句意矛盾。", "钦佩": "语域：“钦佩”偏书面，与口语的抱怨语境不符，而且语义也相反。"}, "sentence_index": 6, "correct_answer": "受不了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "想到奶奶，他受不了地坐在台阶上，一直看着天。", "explanation": "这里应该用〈发呆〉。“受不了”表示承受不住，不能修饰坐着发呆的动作。"}, {"text": "他拼命受不了眼泪，不肯在人前掉一滴。", "explanation": "这里应该用〈忍住〉。“受不了”是承受不住某种刺激，不能表示主动压抑眼泪，与“拼命”的意思不符。"}, {"text": "我们一起去爬山，他一路上受不了地唱着歌，从不喊累。", "explanation": "这里应该用〈坚持〉。“受不了”表示承受不住、忍不下去，不能表示坚持着做某事，这里应说“坚持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么吵的音乐，吵我实在受不了。", "corrected_sentence": "这么吵的音乐，吵得我实在受不了。", "error_description": "补语标记缺失：“吵”后接程度补语要用“得”，应说“吵得我实在受不了”，不能省掉“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个味道太刺鼻，我真的受得了。", "corrected_sentence": "这个味道太刺鼻，我真的受不了。", "error_description": "肯定否定错误：“太刺鼻”说明难以忍受，应说“受不了”；“受得了”表示能承受，与语境相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
