INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96341, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国王或皇帝的儿子，以后会当国王。", "primary_collocate": null, "pronunciation": "tài zǐ", "ipa": "tʰai˥˩ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "国王有三个儿子，大儿子是太子。", "target_word": "太子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皇帝的儿子叫太子，以后要当皇帝。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小太子今年七岁，爱和小朋友玩。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太子长大以后，会成为新的国王。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的太子住在很大的王宫里。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王很爱他的儿子，也就是太子。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太子每天都要读书，学习怎么管理国家。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太子骑着马，走进了王宫。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看过一个电影，里面的太子很勇敢。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王老了，太子要来帮他做事。", "target_word": "太子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太子妃", "label": "复合"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "国王或皇帝的儿子，将来要当国王", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96341, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "太子", "is_correct": true, "explanation": "tài zǐ 指国王或皇帝的儿子，将来要当国王。"}, {"text": "台子", "is_correct": false, "explanation": "台子 táizi 第一个音节声调与 tài 不同（阳平与去声），意思是桌子、平台。"}, {"text": "盖子", "is_correct": false, "explanation": "盖子 gàizi 第一个音节声母不同（g 与 t），声调相同，意思是盖儿。"}, {"text": "菜子", "is_correct": false, "explanation": "菜子 càizi 第一个音节声母不同（c 与 t），意思是菜籽。"}, {"text": "袋子", "is_correct": false, "explanation": "袋子 dàizi 第一个音节声母不同（d 与 t），声调相同，意思是口袋。"}], "explanations": {"太子": "tài zǐ 指国王或皇帝的儿子，将来要当国王。", "台子": "台子 táizi 第一个音节声调与 tài 不同（阳平与去声），意思是桌子、平台。", "盖子": "盖子 gàizi 第一个音节声母不同（g 与 t），声调相同，意思是盖儿。", "菜子": "菜子 càizi 第一个音节声母不同（c 与 t），意思是菜籽。", "袋子": "袋子 dàizi 第一个音节声母不同（d 与 t），声调相同，意思是口袋。"}, "sentence_index": null, "correct_answer": "太子"}, "level_3": {"options": [{"text": "太子", "is_correct": true, "explanation": "太子指国王或皇帝的儿子，将来要当国王，这里指国王的大儿子。"}, {"text": "公主", "is_correct": false, "explanation": "语义：“公主”指女儿，与前文“大儿子”的性别不符，句意不通。"}, {"text": "皇后", "is_correct": false, "explanation": "语义：“皇后”指皇帝的妻子，不能是儿子的身份，句意不通。"}, {"text": "王宫", "is_correct": false, "explanation": "搭配：“是”后接的是身份，“王宫”是场所，不能用来指儿子的身份。"}], "explanations": {"太子": "太子指国王或皇帝的儿子，将来要当国王，这里指国王的大儿子。", "公主": "语义：“公主”指女儿，与前文“大儿子”的性别不符，句意不通。", "皇后": "语义：“皇后”指皇帝的妻子，不能是儿子的身份，句意不通。", "王宫": "搭配：“是”后接的是身份，“王宫”是场所，不能用来指儿子的身份。"}, "sentence_index": 0, "correct_answer": "太子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个太子不会当国王，他的哥哥才是继承人。", "explanation": "这里应该用〈王子〉。“太子”专指已被确定将来继承王位的儿子，不会继承王位的国王之子只能称王子。"}, {"text": "大儿子是太子，但他不是继承人。", "explanation": "这里应该用〈长子〉。“太子”是被确定的继承人，不等于年龄最大的儿子。"}, {"text": "这个太子今年五十岁，已经在位三十年。", "explanation": "这里应该用〈君主〉。“太子”指将来要继承王位的人，已经在位的君主不能称太子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96341, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "太子", "is_correct": true, "explanation": "tài zǐ 指国王或皇帝的儿子，将来要当国王。"}, {"text": "带子", "is_correct": false, "explanation": "dài（去声）与 tài 声母不同（d 与 t），声调相同，意思是腰带、绳带。"}, {"text": "寨子", "is_correct": false, "explanation": "zhài（去声）与 tài 声母不同（zh 与 t），声调相同，意思是村寨。"}, {"text": "梯子", "is_correct": false, "explanation": "tī zi 韵母不同（i 与 ai），声母相同，声调也不同，意思是梯子。"}], "explanations": {"太子": "tài zǐ 指国王或皇帝的儿子，将来要当国王。", "带子": "dài（去声）与 tài 声母不同（d 与 t），声调相同，意思是腰带、绳带。", "寨子": "zhài（去声）与 tài 声母不同（zh 与 t），声调相同，意思是村寨。", "梯子": "tī zi 韵母不同（i 与 ai），声母相同，声调也不同，意思是梯子。"}, "sentence_index": null, "correct_answer": "太子"}, "level_3": {"options": [{"text": "太子", "is_correct": true, "explanation": "太子指国王或皇帝的儿子，将来要当国王，这里指学习管理国家的继承人。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”不具备学习管理国家的身份，句意不通。"}, {"text": "丫鬟", "is_correct": false, "explanation": "语义：“丫鬟”是服侍主人的人，与“学习怎么管理国家”的内容不符。"}, {"text": "皇宫", "is_correct": false, "explanation": "搭配：“每天都要读书”的主语应是人，“皇宫”是场所，不能作动作的主语。"}], "explanations": {"太子": "太子指国王或皇帝的儿子，将来要当国王，这里指学习管理国家的继承人。", "农民": "语义：“农民”不具备学习管理国家的身份，句意不通。", "丫鬟": "语义：“丫鬟”是服侍主人的人，与“学习怎么管理国家”的内容不符。", "皇宫": "搭配：“每天都要读书”的主语应是人，“皇宫”是场所，不能作动作的主语。"}, "sentence_index": 6, "correct_answer": "太子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个女孩是太子，将来要当皇帝。", "explanation": "这里应该用〈公主〉。“太子”专指男性继承人，国王的女儿只能称公主，将来即使继位也不称太子。"}, {"text": "国王的三个儿子都叫太子。", "explanation": "这里应该用〈王子〉。“太子”只能指一个被确定的继承人，其余的儿子只能称王子。"}, {"text": "太子是国王的弟弟，将来要继承王位。", "explanation": "这里应该用〈王弟〉。“太子”指国王的儿子，国王的弟弟不能称太子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宫里来了一只太子，大家都很惊讶。", "corrected_sentence": "宫里来了一位太子，大家都很惊讶。", "error_description": "错误：量词用了“只”。“只”用于动物，“太子”指人，应用量词“位”，正确说法是“宫里来了一位太子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国王宣布了一只新太子，宫里很热闹。", "corrected_sentence": "国王宣布了一位新太子，宫里很热闹。", "error_description": "错误：量词用了“只”。“只”多用于动物，“太子”指人，应用量词“位”，正确说法是“国王宣布了一位新太子，宫里很热闹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
