INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校为每名学生编定的识别号码。", "primary_collocate": null, "pronunciation": "xué hào", "ipa": "ɕɥe˧˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "新生报到时，学校会发给他们学号。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用学号可以查到你的考试成绩。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学号由学校统一编定，不能自己改。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请输入学号和密码，登录学校网站。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的学号前四位，是入学的年份。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借书的时候，要用学号办借书证。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生证丢了，可以凭学号去补办。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宿舍门口的表格上，要填姓名和学号。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师按学号顺序，一个一个检查作业。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转学以后，他得到了新的学号。", "target_word": "学号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "學號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校统一编定、用来识别学生的号码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '835b18fe-03f2-4221-8887-eff8b608d335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学号", "is_correct": true, "explanation": "正确：“学号”是学校发给新生的编号，与“发给他们”搭配。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的钱，不会由学校发给新生。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位要在毕业后才授予，不会在新生报到时发给。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体的分量，不是学校发给新生的东西。"}], "explanations": {"学号": "正确：“学号”是学校发给新生的编号，与“发给他们”搭配。", "学费": "语义：学费是学生交给学校的钱，不会由学校发给新生。", "学位": "语义：学位要在毕业后才授予，不会在新生报到时发给。", "体重": "体貌：“体重”是身体的分量，不是学校发给新生的东西。"}, "sentence_index": 0, "correct_answer": "学号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的学号写在前面。", "explanation": "这里应该用〈车牌号〉。车辆的号码称车牌号，学号只指学校编给学生的号码。"}, {"text": "每件行李都有学号。", "explanation": "这里应该用〈编号〉。行李的顺序号一般说编号，学号专指学生。"}, {"text": "银行卡的学号可以在背面找到。", "explanation": "这里应该用〈卡号〉。银行卡的号码称卡号，学号只用于学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学号", "is_correct": true, "explanation": "正确：凭“学号”可以在学校补办，符合语境。"}, {"text": "笔记", "is_correct": false, "explanation": "语义：笔记是记录内容的本子，不能凭它去补办学生证。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体器官，不能凭它去办理手续。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，与补办学生证无关。"}], "explanations": {"学号": "正确：凭“学号”可以在学校补办，符合语境。", "笔记": "语义：笔记是记录内容的本子，不能凭它去补办学生证。", "眼睛": "体貌：“眼睛”是身体器官，不能凭它去办理手续。", "书包": "语义：书包是装东西的袋子，与补办学生证无关。"}, "sentence_index": 6, "correct_answer": "学号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "转学以后，他得到了一张新的学号。", "explanation": "这里应该用〈个〉。〈张〉用于平面的东西，学号不能用“张”来计量。"}, {"text": "转学以后，他得到了一双新的学号。", "explanation": "这里应该用〈个〉。〈双〉用于成对的东西，学号不能用“双”来计量。"}, {"text": "转学以后，他得到了一件新的学号。", "explanation": "这里应该用〈个〉。〈件〉多用于衣物、事情等，学号不能用“件”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学号改了过一次。", "corrected_sentence": "学号改过一次。", "error_description": "“了”与“过”不能同用。“改过”已表示曾经改动，中间加“了”不通，应为“学号改过一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一下子背得不出学号。", "corrected_sentence": "我一下子背不出学号。", "error_description": "补语错误：可能补语的否定形式是“背不出”，不能说“背得不出”，应为“我一下子背不出学号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d19f148-fa31-4462-8c9c-ecf91a39ff4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
