INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拿到别人给的东西的人。", "primary_collocate": null, "pronunciation": "jiē shòu zhě", "ipa": "tɕjɛ˧˥ ʂoʊ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这笔捐款的接受者是一所小学。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "礼物的接受者看到卡片，笑了。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "器官捐献者和接受者从没见过面。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份奖学金的接受者将在周五公布。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个接受者都能领到一袋大米。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这次爱心捐助的接受者之一。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "捐赠者把书送给了接受者。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "器官移植的接受者需要长期服药。", "target_word": "接受者", "complexity_tier": "T3", "furigana": "qì guān yí zhí de jiē shòu zhě xū yào cháng qī fú yào.", "sentence_source": "generated"}, {"text": "这批救济物资的接受者是谁？", "target_word": "接受者", "complexity_tier": "T3", "furigana": "zhè pī jiù jì wù zī de jiē shòu zhě shì shéi?", "sentence_source": "generated"}, {"text": "接受者收到包裹后，给我们回了信。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "收到别人捐赠、赠送的东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不可能是一所小学，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是物，不能与“一所小学”同指，句意不通。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受别人给的东西（此处是捐款）的一方，指接受这笔捐款的小学。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是机构，不能与“一所小学”同指，句意不通。"}], "explanations": {"学生": "语义：学生是人，不可能是一所小学，句意不通。", "汽车": "语义：汽车是物，不能与“一所小学”同指，句意不通。", "接受者": "接受者：接受别人给的东西（此处是捐款）的一方，指接受这笔捐款的小学。", "医院": "语义：医院是机构，不能与“一所小学”同指，句意不通。"}, "sentence_index": 0, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "接受者把书送给了一所小学。", "explanation": "这里应该用〈捐赠者〉。接受者是拿到东西的一方，不会把东西送出去；“送”的一方要用捐赠者。"}, {"text": "这次比赛的接受者有三百人。", "explanation": "这里应该用〈参赛者〉。接受者指拿到别人给的东西的人，比赛的参与者要用参赛者。"}, {"text": "那位接受者按时走进了面试室。", "explanation": "这里应该用〈面试者〉。接受者指拿到东西的人，走进面试室接受面试的人要用面试者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书", "is_correct": false, "explanation": "语义：“书”是物，不能作为“送给”的接受对象，句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“送给”要求有生命的接受对象，“空气”不能接受东西。"}, {"text": "捐赠者", "is_correct": false, "explanation": "语义：“捐赠者”是送出东西的人，前文已经占据了这个角色，不能同时作为接受者。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受别人给的东西的人，此处指收到书的人。"}], "explanations": {"书": "语义：“书”是物，不能作为“送给”的接受对象，句子不通。", "空气": "配价：“送给”要求有生命的接受对象，“空气”不能接受东西。", "捐赠者": "语义：“捐赠者”是送出东西的人，前文已经占据了这个角色，不能同时作为接受者。", "接受者": "接受者：接受别人给的东西的人，此处指收到书的人。"}, "sentence_index": 6, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的接受者笑着迎接每位客人。", "explanation": "这里应该用〈接待者〉。接受者指拿到别人给的东西的人，在门口迎接、招呼客人的要用接待者。"}, {"text": "他是公司的接受者，三年后将接任总经理。", "explanation": "这里应该用〈接班人〉。接受者指拿到别人给的东西的人，接替职位的要用接班人。"}, {"text": "总机的接受者接转了电话。", "explanation": "这里应该用〈接线员〉。接受者指拿到别人给的东西的人，负责接转电话的要用接线员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位很高接受者在门口等着。", "corrected_sentence": "那位很高的接受者在门口等着。", "error_description": "结构助词漏用：“很高”修饰“接受者”时要用“的”，应说“那位很高的接受者”，不能漏掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那批物资得接受者是我们学校。", "corrected_sentence": "那批物资的接受者是我们学校。", "error_description": "结构助词误用：修饰名词要用“的”，不能用“得”（“得”用于补语）。应为“那批物资的接受者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
