INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接受某物或某事的人。", "primary_collocate": null, "pronunciation": "jiē shòu zhě", "ipa": "tɕjɛ˧˥ ʂoʊ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "新药的接受者要每天记录体温。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这种教育方式的接受者。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项治疗的接受者大多是老人。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为信息的接受者，我们要学会判断。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查显示，培训的接受者都很满意。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接受者对新规定没有意见。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法的接受者越来越多。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术的接受者需要在医院住三天。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子是家庭教育的接受者。", "target_word": "接受者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项补贴政策的接受者需要提交材料。", "target_word": "接受者", "complexity_tier": "T3", "furigana": "zhè xiàng bǔ tiē zhèng cè de jiē shòu zhě xū yào tí jiāo cái liào.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "接受治疗、教育、信息等事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "配价：“记录体温”要求有体温的主体，“椅子”不能作为记录者。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是需要服药的人，句子说它要记录体温，不合情理。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受某种药物或治疗的人，此处指服用新药的人。"}, {"text": "药剂", "is_correct": false, "explanation": "语义：药剂是药物本身，不会服药，也不会记录体温。"}], "explanations": {"椅子": "配价：“记录体温”要求有体温的主体，“椅子”不能作为记录者。", "电脑": "语义：电脑不是需要服药的人，句子说它要记录体温，不合情理。", "接受者": "接受者：接受某种药物或治疗的人，此处指服用新药的人。", "药剂": "语义：药剂是药物本身，不会服药，也不会记录体温。"}, "sentence_index": 0, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次手术的接受者是张大夫。", "explanation": "这里应该用〈医生〉。接受者指接受治疗的人，做手术的人要用医生。"}, {"text": "接受者在会上介绍了新政策。", "explanation": "这里应该用〈发言人〉。接受者指接收服务或信息的人，在会上介绍政策的要用发言人。"}, {"text": "接受者为顾客端来了热水。", "explanation": "这里应该用〈服务员〉。接受者指接受某物或某事的人，为顾客服务的要用服务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能成为接受想法的对象，句子说它越来越多也不合理。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能接受想法，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”与“越来越多”不搭配，不能说“空气越来越多”。"}, {"text": "接受者", "is_correct": true, "explanation": "接受者：接受这个想法的人，指赞同或接受该想法的人。"}], "explanations": {"石头": "语义：石头不是人，不能成为接受想法的对象，句子说它越来越多也不合理。", "桌子": "语义：桌子是家具，不能接受想法，句意不通。", "空气": "搭配：“空气”与“越来越多”不搭配，不能说“空气越来越多”。", "接受者": "接受者：接受这个想法的人，指赞同或接受该想法的人。"}, "sentence_index": 6, "correct_answer": "接受者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前台的接受者正在修电脑。", "explanation": "这里应该用〈技术员〉。接受者指接受某物或某事的人，修电脑的要用技术员。"}, {"text": "他是这家店的接受者，每天负责煮咖啡。", "explanation": "这里应该用〈咖啡师〉。接受者指接受某物或某事的人，负责煮咖啡的要用咖啡师。"}, {"text": "这位接受者负责设计公司的网站。", "explanation": "这里应该用〈设计师〉。接受者指接受某物或某事的人，负责设计网站的要用设计师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位很年轻接受者参加了这次培训。", "corrected_sentence": "一位很年轻的接受者参加了这次培训。", "error_description": "结构助词漏用：“很年轻”修饰“接受者”时要加“的”，应为“一位很年轻的接受者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次培训得接受者都拿到了证书。", "corrected_sentence": "那次培训的接受者都拿到了证书。", "error_description": "结构助词误用：修饰名词要用“的”，不能用“得”。应为“那次培训的接受者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96375, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "进入：走进某处，与撤离的意思相反。"}, {"text": "学习", "is_correct": false, "explanation": "与撤离没有反义关系，学习与离开某地无关。"}, {"text": "思考", "is_correct": false, "explanation": "与撤离没有反义关系，思考不涉及位置的转移。"}, {"text": "写信", "is_correct": false, "explanation": "与撤离没有反义关系，写信不涉及离开或进入。"}], "correct_answer": "进入", "explanations": {"进入": "进入：走进某处，与撤离的意思相反。", "学习": "与撤离没有反义关系，学习与离开某地无关。", "思考": "与撤离没有反义关系，思考不涉及位置的转移。", "写信": "与撤离没有反义关系，写信不涉及离开或进入。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
