INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96383, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多年以前传下来、大家一直在过的节日和习惯。", "primary_collocate": null, "pronunciation": "wén huà chuán tǒng", "ipa": "wən˧˥ xwa˥˩ ʈʂʰwan˧˥ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "春节是中国很重要的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃月饼是中秋节的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家有一个文化传统，每年都一起包饺子。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "端午节赛龙舟是很老的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，这个文化传统已经有上千年了。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年给孩子红包是一种文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解你们国家的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子还留着很多文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元宵节吃汤圆，是我们的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常给我讲家乡的文化传统。", "target_word": "文化传统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "文化傳統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "文化传统:传下来的节日和习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文化传统", "is_correct": true, "explanation": "正确。“文化传统”指传下来的节日和习惯，春节符合这一说法。"}, {"text": "经济发展", "is_correct": false, "explanation": "语义：春节是节日，不是“经济发展”，句子说春节是“重要的经济发展”，句意不通。"}, {"text": "科学技术", "is_correct": false, "explanation": "语义：“科学技术”是学科或技术体系，不能指节日，句意不通。"}, {"text": "交通规则", "is_correct": false, "explanation": "语义：“交通规则”是交通管理的规定，不能指节日，句意不通。"}], "explanations": {"文化传统": "正确。“文化传统”指传下来的节日和习惯，春节符合这一说法。", "经济发展": "语义：春节是节日，不是“经济发展”，句子说春节是“重要的经济发展”，句意不通。", "科学技术": "语义：“科学技术”是学科或技术体系，不能指节日，句意不通。", "交通规则": "语义：“交通规则”是交通管理的规定，不能指节日，句意不通。"}, "sentence_index": 0, "correct_answer": "文化传统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天睡前读书，这是我的文化传统。", "explanation": "这里应该用〈习惯〉。个人每天的做法是个人习惯，不是很多年前传下来、大家一起过的节日或习俗。"}, {"text": "我有一个好文化传统：每天早起锻炼。", "explanation": "这里应该用〈习惯〉。“文化传统”指一个群体世代相传的习俗，个人的日常做法只能说习惯。"}, {"text": "他的文化传统是打篮球。", "explanation": "这里应该用〈爱好〉。个人的兴趣是爱好，不是大家一起过的节日或习俗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文化传统", "is_correct": true, "explanation": "正确。“文化传统”指一个民族或群体世代相传的习俗，句中指的是对方国家的这类内容。"}, {"text": "心跳速度", "is_correct": false, "explanation": "语义：“心跳速度”是生理指标，不是国家的习俗或观念，“了解你们国家的心跳速度”句意不通。"}, {"text": "眼睛颜色", "is_correct": false, "explanation": "语义：“眼睛颜色”是外貌特征，不是国家的习俗或观念，句意不通。"}, {"text": "头发长度", "is_correct": false, "explanation": "语义：“头发长度”是外貌特征，不是国家的习俗或观念，句意不通。"}], "explanations": {"文化传统": "正确。“文化传统”指一个民族或群体世代相传的习俗，句中指的是对方国家的这类内容。", "心跳速度": "语义：“心跳速度”是生理指标，不是国家的习俗或观念，“了解你们国家的心跳速度”句意不通。", "眼睛颜色": "语义：“眼睛颜色”是外貌特征，不是国家的习俗或观念，句意不通。", "头发长度": "语义：“头发长度”是外貌特征，不是国家的习俗或观念，句意不通。"}, "sentence_index": 6, "correct_answer": "文化传统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家里的文化传统是晚上十点前必须回家。", "explanation": "这里应该用〈规矩〉。家里的规定是家人之间的约定，不是世代相传的习俗，不能叫“文化传统”。"}, {"text": "这辆车的文化传统是速度很快。", "explanation": "这里应该用〈特点〉。车的性能是产品特点，不是很多年前传下来、大家一起过的节日或习俗，不能叫“文化传统”。"}, {"text": "我的文化传统是每天写日记。", "explanation": "这里应该用〈习惯〉。个人每天的做法是个人习惯，不是很多年前传下来、大家一起过的节日或习俗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "端午节吃粽子是一只文化传统。", "corrected_sentence": "端午节吃粽子是一种文化传统。", "error_description": "量词错误：“文化传统”应用量词“种”，不能用“只”（“只”多用于动物或成对物件中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人们文化传统传下去。", "corrected_sentence": "老人们把文化传统传下去。", "error_description": "把字句遗漏：处置“文化传统”时要用“把”引出宾语，应说“老人们把文化传统传下去”，不能省去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
