INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "弯弯的线，不是直的。", "primary_collocate": null, "pronunciation": "qū xiàn", "ipa": "tɕʰy˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "小路沿着山边走成一条曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在沙滩上画曲线玩。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直线是直的，曲线是弯的。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的曲线很好看。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在空中飞出一条曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两个点连成一条曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，直线不是曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流的曲线像一条蓝带子。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车沿着曲线慢慢开上山。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用线在布上绣出曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "曲线图", "label": "复合"}], "register": "中性", "sense_fingerprint": "形状弯曲、不直的线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裙子", "is_correct": false, "explanation": "搭配：“走成”的对象应是路线或线条，不能说“走成一条裙子”。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：小路不能变成一条鱼，句意不通。"}, {"text": "曲线", "is_correct": true, "explanation": "曲线：弯弯的、不直的线，此处指小路弯弯的走向。"}, {"text": "毛巾", "is_correct": false, "explanation": "语义：毛巾是织物，小路不会变成毛巾。"}], "explanations": {"裙子": "搭配：“走成”的对象应是路线或线条，不能说“走成一条裙子”。", "鱼": "语义：小路不能变成一条鱼，句意不通。", "曲线": "曲线：弯弯的、不直的线，此处指小路弯弯的走向。", "毛巾": "语义：毛巾是织物，小路不会变成毛巾。"}, "sentence_index": 0, "correct_answer": "曲线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沿着曲线直直地走，就能到山顶。", "explanation": "这里应该用〈直线〉。曲线是弯的，与“直直地走”矛盾，直的路要说直线。"}, {"text": "他用直尺在纸上画了一条曲线。", "explanation": "这里应该用〈直线〉。直尺只能画直线，弯线要用曲线板或圆规，这里曲线用错了。"}, {"text": "他的笔迹很直，像一条曲线。", "explanation": "这里应该用〈直线〉。“很直”描述的是直的线，要说直线；曲线是弯的，与“很直”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是线，“直线不是桌子”句意不通。"}, {"text": "曲线", "is_correct": true, "explanation": "曲线：弯曲的线，与直线相对，此处指“直线不是曲线”。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的外貌，不能说“直线不是脸”来对比线的形状。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，与线的形状无关，句意不通。"}], "explanations": {"桌子": "语义：桌子是家具，不是线，“直线不是桌子”句意不通。", "曲线": "曲线：弯曲的线，与直线相对，此处指“直线不是曲线”。", "脸": "体貌：脸是人的外貌，不能说“直线不是脸”来对比线的形状。", "鸡蛋": "语义：鸡蛋是食物，与线的形状无关，句意不通。"}, "sentence_index": 6, "correct_answer": "曲线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们选了一条最快的曲线去机场。", "explanation": "这里应该用〈路线〉。曲线指几何或图表中的线，选去机场的走法要用路线。"}, {"text": "他把铁丝拉直了，它现在是一条曲线。", "explanation": "这里应该用〈直线〉。铁丝拉直后是直线，不是弯的曲线，这里应说直线。"}, {"text": "他们绕了一大段曲线才找到出口。", "explanation": "这里应该用〈弯路〉。曲线指线，不指走过的路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边有一条很弯曲线。", "corrected_sentence": "路边有一条很弯的曲线。", "error_description": "结构助词漏用：“很弯”修饰“曲线”时要加“的”，应为“一条很弯的曲线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师得曲线画得很整齐。", "corrected_sentence": "老师的曲线画得很整齐。", "error_description": "结构助词误用：修饰“曲线”要用“的”，不能用“得”（“得”用于补语）。应为“老师的曲线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
