INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不是直的、弯曲的线；也指按数据画出的变化线。", "primary_collocate": null, "pronunciation": "qū xiàn", "ipa": "tɕʰy˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "图上的红色曲线越来越高。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用笔画了一条曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条曲线表示气温的变化。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水在山间划出一道曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看黑板上的曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从曲线能看出人口在增加。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球飞出一条漂亮的曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月销量的曲线一直向上。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在纸上画一条直线和一条曲线。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "曲线下降，说明价格在下跌。", "target_word": "曲线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "曲线图", "label": "复合"}], "register": "中性", "sense_fingerprint": "弯曲的线，也指表示数据变化的线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包不是图上的线，不会越来越高。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料是颜色材料，本身不会越来越高，句意不通。"}, {"text": "曲线", "is_correct": true, "explanation": "曲线：图表上表示变化的线，此处指红色的数据曲线。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：眼睛是人的外貌部位，不是图上的线，也不会越来越高。"}], "explanations": {"书包": "语义：书包不是图上的线，不会越来越高。", "颜料": "语义：颜料是颜色材料，本身不会越来越高，句意不通。", "曲线": "曲线：图表上表示变化的线，此处指红色的数据曲线。", "眼睛": "体貌：眼睛是人的外貌部位，不是图上的线，也不会越来越高。"}, "sentence_index": 0, "correct_answer": "曲线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从这里沿着曲线直直地走，就能到车站。", "explanation": "这里应该用〈直线〉。曲线是弯的，与“直直地走”矛盾，表示笔直的路要用直线。"}, {"text": "老师用直尺画了一条曲线。", "explanation": "这里应该用〈直线〉。直尺只能画直线，画弯线要用曲线板或圆规，这里曲线用错了。"}, {"text": "他的人生像一条笔直的曲线。", "explanation": "这里应该用〈直线〉。“笔直”形容直的线，要用直线；曲线是弯的，与“笔直”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：球不能飞出一条河，此处要求的是球飞行的线状路径。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，球不能飞出一条鱼。"}, {"text": "曲线", "is_correct": true, "explanation": "曲线：弯弯的路径，此处指球飞行的弧形轨迹。"}, {"text": "尾巴", "is_correct": false, "explanation": "体貌：尾巴是动物的身体部位，球不能飞出一条尾巴。"}], "explanations": {"河": "语义：球不能飞出一条河，此处要求的是球飞行的线状路径。", "鱼": "语义：鱼是动物，球不能飞出一条鱼。", "曲线": "曲线：弯弯的路径，此处指球飞行的弧形轨迹。", "尾巴": "体貌：尾巴是动物的身体部位，球不能飞出一条尾巴。"}, "sentence_index": 6, "correct_answer": "曲线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们选了一条最短的曲线去机场。", "explanation": "这里应该用〈路线〉。曲线是几何或图表中的线，选去机场的走法要用路线。"}, {"text": "他把绳子拉直了，它现在是一条曲线。", "explanation": "这里应该用〈直线〉。绳子拉直后是直线，不是弯的曲线，这里应说直线。"}, {"text": "我们绕了一段很长的曲线才到家。", "explanation": "这里应该用〈弯路〉。曲线指线，不指走过的路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕上那条很陡曲线在下降。", "corrected_sentence": "屏幕上那条很陡的曲线在下降。", "error_description": "结构助词漏用：“很陡”修饰“曲线”时要加“的”，应为“那条很陡的曲线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张图得曲线很清楚。", "corrected_sentence": "那张图的曲线很清楚。", "error_description": "结构助词误用：修饰“曲线”要用“的”，不能用“得”。应为“那张图的曲线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
