INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96391, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不一定，说不定不是这样。", "primary_collocate": null, "pronunciation": "wèi bì", "ipa": "weɪ˥˩ pi˥˩", "syllable_count": 2, "sentences": [{"text": "贵的东西未必好用。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话未必是真的。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天未必没有人出门。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习好的人未必会做饭。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法未必有用。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看到的未必是全部。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天未必会下雨，不用带伞。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着，心里未必高兴。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早到未必是好事。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说好，我未必同意。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不一定，事情不见得是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未必", "is_correct": true, "explanation": "正确。未必表示不一定，与“贵的东西”这一泛泛的判断相合，句意是贵的东西不一定好用。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：「正在」表示动作进行中，不能与「好用」这类状态形容词搭配，“贵的东西”也不能处于进行状态。"}, {"text": "差点", "is_correct": false, "explanation": "语义：「差点」表示险些发生某事，与“贵的东西……好用”这一概括说法不合，句子说不通。"}, {"text": "只好", "is_correct": false, "explanation": "配价：「只好」要求有人主动做出某种选择，主语“贵的东西”无法“只好”，填入后不成立。"}], "explanations": {"未必": "正确。未必表示不一定，与“贵的东西”这一泛泛的判断相合，句意是贵的东西不一定好用。", "正在": "体貌：「正在」表示动作进行中，不能与「好用」这类状态形容词搭配，“贵的东西”也不能处于进行状态。", "差点": "语义：「差点」表示险些发生某事，与“贵的东西……好用”这一概括说法不合，句子说不通。", "只好": "配价：「只好」要求有人主动做出某种选择，主语“贵的东西”无法“只好”，填入后不成立。"}, "sentence_index": 0, "correct_answer": "未必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个结果一定未必正确，大家都要重新检查。", "explanation": "这里应该用〈必定〉。未必表示不一定，与“一定”自相矛盾，句子说不通；表示结果确定无疑，应当用必定。"}, {"text": "这个计划肯定未必能成功，我们别再讨论了。", "explanation": "这里应该用〈必然〉。未必表示不一定，与“肯定”矛盾；要说计划一定能成功，应当用必然，不能用未必。"}, {"text": "我们已经商量好了，他绝对未必参加。", "explanation": "这里应该用〈一定〉。未必表示不一定，与“绝对”矛盾；要说他肯定会参加，应当用一定，不能用未必。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未必", "is_correct": true, "explanation": "正确。未必表示不一定，符合“明天……不用带伞”的推测语境。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」表示马上发生，与“明天”这一将来的时间不合，句子说不通。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示经常、一贯，与“明天”这种一次性的时间不合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」表示一贯如此，不与“明天”这类将来时间词搭配。"}], "explanations": {"未必": "正确。未必表示不一定，符合“明天……不用带伞”的推测语境。", "立刻": "语义：「立刻」表示马上发生，与“明天”这一将来的时间不合，句子说不通。", "总是": "语义：「总是」表示经常、一贯，与“明天”这种一次性的时间不合。", "从来": "搭配：「从来」表示一贯如此，不与“明天”这类将来时间词搭配。"}, "sentence_index": 6, "correct_answer": "未必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天已经亲手交了作业，未必交了。", "explanation": "这里应该用〈确实〉。未必表示不一定，与“亲手交了”自相矛盾；陈述已经发生的事实，应当用确实。"}, {"text": "我非常确定他会来，未必会来。", "explanation": "这里应该用〈一定〉。未必表示不确定，与“非常确定”矛盾；表示确定时应当用一定。"}, {"text": "我一直亲眼看着他签字，他未必签了字。", "explanation": "这里应该用〈的确〉。未必表示不确定，与“亲眼看着”矛盾；陈述亲眼见到的事实，应当用的确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试他很未必能及格。", "corrected_sentence": "这次考试他未必能及格。", "error_description": "错误：「很未必」；正确：「未必」。「未必」本身已带有不确定的语气，前面不能再加程度副词「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她未必了同意这个计划。", "corrected_sentence": "她未必同意这个计划。", "error_description": "错误：「未必了同意」；正确：「未必同意」。「未必」是副词，本身已带有不确定的语气，后面不能直接加「了」等体标。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不一定；表示对某事的可能性持怀疑或否定态度。", "primary_collocate": null, "pronunciation": "wèi bì", "ipa": "weɪ˥˩ pi˥˩", "syllable_count": 2, "sentences": [{"text": "他未必能赶上最后一班车。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，他未必还在公司。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去求他，他未必会帮你。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有准备，我们未必能赢。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事老板未必知道。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她未必愿意搬到别的城市。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，他未必看得见路。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他未必想来，你别勉强他。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱这么高，客人未必会买。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不说，他未必明白你的意思。", "target_word": "未必", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对某事能否发生表示怀疑，认为可能性不大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未必", "is_correct": true, "explanation": "正确。未必表示对“赶上最后一班车”的可能性持怀疑，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：「只好」表示无可奈何只得如此，后面须接具体行为，不能与“能赶上”连用，句子不通。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：「正在」表示动作进行中，不能与“赶上最后一班车”这种尚未发生的结果搭配。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」强调马上发生，与“最后一班车”需要赶的时间不匹配，句子说不通。"}], "explanations": {"未必": "正确。未必表示对“赶上最后一班车”的可能性持怀疑，符合句意。", "只好": "搭配：「只好」表示无可奈何只得如此，后面须接具体行为，不能与“能赶上”连用，句子不通。", "正在": "体貌：「正在」表示动作进行中，不能与“赶上最后一班车”这种尚未发生的结果搭配。", "立刻": "语义：「立刻」强调马上发生，与“最后一班车”需要赶的时间不匹配，句子说不通。"}, "sentence_index": 0, "correct_answer": "未必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛他一定未必能赢，大家都这么认为。", "explanation": "这里应该用〈必定〉。未必表示怀疑或否定，与“一定”矛盾，句子说不通；表示确定能赢，应当用必定。"}, {"text": "这次肯定未必会下雨，你尽管出门。", "explanation": "这里应该用〈不会〉。未必只表示怀疑，与“肯定”矛盾；若要确定不下雨，应说“肯定不会下雨”。"}, {"text": "没有准备，我们绝对未必能赢。", "explanation": "这里应该用〈不可能〉。未必表示不确定，与“绝对”矛盾；若要强调肯定赢不了，应说“绝对不可能赢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未必", "is_correct": true, "explanation": "正确。未必表示对“看得见路”的可能性持怀疑，与“天这么黑”的语境相合。"}, {"text": "肯定", "is_correct": false, "explanation": "语义：「肯定」表示确定无疑，与「天这么黑」的语境相抵触，句子等于断定他一定看得见路，句意不合。"}, {"text": "一定", "is_correct": false, "explanation": "语义：「一定」表示必然如此，与「天这么黑」的语境相抵触，句子断定他必然看得见路，与情境不符。"}, {"text": "差点", "is_correct": false, "explanation": "语义：「差点」表示险些发生某事，与「看得见路」这一状态搭配不通，句子说不通。"}], "explanations": {"未必": "正确。未必表示对“看得见路”的可能性持怀疑，与“天这么黑”的语境相合。", "肯定": "语义：「肯定」表示确定无疑，与「天这么黑」的语境相抵触，句子等于断定他一定看得见路，句意不合。", "一定": "语义：「一定」表示必然如此，与「天这么黑」的语境相抵触，句子断定他必然看得见路，与情境不符。", "差点": "语义：「差点」表示险些发生某事，与「看得见路」这一状态搭配不通，句子说不通。"}, "sentence_index": 6, "correct_answer": "未必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明明已经答应了，却未必答应。", "explanation": "这里应该用〈确实〉。未必表示不确定，与“明明已经答应”矛盾；陈述已经发生的事，应当用确实。"}, {"text": "明天的天气预报百分之百准确，未必下雨。", "explanation": "这里应该用〈一定〉。未必表示不确定，与“百分之百准确”矛盾；要说明天必然下雨，应当用一定。"}, {"text": "我确定赶得上，恐怕未必。", "explanation": "未必表示不确定，与“确定赶得上”矛盾；这里要表达确定，应直接用肯定说法，不能说“恐怕未必”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他未必了会来参加会议。", "corrected_sentence": "他未必会来参加会议。", "error_description": "错误：「未必了会」；正确：「未必会」。「了」不能插在副词「未必」与能愿动词「会」之间，应直接说「未必会来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很未必能完成这项任务。", "corrected_sentence": "他未必能完成这项任务。", "error_description": "错误：「很未必」；正确：「未必」。「未必」本身已带有不确定的语气，不能再受程度副词「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
