INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "捕捞和养殖水生动植物的产业。", "primary_collocate": null, "pronunciation": "yú yè", "ipa": "y˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的渔业发展得很快。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔业是海边城市的重要产业。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在渔业不但捕鱼，还养虾和海带。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想保护海洋，也想发展渔业。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的渔业每年卖很多海产品到国外。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风多的年份，渔业的收入会少很多。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多渔业公司在海上养鱼，也出口海产品。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染让渔业的损失越来越大。", "target_word": "渔业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护鱼，政府限制渔业的捕鱼量。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，海水变暖会影响全世界的渔业。", "target_word": "渔业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "漁業", "label": "繁体"}, {"form": "渔业资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "渔业：捕捞和养殖水生动植物的产业，常与经济、政策、海洋有关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渔业", "is_correct": true, "explanation": "正确。渔业是捕捞和养殖水生动植物的产业，与“这个国家的……发展得很快”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不会“发展”，与“这个国家的……发展得很快”的产业语境不符。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子是矿物颗粒，不是可以“发展”的事物，与“这个国家的……发展得很快”的语境不符，句子说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，与“这个国家的”这一社会语境不符，句子说不通。"}], "explanations": {"渔业": "正确。渔业是捕捞和养殖水生动植物的产业，与“这个国家的……发展得很快”相合。", "天气": "语义：天气是自然现象，不会“发展”，与“这个国家的……发展得很快”的产业语境不符。", "沙子": "语义：沙子是矿物颗粒，不是可以“发展”的事物，与“这个国家的……发展得很快”的语境不符，句子说不通。", "月亮": "语义：月亮是天体，与“这个国家的”这一社会语境不符，句子说不通。"}, "sentence_index": 0, "correct_answer": "渔业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的一座渔业很发达。", "explanation": "这里应该用〈个〉或〈种〉。「座」用于山、楼等大型固定物，渔业是行业，量词用错了。"}, {"text": "今年的渔业很多，价格却很低。", "explanation": "这里应该用〈渔获〉。渔获指捕到的鱼，渔业指行业；此处说的是捕到的鱼，不是行业。"}, {"text": "渔业破了一个大洞。", "explanation": "这里应该用〈渔网〉。渔网是工具，会破损；渔业是行业，不能破损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渔业", "is_correct": true, "explanation": "正确。渔业作定语修饰“公司”，指从事捕鱼养鱼的企业，与“在海上养鱼”相合。"}, {"text": "林业", "is_correct": false, "explanation": "语义：林业以森林为对象，与“在海上养鱼”的经营内容不符。"}, {"text": "电子", "is_correct": false, "explanation": "语义：电子公司从事电子产品业务，与“在海上养鱼”的经营内容不符。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：石油不能用来养鱼，「石油公司在海上养鱼」与常识和搭配都不通。"}], "explanations": {"渔业": "正确。渔业作定语修饰“公司”，指从事捕鱼养鱼的企业，与“在海上养鱼”相合。", "林业": "语义：林业以森林为对象，与“在海上养鱼”的经营内容不符。", "电子": "语义：电子公司从事电子产品业务，与“在海上养鱼”的经营内容不符。", "石油": "搭配：石油不能用来养鱼，「石油公司在海上养鱼」与常识和搭配都不通。"}, "sentence_index": 6, "correct_answer": "渔业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔业停靠在港口，装满了鱼。", "explanation": "这里应该用〈渔船〉。渔业是行业，不能停靠、装鱼；能停靠、装鱼的是渔船。"}, {"text": "我们在渔业的甲板上晒太阳。", "explanation": "这里应该用〈渔船〉。甲板属于船，渔业是行业，没有甲板，不能说“渔业的甲板”。"}, {"text": "渔业在海上撒网，很快就收工了。", "explanation": "这里应该用〈渔民〉。撒网的是人，渔业是行业，不能做动作；此句说的是渔民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府把渔业管理的很好。", "corrected_sentence": "政府把渔业管理得很好。", "error_description": "错误：「管理的很好」；正确：「管理得很好」。「得」用于动词后引出状态补语，「的」是结构助词，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村的渔业的发展了很多年。", "corrected_sentence": "这个村的渔业发展了很多年。", "error_description": "错误：「渔业的发展了」；正确：「渔业发展了」。「渔业的发展」是名词性短语，不能直接带动态助词「了」作谓语，应去掉「的」，让「渔业」作主语、「发展」作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都喜欢、都在做的新样子。", "primary_collocate": null, "pronunciation": "cháo liú", "ipa": "tʂʰɑʊ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "年轻人都喜欢追潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿得很有个性，总是走在潮流的前面。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鞋子现在是最新的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太懂潮流，只喜欢舒服的衣服。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说今年的潮流是白色的运动鞋。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每个月都买新衣服，想跟上潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人跟着网上的潮流剪头发。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个潮流来得快，去得也快。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明星戴过的帽子，很快就成了潮流。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他的衣服不是潮流，但是很好穿。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股潮流", "label": "量词"}], "register": "中性", "sense_fingerprint": "潮流：衣服、发型等方面大家都喜欢的新样子，即时尚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是可以追赶的对象。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指大家都喜欢、都在做的新样子，“追潮流”是常见搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能用来追赶。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“追”接的是人、趋势等，不说“追早饭”。"}], "explanations": {"电话": "语义：电话是通讯工具，不是可以追赶的对象。", "潮流": "潮流指大家都喜欢、都在做的新样子，“追潮流”是常见搭配。", "冰箱": "语义：冰箱是家用电器，不能用来追赶。", "早饭": "搭配：“追”接的是人、趋势等，不说“追早饭”。"}, "sentence_index": 0, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的潮流是打篮球，每个周末都去球场。", "explanation": "这里应该用〈爱好〉。潮流指社会上大家都在追随的新样子，个人喜欢做的事要说爱好，不说潮流。"}, {"text": "比赛进入了最后的潮流，观众大声欢呼。", "explanation": "这里应该用〈高潮〉。高潮指比赛、演出发展到最激烈、最精彩的阶段，潮流指大家追随的新样子，不指比赛的阶段。"}, {"text": "他的潮流很暴躁，动不动就发火。", "explanation": "这里应该用〈脾气〉。脾气指一个人的性情和发作时的样子，潮流指大家追随的新样子，不用来形容人的性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说人的高矮，不能作为跟着剪发的依据。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指大家都在做的新样子，“跟着……的潮流”是常见说法，修饰“剪头发”的样式。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不指式样，不能跟着它剪头发。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“故事”不是可以照着剪的样子，不能说“跟着网上的故事剪头发”。"}], "explanations": {"身高": "体貌：“身高”说人的高矮，不能作为跟着剪发的依据。", "潮流": "潮流指大家都在做的新样子，“跟着……的潮流”是常见说法，修饰“剪头发”的样式。", "时间": "语义：时间不指式样，不能跟着它剪头发。", "故事": "搭配：“故事”不是可以照着剪的样子，不能说“跟着网上的故事剪头发”。"}, "sentence_index": 6, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的潮流是教小学生画画，每天都很忙。", "explanation": "这里应该用〈工作〉。潮流指社会上大家都在追随的新样子，个人的职业要说工作，不说潮流。"}, {"text": "他的潮流很踏实，做事认真负责。", "explanation": "这里应该用〈作风〉。作风指一个人做事的态度和风格，潮流指大家追随的新样子，不用来形容人的做事态度。"}, {"text": "这所学校的潮流很贵，很多家庭负担不起。", "explanation": "这里应该用〈学费〉。学费指上学要交的钱，潮流指大家追随的新样子，不指学校收取的费用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种发型曾经是潮流过，现在已经过时了。", "corrected_sentence": "这种发型曾经是潮流，现在已经过时了。", "error_description": "错误在时态助词“过”。“潮流”是名词，后面不能直接加“过”，“曾经”已经表示过去，应说“曾经是潮流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那件外套是今年最火的一件潮流。", "corrected_sentence": "那件外套是今年最火的一股潮流。", "error_description": "量词错误。“潮流”作为抽象的趋势，应搭配量词“股”，说“一股潮流”；“件”用于衣物等具体物品，不能用来数“潮流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆流", "is_correct": true, "explanation": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。"}, {"text": "桌子", "is_correct": false, "explanation": "与“潮流”无反义关系，桌子是具体的家具，不表示社会趋势。"}, {"text": "石头", "is_correct": false, "explanation": "与“潮流”无反义关系，石头是具体的物体，不表示社会趋势。"}, {"text": "窗户", "is_correct": false, "explanation": "与“潮流”无反义关系，窗户是房屋的构件，不表示社会趋势。"}], "correct_answer": "逆流", "explanations": {"逆流": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。", "桌子": "与“潮流”无反义关系，桌子是具体的家具，不表示社会趋势。", "石头": "与“潮流”无反义关系，石头是具体的物体，不表示社会趋势。", "窗户": "与“潮流”无反义关系，窗户是房屋的构件，不表示社会趋势。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆流", "is_correct": true, "explanation": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。"}, {"text": "钥匙", "is_correct": false, "explanation": "与“潮流”无反义关系，钥匙是开锁的工具，不表示社会趋势。"}, {"text": "书包", "is_correct": false, "explanation": "与“潮流”无反义关系，书包是装东西的用具，不表示社会趋势。"}, {"text": "花瓶", "is_correct": false, "explanation": "与“潮流”无反义关系，花瓶是盛花的器物，不表示社会趋势。"}], "correct_answer": "逆流", "explanations": {"逆流": "逆流指逆着水流或潮流的方向，比喻违背社会发展的大势，与“潮流”构成反义。", "钥匙": "与“潮流”无反义关系，钥匙是开锁的工具，不表示社会趋势。", "书包": "与“潮流”无反义关系，书包是装东西的用具，不表示社会趋势。", "花瓶": "与“潮流”无反义关系，花瓶是盛花的器物，不表示社会趋势。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻社会变动或发展的趋势；也指风行一时的事物。", "primary_collocate": null, "pronunciation": "cháo liú", "ipa": "tʂʰɑʊ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们要跟上时代的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界经济的潮流是越来越开放。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人想改变社会，也想走在时代潮流的前面。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司看清了市场的潮流，所以赚了很多钱。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保已经成了世界的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也挡不住时代的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读书的人越来越多，这是社会发展的潮流。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很早就看到了互联网的潮流。", "target_word": "潮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史的潮流向前走，没有人能停下来。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学生要顺着时代的潮流，不断学习。", "target_word": "潮流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股潮流", "label": "量词"}], "register": "中性", "sense_fingerprint": "潮流：社会、时代、经济等发展变化的大趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高峰", "is_correct": false, "explanation": "搭配：“跟上”接的是步伐、潮流，攀上的才是高峰，不说“跟上时代的高峰”。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指社会、时代发展的大趋势，与“跟上”搭配，表示要紧跟时代的变化。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以跟上的发展方向。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是具体的机器，不是可以跟随的社会趋势。"}], "explanations": {"高峰": "搭配：“跟上”接的是步伐、潮流，攀上的才是高峰，不说“跟上时代的高峰”。", "潮流": "潮流指社会、时代发展的大趋势，与“跟上”搭配，表示要紧跟时代的变化。", "天气": "语义：天气是自然现象，不是可以跟上的发展方向。", "电脑": "语义：电脑是具体的机器，不是可以跟随的社会趋势。"}, "sentence_index": 0, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年夏天气温一直在上升，形成了明显的潮流。", "explanation": "这里应该用〈趋势〉。潮流指社会、时代或流行中的大方向，不用来说气温等自然数据的变化。"}, {"text": "涨潮的时候，潮流很快就淹没了礁石。", "explanation": "这里应该用〈潮水〉。淹没礁石的是潮水；潮流只指海水流动的方向和速度，不会淹没东西。"}, {"text": "演唱会进入了最精彩的潮流，观众全部站了起来。", "explanation": "这里应该用〈高潮〉。高潮指演出、比赛发展到最激烈、最精彩的阶段；潮流指社会上的大趋势，不指演出的某个阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”说人或物的体形，不用来形容社会的发展。"}, {"text": "潮流", "is_correct": true, "explanation": "潮流指社会发展的大趋势，“社会发展的潮流”是常见说法，正好说明读书的人越来越多这一趋势。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指给商品套上的外壳，与社会发展的趋势无关。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”只说食物或人的喜好，不能说“社会发展的口味”。"}], "explanations": {"身材": "体貌：“身材”说人或物的体形，不用来形容社会的发展。", "潮流": "潮流指社会发展的大趋势，“社会发展的潮流”是常见说法，正好说明读书的人越来越多这一趋势。", "包装": "语义：“包装”指给商品套上的外壳，与社会发展的趋势无关。", "口味": "搭配：“口味”只说食物或人的喜好，不能说“社会发展的口味”。"}, "sentence_index": 6, "correct_answer": "潮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警方已经掌握了嫌疑人的潮流，随时可以行动。", "explanation": "这里应该用〈动向〉。潮流指时代或社会的大趋势，不指某个人的行踪或举动。"}, {"text": "他每天早上都有跑步的潮流。", "explanation": "这里应该用〈习惯〉。潮流指社会上大家都在追随的趋势，个人的日常习惯要说习惯，不说潮流。"}, {"text": "他对数学的潮流很浓，常常自己做题。", "explanation": "这里应该用〈兴趣〉。兴趣指个人对某件事的喜爱，潮流指社会上的大趋势，不用来说个人的喜好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快就跟上着潮流。", "corrected_sentence": "他很快就跟上了潮流。", "error_description": "错误：「跟上着」；正确：「跟上了」。「跟上」表示已经完成的动作，应用完成态助词「了」，不能用表示持续的「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只潮流很快就传到了我们学校。", "corrected_sentence": "这股潮流很快就传到了我们学校。", "error_description": "量词错误。“潮流”应用量词“股”，不能用“只”，“只”用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "博学", "is_correct": true, "explanation": "博学：学识广博，与“无知”构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "与“无知”无反义关系，干净形容卫生状况，与知识无关。"}, {"text": "高兴", "is_correct": false, "explanation": "与“无知”无反义关系，高兴形容心情，与知识无关。"}, {"text": "沉重", "is_correct": false, "explanation": "与“无知”无反义关系，沉重形容重量或心情，与知识无关。"}], "correct_answer": "博学", "explanations": {"博学": "博学：学识广博，与“无知”构成反义。", "干净": "与“无知”无反义关系，干净形容卫生状况，与知识无关。", "高兴": "与“无知”无反义关系，高兴形容心情，与知识无关。", "沉重": "与“无知”无反义关系，沉重形容重量或心情，与知识无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
