INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "什么都不知道，也不懂。", "primary_collocate": null, "pronunciation": "wú zhī", "ipa": "u˧˥ tʂɨ˥˥", "syllable_count": 2, "sentences": [{"text": "在音乐方面，我几乎是无知的。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对法律一点儿都不懂，非常无知。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子对世界很无知，什么都想问。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚到这个国家时，我对一切都很无知。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不看新闻，对身边的事很无知。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想一直这么无知下去，所以要多读书。", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她承认自己对医学无知，就请医生来帮忙。", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时我年纪小，对钱的事很无知。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不懂也不问，只会让你一直无知。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人笑着说：“我对手机无知，什么都不会用。”", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無知", "label": "繁体"}, {"form": "愚昧无知", "label": "复合"}], "register": "中性", "sense_fingerprint": "无知：对某方面的事什么都不知道、不懂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无知", "is_correct": true, "explanation": "无知：什么都不知道，也不懂。"}, {"text": "五只", "is_correct": false, "explanation": "wǔ zhī（第三声）与 wú zhī（第二声）第一个音节声调不同，意思是五个（量词“只”）。"}, {"text": "五指", "is_correct": false, "explanation": "wǔ zhǐ（第三声）与 wú zhī 第一个音节声调不同，第二个音节也变调，意思是五根手指。"}, {"text": "无职", "is_correct": false, "explanation": "wú zhí（第二声）与 wú zhī（第一声）第二个音节声调不同，意思是没有职位。"}, {"text": "无志", "is_correct": false, "explanation": "wú zhì（第四声）与 wú zhī（第一声）第二个音节声调不同，意思是没有志向。"}], "explanations": {"无知": "无知：什么都不知道，也不懂。", "五只": "wǔ zhī（第三声）与 wú zhī（第二声）第一个音节声调不同，意思是五个（量词“只”）。", "五指": "wǔ zhǐ（第三声）与 wú zhī 第一个音节声调不同，第二个音节也变调，意思是五根手指。", "无职": "wú zhí（第二声）与 wú zhī（第一声）第二个音节声调不同，意思是没有职位。", "无志": "wú zhì（第四声）与 wú zhī（第一声）第二个音节声调不同，意思是没有志向。"}, "sentence_index": null, "correct_answer": "无知"}, "level_3": {"options": [{"text": "结实", "is_correct": false, "explanation": "体貌：“结实”形容身体强壮，不能用来说人对音乐的了解。"}, {"text": "无知", "is_correct": true, "explanation": "无知：什么都不知道、不懂，与“几乎是……的”相合，指音乐方面知识极少。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”形容声音、思路等明白，不用来说人对某方面知识的了解。"}, {"text": "流利", "is_correct": false, "explanation": "搭配：“流利”多修饰语言、演奏，不能说“我几乎是流利的”。"}], "explanations": {"结实": "体貌：“结实”形容身体强壮，不能用来说人对音乐的了解。", "无知": "无知：什么都不知道、不懂，与“几乎是……的”相合，指音乐方面知识极少。", "清晰": "语义：“清晰”形容声音、思路等明白，不用来说人对某方面知识的了解。", "流利": "搭配：“流利”多修饰语言、演奏，不能说“我几乎是流利的”。"}, "sentence_index": 0, "correct_answer": "无知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市对我来说还很无知。", "explanation": "这里应该用〈陌生〉。无知指人对知识、道理不懂，不用来说城市或地方对人的生疏。"}, {"text": "这块布很无知，颜色一洗就掉。", "explanation": "这里应该用〈不耐洗〉。不耐洗指经不起洗涤，无知指人缺乏知识或不明事理，不用来形容布料。"}, {"text": "他喝醉以后，眼神很无知，连家门都找不到。", "explanation": "这里应该用〈迷茫〉。迷茫指神情发愣、不知方向，无知指缺乏知识，不用来形容醉后的眼神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容身体单薄，不能用来说人对医学的了解。"}, {"text": "无知", "is_correct": true, "explanation": "无知：对某方面什么都不懂，与“对医学”搭配，说明需要请医生帮忙。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“清醒”形容头脑明白，不用来说人对医学的了解程度。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容谈吐风趣，不能与“对医学”搭配。"}], "explanations": {"瘦弱": "体貌：“瘦弱”形容身体单薄，不能用来说人对医学的了解。", "无知": "无知：对某方面什么都不懂，与“对医学”搭配，说明需要请医生帮忙。", "清醒": "语义：“清醒”形容头脑明白，不用来说人对医学的了解程度。", "幽默": "搭配：“幽默”形容谈吐风趣，不能与“对医学”搭配。"}, "sentence_index": 6, "correct_answer": "无知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到噩耗，他一时无知，说不出话来。", "explanation": "这里应该用〈茫然〉。茫然指一时不知所措，无知指缺乏知识，不用来形容受惊后的神态。"}, {"text": "这个孩子反应无知，学东西比别人慢。", "explanation": "这里应该用〈愚钝〉。愚钝指反应慢、脑子不灵，无知指缺乏知识，不用来形容反应的快慢。"}, {"text": "这道题把他弄得很无知，半天没有说话。", "explanation": "这里应该用〈迷惑〉。迷惑指不明白、拿不定主意，无知指缺乏知识，不用来形容一时的困惑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在历史方面很很无知，连基本的年代都说不清。", "corrected_sentence": "他在历史方面很无知，连基本的年代都说不清。", "error_description": "错误：「很很」重复使用程度副词；正确：只用一个「很」，说「很无知」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前把很多事都很无知，现在懂得多了。", "corrected_sentence": "他以前对很多事都很无知，现在懂得多了。", "error_description": "错误：「把」字句的谓语「很无知」是形容词，不能放在「把」字句中；应将「把」改为「对」，用「对」引出对象「很多事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
