INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96416, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "缺乏知识的；不明事理的。", "primary_collocate": null, "pronunciation": "wú zhī", "ipa": "u˧˥ tʂɨ˥˥", "syllable_count": 2, "sentences": [{"text": "随便丢垃圾是无知的行为。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他无知地以为钱可以买到一切。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种无知的想法会害了孩子。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为无知，他们相信了骗子的话。", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说女孩子不用读书，是很无知的看法。", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的无知让大家很生气。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她骂人又不讲理，真是无知。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要把自己的无知，当成别人的错。", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无知的人常常觉得自己什么都对。", "target_word": "无知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子乱吃药，是大人的无知造成的。", "target_word": "无知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無知", "label": "繁体"}, {"form": "愚昧无知", "label": "复合"}], "register": "中性", "sense_fingerprint": "无知：缺乏知识、不明事理，常用来评价想法或行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b18b47-23e4-4c5b-ae48-2c389760d19b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96416, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无知", "is_correct": true, "explanation": "无知：缺乏知识，不明事理。"}, {"text": "五只", "is_correct": false, "explanation": "wǔ zhī（第三声）与 wú zhī（第二声）第一个音节声调不同，意思是五个（量词“只”）。"}, {"text": "五指", "is_correct": false, "explanation": "wǔ zhǐ（第三声）与 wú zhī 第一个音节声调不同，第二个音节也变调，意思是五根手指。"}, {"text": "无职", "is_correct": false, "explanation": "wú zhí（第二声）与 wú zhī（第一声）第二个音节声调不同，意思是没有职位。"}, {"text": "无志", "is_correct": false, "explanation": "wú zhì（第四声）与 wú zhī（第一声）第二个音节声调不同，意思是没有志向。"}], "explanations": {"无知": "无知：缺乏知识，不明事理。", "五只": "wǔ zhī（第三声）与 wú zhī（第二声）第一个音节声调不同，意思是五个（量词“只”）。", "五指": "wǔ zhǐ（第三声）与 wú zhī 第一个音节声调不同，第二个音节也变调，意思是五根手指。", "无职": "wú zhí（第二声）与 wú zhī（第一声）第二个音节声调不同，意思是没有职位。", "无志": "wú zhì（第四声）与 wú zhī（第一声）第二个音节声调不同，意思是没有志向。"}, "sentence_index": null, "correct_answer": "无知"}, "level_3": {"options": [{"text": "文明", "is_correct": false, "explanation": "语义：“文明”与“随便丢垃圾”的意思相反，不能说“随便丢垃圾是文明的行为”。"}, {"text": "无知", "is_correct": true, "explanation": "无知：缺乏知识，不明事理，用来评价“随便丢垃圾”这种行为。"}, {"text": "优雅", "is_correct": false, "explanation": "搭配：“优雅”多修饰举止、姿态，与“随便丢垃圾”这类行为不搭配。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不用来评价行为。"}], "explanations": {"文明": "语义：“文明”与“随便丢垃圾”的意思相反，不能说“随便丢垃圾是文明的行为”。", "无知": "无知：缺乏知识，不明事理，用来评价“随便丢垃圾”这种行为。", "优雅": "搭配：“优雅”多修饰举止、姿态，与“随便丢垃圾”这类行为不搭配。", "高大": "体貌：“高大”形容人或物的体形，不用来评价行为。"}, "sentence_index": 0, "correct_answer": "无知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个玩具的设计太无知了，三岁孩子都看得出来。", "explanation": "这里应该用〈幼稚〉。无知指人缺乏知识或判断，不用来评价玩具的设计。"}, {"text": "这台机器的设计很无知，用了一天就坏了。", "explanation": "这里应该用〈愚蠢〉。无知指人不懂道理，不用来形容机器的设计。"}, {"text": "这座桥很无知，经得起大风大雨。", "explanation": "这里应该用〈坚固〉。坚固指东西结实、不易损坏，无知指缺乏知识或不明事理，不用来形容桥梁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容人品好，与“骂人又不讲理”的表现相反，不能说“真是善良”。"}, {"text": "无知", "is_correct": true, "explanation": "无知：缺乏知识，不明事理，用来评价“骂人又不讲理”的表现。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌或样子好看，不用来评价人的言行。"}, {"text": "富有", "is_correct": false, "explanation": "搭配：“富有”多接抽象名词，如“富有想象力”，不能单独作谓语评价人。"}], "explanations": {"善良": "语义：“善良”形容人品好，与“骂人又不讲理”的表现相反，不能说“真是善良”。", "无知": "无知：缺乏知识，不明事理，用来评价“骂人又不讲理”的表现。", "漂亮": "体貌：“漂亮”形容外貌或样子好看，不用来评价人的言行。", "富有": "搭配：“富有”多接抽象名词，如“富有想象力”，不能单独作谓语评价人。"}, "sentence_index": 6, "correct_answer": "无知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套系统的反应无知，常常卡住。", "explanation": "这里应该用〈愚钝〉。愚钝指反应慢、脑子不灵，无知指缺乏知识，不用来形容系统的反应。"}, {"text": "这个程序的运行很无知，经常卡住。", "explanation": "这里应该用〈迟钝〉。迟钝指反应或运行慢半拍，无知指缺乏知识，不用来形容程序的运行。"}, {"text": "他年纪大了，有时走路很无知，常常摔跤。", "explanation": "这里应该用〈不稳〉。不稳指走路摇晃、站不牢，无知指缺乏知识或不明事理，不用来形容走路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他无知的在河里倒了一桶油。", "corrected_sentence": "他无知地在河里倒了一桶油。", "error_description": "助词错误。修饰动词的状语应用“地”，应说“无知地在河里倒了一桶油”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一向无知得，什么都不肯学。", "corrected_sentence": "他一向无知得很，什么都不肯学。", "error_description": "程度补语错误。“无知得”后面要接补语，如“无知得很”，不能在“得”后空着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d9fc73d-0514-4ea4-a9e8-94ad3f37fb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96423, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
