INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96423, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西走过或碰过后留下的样子。", "primary_collocate": null, "pronunciation": "hén jì", "ipa": "xən˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "雪地上有一串小动物留下的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上还留着杯子的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有一道长长的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的水干了，只剩一点痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过以后，沙发上留下了痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户上有手指碰过的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车轮在泥地上压出了深深的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用布把地板上的痕迹擦掉了。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白衬衫上有一块黑色的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙子上有人走过的痕迹。", "target_word": "痕迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道痕迹", "label": "量词"}, {"form": "痕跡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "痕迹：物体经过或接触后留下的看得见的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96423, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "痕迹", "is_correct": true, "explanation": "正确：痕迹（hén jì）指东西走过或碰过后留下的样子。"}, {"text": "人迹", "is_correct": false, "explanation": "rén（第二声）与 hén（第二声）声母不同，意思是人走过留下的踪迹。"}, {"text": "寒季", "is_correct": false, "explanation": "hán（第二声）与 hén 韵母不同（an 与 en），意思是寒冷的季节。"}, {"text": "很急", "is_correct": false, "explanation": "hěn（第三声）与 hén 声调不同，jí（第二声）与 jì（第四声）声调不同，意思是非常着急。"}], "explanations": {"痕迹": "正确：痕迹（hén jì）指东西走过或碰过后留下的样子。", "人迹": "rén（第二声）与 hén（第二声）声母不同，意思是人走过留下的踪迹。", "寒季": "hán（第二声）与 hén 韵母不同（an 与 en），意思是寒冷的季节。", "很急": "hěn（第三声）与 hén 声调不同，jí（第二声）与 jì（第四声）声调不同，意思是非常着急。"}, "sentence_index": null, "correct_answer": "痕迹"}, "level_3": {"options": [{"text": "痕迹", "is_correct": true, "explanation": "正确：“留下”的对象是痕迹，指小动物走过后留在雪地上的样子。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是水凝结成的固体，不是小动物走过后留下的东西。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雪花是雪的结晶，不是小动物走过后留下的东西。"}, {"text": "爪子", "is_correct": false, "explanation": "语义：爪子是动物身体的一部分，不是它走过后留下的样子。"}], "explanations": {"痕迹": "正确：“留下”的对象是痕迹，指小动物走过后留在雪地上的样子。", "冰块": "语义：冰块是水凝结成的固体，不是小动物走过后留下的东西。", "雪花": "语义：雪花是雪的结晶，不是小动物走过后留下的东西。", "爪子": "语义：爪子是动物身体的一部分，不是它走过后留下的样子。"}, "sentence_index": 0, "correct_answer": "痕迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上有一只痕迹。", "explanation": "这里应该用〈道〉。痕迹用“道”“块”等量词，“只”一般用于动物。"}, {"text": "这次旅行给我的痕迹很好。", "explanation": "这里应该用〈印象〉。痕迹指东西碰过或走过后留下的样子，不指人对事物的感受。"}, {"text": "我在书页上做了一个痕迹，提醒自己复习。", "explanation": "这里应该用〈记号〉。痕迹是东西经过或接触后自然留下的样子，不是有意做出的标记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痕迹", "is_correct": true, "explanation": "正确：“压出”的结果是留下的印迹，“深深的”修饰痕迹。"}, {"text": "泥巴", "is_correct": false, "explanation": "语义：泥巴是泥土本身，不是车轮压过后留下的样子。"}, {"text": "声响", "is_correct": false, "explanation": "搭配：“深深的”不能修饰声响，“压出”后接的是印迹或凹陷，不说“压出深深的声响”。"}, {"text": "力量", "is_correct": false, "explanation": "搭配：“压出”可以接印迹，但不能说“压出深深的力量”。"}], "explanations": {"痕迹": "正确：“压出”的结果是留下的印迹，“深深的”修饰痕迹。", "泥巴": "语义：泥巴是泥土本身，不是车轮压过后留下的样子。", "声响": "搭配：“深深的”不能修饰声响，“压出”后接的是印迹或凹陷，不说“压出深深的声响”。", "力量": "搭配：“压出”可以接印迹，但不能说“压出深深的力量”。"}, "sentence_index": 6, "correct_answer": "痕迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只瓷碗上画着一圈漂亮的痕迹，很有中国风。", "explanation": "这里应该用〈花纹〉。痕迹是东西碰过或走过后留下的印迹，不是有意画出的装饰。"}, {"text": "桌上有一颗痕迹，妈妈说要擦干净。", "explanation": "这里应该用〈块〉。痕迹用“块”“道”等量词，“颗”用于小而圆的东西。"}, {"text": "黑板上写着一行痕迹，老师说要擦掉。", "explanation": "这里应该用〈字〉。痕迹是无意留下的印迹，不能用来表示有意写下的字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户上有一只细细的痕迹。", "corrected_sentence": "窗户上有一道细细的痕迹。", "error_description": "“痕迹”应搭配量词“道”，写成“只”是错误的。“只”一般用于动物或成对的东西，不能计量这种划过或压过后留下的印迹。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车轮在雪地上压出了一道深深地痕迹。", "corrected_sentence": "车轮在雪地上压出了一道深深的痕迹。", "error_description": "“深深”修饰名词“痕迹”，应用“的”；“地”用于修饰动词，不能直接修饰名词，写成“深深地痕迹”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
