INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多聪明人一起查资料、做实验的地方。", "primary_collocate": null, "pronunciation": "yán jiū yuàn", "ipa": "jɛn˧˥ tɕjoʊ˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "研究院里有很多实验室。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在研究院里做实验。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究院的图书馆里有很多资料。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群聪明人每天待在研究院里。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去研究院找朋友，他正在查资料。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究院里的人常常工作到很晚。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究院的楼很新，里面有很多机器。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他还在研究院里忙着做实验。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究院很大，我走了很久。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们参观了研究院。", "target_word": "研究院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "所", "label": "量词"}], "register": "中性", "sense_fingerprint": "研究院：人们聚在一起查资料、做实验的工作场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39a6f9bc-591a-4f48-89d4-a7b21a9a7282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究院", "is_correct": true, "explanation": "研究院是聚集人员做研究的场所，里面有实验室，与句意相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园里不会有很多实验室，与句意不符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市里不会有很多实验室，与句意不符。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站里不会有很多实验室，与句意不符。"}], "explanations": {"研究院": "研究院是聚集人员做研究的场所，里面有实验室，与句意相符。", "花园": "语义：花园里不会有很多实验室，与句意不符。", "超市": "语义：超市里不会有很多实验室，与句意不符。", "车站": "语义：车站里不会有很多实验室，与句意不符。"}, "sentence_index": 0, "correct_answer": "研究院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去研究院看病。", "explanation": "这里应该用〈医院〉。研究院是做研究的地方，看病要去医院。"}, {"text": "我每天去研究院取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，研究院不是金融机构。"}, {"text": "我去研究院买菜。", "explanation": "这里应该用〈超市〉。买菜要去超市，研究院不是卖东西的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究院", "is_correct": true, "explanation": "研究院是做研究的机构，楼很新、里面有机器，符合句意。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林里没有“楼”，句子无法成立。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原上没有楼房，与句意不符。"}, {"text": "沙滩", "is_correct": false, "explanation": "语义：沙滩上没有楼房，与句意不符。"}], "explanations": {"研究院": "研究院是做研究的机构，楼很新、里面有机器，符合句意。", "森林": "语义：森林里没有“楼”，句子无法成立。", "草原": "语义：草原上没有楼房，与句意不符。", "沙滩": "语义：沙滩上没有楼房，与句意不符。"}, "sentence_index": 6, "correct_answer": "研究院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口开了一只研究院。", "explanation": "这里应该用〈所〉。研究院是机构，量词用“所”；“只”多用于动物。"}, {"text": "周末我们去参观了一条研究院。", "explanation": "这里应该用〈所〉。“条”用于细长的东西，研究院不能这样计量。"}, {"text": "这座城市里有一朵研究院。", "explanation": "这里应该用〈所〉。“朵”用于花朵等，不能用来计量研究院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一群聪明人研究院里查资料。", "corrected_sentence": "一群聪明人在研究院里查资料。", "error_description": "“研究院里”前面漏了介词“在”。正确说法是“在研究院里查资料”，地点要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条研究院的楼很高。", "corrected_sentence": "这所研究院的楼很高。", "error_description": "量词错误：“研究院”应用“所”计量，“条”用于细长的东西，不能用来数研究院。正确说法是“这所研究院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67ba3851-9da9-4dfd-94a0-d5181ff7b627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
