INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机或船只定期航行的路线。", "primary_collocate": null, "pronunciation": "háng xiàn", "ipa": "xɑŋ˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司新开了一条北京到巴黎的航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为台风，这条航线今天停飞了。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条海上航线连接两个大港口。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都乘这条航线的飞机去上海出差。", "target_word": "航线", "complexity_tier": "T3", "furigana": "tā měi gè yuè dōu chéng zhè tiáo háng xiàn de fēi jī qù Shàng hǎi chū chāi", "sentence_source": "generated"}, {"text": "公司打算增加几条国际航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这条航线的乘客比较少。", "target_word": "航线", "complexity_tier": "T3", "furigana": "dōng tiān zhè tiáo háng xiàn de chéng kè bǐ jiào shǎo", "sentence_source": "generated"}, {"text": "新航线开通后，两地的飞行时间缩短了一半。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司有二十多条国内航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雪，飞机改变了原来的航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，商船沿着这条航线运送茶叶。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "国际航线", "label": "复合"}], "register": "中性", "sense_fingerprint": "飞机或船只定期航行的路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14e608b0-7393-4f4f-8031-081eab276426') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "航线", "is_correct": true, "explanation": "正确：航线（háng xiàn）指飞机或船定期航行的路线。"}, {"text": "横线", "is_correct": false, "explanation": "横线（héng xiàn）与航线只差第一个字的韵母（eng 与 ang），声调相同，意思是横向的线。"}, {"text": "防线", "is_correct": false, "explanation": "防线（fáng xiàn）与航线只差第一个字的声母（f 与 h），声调相同，意思是防御的界线。"}, {"text": "航向", "is_correct": false, "explanation": "航向（háng xiàng）与航线只差第二个字的韵母（xiàng 与 xiàn），意思是船或飞机的行进方向，不是固定路线。"}], "explanations": {"航线": "正确：航线（háng xiàn）指飞机或船定期航行的路线。", "横线": "横线（héng xiàn）与航线只差第一个字的韵母（eng 与 ang），声调相同，意思是横向的线。", "防线": "防线（fáng xiàn）与航线只差第一个字的声母（f 与 h），声调相同，意思是防御的界线。", "航向": "航向（háng xiàng）与航线只差第二个字的韵母（xiàng 与 xiàn），意思是船或飞机的行进方向，不是固定路线。"}, "sentence_index": null, "correct_answer": "航线"}, "level_3": {"options": [{"text": "航线", "is_correct": true, "explanation": "正确：新开的是一条北京到巴黎的航线，指飞机定期往返的路线。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然水道，不能说“新开”，也不是北京到巴黎的运输路线。"}, {"text": "公交线", "is_correct": false, "explanation": "搭配：“公交线”只指城市内部的公共汽车路线，不能说“北京到巴黎的公交线”。"}, {"text": "街", "is_correct": false, "explanation": "语义：街是城市里的道路，不能连接两个国家的城市。"}], "explanations": {"航线": "正确：新开的是一条北京到巴黎的航线，指飞机定期往返的路线。", "河": "语义：河是自然水道，不能说“新开”，也不是北京到巴黎的运输路线。", "公交线": "搭配：“公交线”只指城市内部的公共汽车路线，不能说“北京到巴黎的公交线”。", "街": "语义：街是城市里的道路，不能连接两个国家的城市。"}, "sentence_index": 0, "correct_answer": "航线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天沿着这条航线走路去上班。", "explanation": "这里应当用〈路线〉。航线指飞机或船定期航行的路线，走路上班的路不叫航线。"}, {"text": "这次航线晚点了两个小时。", "explanation": "这里应当用〈航班〉。晚点的是某个班次的飞机，航线只是路线本身，不会晚点。"}, {"text": "这条航线经过三个公交车站。", "explanation": "这里应当用〈线路〉。航线在空中或水上，不经过公交车站；公交车站属于陆上线路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航线", "is_correct": true, "explanation": "正确：航线开通后，两地的飞行时间才会缩短。"}, {"text": "地铁线", "is_correct": false, "explanation": "语义：地铁线在城市内运行，不能缩短两地之间的飞行时间。"}, {"text": "餐厅", "is_correct": false, "explanation": "搭配：“开通”用于线路或服务，不说“开通餐厅”。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话开通与两地的飞行时间无关，句意不通。"}], "explanations": {"航线": "正确：航线开通后，两地的飞行时间才会缩短。", "地铁线": "语义：地铁线在城市内运行，不能缩短两地之间的飞行时间。", "餐厅": "搭配：“开通”用于线路或服务，不说“开通餐厅”。", "电话": "语义：电话开通与两地的飞行时间无关，句意不通。"}, "sentence_index": 6, "correct_answer": "航线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "航线正在滑行，请系好安全带。", "explanation": "这里应当用〈飞机〉。滑行是飞机在跑道上移动，航线是路线，不能滑行。"}, {"text": "这条航线从早到晚都有列车经过。", "explanation": "这里应当用〈铁路〉。列车经过的是陆上铁路，航线在空中或水上，不能有列车经过。"}, {"text": "航线很好听，大家都喜欢唱。", "explanation": "这里应当用〈歌曲〉。好听、能唱的是歌曲，航线是路线，不能唱，也不能说好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座航线下个月正式开通。", "corrected_sentence": "这条航线下个月正式开通。", "error_description": "错误形式“这座航线”，正确形式“这条航线”。“座”用于山、桥、楼房等大型固定物，航线是线状的路线，量词应当用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条航线终于通开了。", "corrected_sentence": "这条航线终于开通了。", "error_description": "错误形式“通开了”，正确形式“开通了”。“开通”中“通”是补语，两者顺序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
