INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛所能看到的空间范围；比喻见识的广度。", "primary_collocate": null, "pronunciation": "shì yě", "ipa": "ʂʅ˥˩ jɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "多读书可以开阔孩子的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国留学让他的视野变得更宽。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的视野很宽，什么新闻都知道。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行能让我们拓宽视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作以后，我才发现自己的视野太小了。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常带学生参观，扩大他们的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过很多国家，视野很开阔。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书为我打开了新的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和不同领域的人交流，能让人的视野更开阔。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看世界的视野不同，想法也会不同。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比喻见识的广度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14e608b0-7393-4f4f-8031-081eab276426') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：视野（shì yě）此处指见识的广度。"}, {"text": "事业", "is_correct": false, "explanation": "事业（shì yè）与视野只差第二个字的声调（yè 与 yě），意思是长期从事的工作或追求。"}, {"text": "失业", "is_correct": false, "explanation": "失业（shī yè）与视野两个字的声调都不同（shī 与 shì，yè 与 yě），意思是没有工作。"}, {"text": "实业", "is_correct": false, "explanation": "实业（shí yè）与视野两个字的声调都不同（shí 与 shì，yè 与 yě），意思是实际的经济事业。"}], "explanations": {"视野": "正确：视野（shì yě）此处指见识的广度。", "事业": "事业（shì yè）与视野只差第二个字的声调（yè 与 yě），意思是长期从事的工作或追求。", "失业": "失业（shī yè）与视野两个字的声调都不同（shī 与 shì，yè 与 yě），意思是没有工作。", "实业": "实业（shí yè）与视野两个字的声调都不同（shí 与 shì，yè 与 yě），意思是实际的经济事业。"}, "sentence_index": null, "correct_answer": "视野"}, "level_3": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：开阔孩子的视野指扩大见识的广度，符合读书的作用。"}, {"text": "房间", "is_correct": false, "explanation": "语义：读书开阔的是见识，不是房间的大小。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”用“保护”“提高”，不说“开阔”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能说“开阔”，读书也改变不了身高。"}], "explanations": {"视野": "正确：开阔孩子的视野指扩大见识的广度，符合读书的作用。", "房间": "语义：读书开阔的是见识，不是房间的大小。", "视力": "搭配：“视力”用“保护”“提高”，不说“开阔”。", "身高": "搭配：“身高”不能说“开阔”，读书也改变不了身高。"}, "sentence_index": 0, "correct_answer": "视野"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的视野很认真。", "explanation": "这里应当用〈态度〉。“认真”形容人的态度，视野指见识的广度，不能形容认真。"}, {"text": "他的视野很明确。", "explanation": "这里应当用〈目标〉。“明确”用于目标、要求，视野不能说明确。"}, {"text": "他的视野很暴躁。", "explanation": "这里应当用〈脾气〉。“暴躁”形容性情，视野不能用来形容性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：去过很多国家，视野开阔，指见识广。"}, {"text": "房间", "is_correct": false, "explanation": "语义：去过很多国家与房间大小无关，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“开阔”不用来形容脚步。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：“嗓门”用“大”“响亮”，不说“开阔”。"}], "explanations": {"视野": "正确：去过很多国家，视野开阔，指见识广。", "房间": "语义：去过很多国家与房间大小无关，句意不通。", "脚步": "搭配：“开阔”不用来形容脚步。", "嗓门": "搭配：“嗓门”用“大”“响亮”，不说“开阔”。"}, "sentence_index": 6, "correct_answer": "视野"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把视野存进了银行。", "explanation": "这里应当用〈钱〉。存进银行的是钱，视野是抽象的见识，不能存进银行。"}, {"text": "视野开了很多花。", "explanation": "这里应当用〈大树〉。开花的是植物，视野指见识的广度，不能开花。"}, {"text": "视野在树枝上叫个不停。", "explanation": "这里应当用〈鸟〉。在树枝上叫的是鸟，视野指见识的广度，不能叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次游学让她的视野宽变了。", "corrected_sentence": "这次游学让她的视野变宽了。", "error_description": "错误形式“宽变了”，正确形式“变宽了”。“变宽”是动补结构，补语“宽”必须紧跟“变”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行开阔了我们得视野。", "corrected_sentence": "旅行开阔了我们的视野。", "error_description": "错误形式“我们得视野”，正确形式“我们的视野”。“我们的”是定语，修饰“视野”，这里应用结构助词“的”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
