INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种语言或个人所使用的全部词的总和。", "primary_collocate": null, "pronunciation": "cí huì", "ipa": "tsʰɨ˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "汉语的词汇非常丰富。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人的词汇越多，表达越清楚。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多书，词汇变得更丰富了。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语词汇每年都会增加。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络让现代汉语的词汇发生了变化。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家用的词汇很特别。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大后，词汇会越来越多。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种语言的词汇都有自己的特点。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典包括了现代汉语的大部分词汇。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留学生的汉语词汇还不多。", "target_word": "词汇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "词汇量", "label": "复合"}, {"form": "词汇表", "label": "复合"}], "register": "中性", "sense_fingerprint": "一种语言或个人全部词的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14e608b0-7393-4f4f-8031-081eab276426') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能说“汉语的天气”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能用“丰富”来形容。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开门的工具，与语言没有关系。"}, {"text": "词汇", "is_correct": true, "explanation": "词汇指汉语中全部词的总和，与“汉语的”和“丰富”相符。"}], "explanations": {"天气": "语义：天气是自然现象，不能说“汉语的天气”。", "身高": "搭配：“身高”不能用“丰富”来形容。", "钥匙": "语义：钥匙是开门的工具，与语言没有关系。", "词汇": "词汇指汉语中全部词的总和，与“汉语的”和“丰富”相符。"}, "sentence_index": 0, "correct_answer": "词汇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他能说一口流利的词汇。", "explanation": "这里应该用〈方言〉。“一口……流利”修饰说话，词汇是词的集合，不能说“说一口流利的词汇”。"}, {"text": "这个人的词汇很苗条。", "explanation": "这里应该用〈身材〉。“苗条”形容人的体形，词汇是词的集合，不能说“很苗条”。"}, {"text": "他会写一手好词汇。", "explanation": "这里应该用〈字〉。“一手好”形容书写，词汇不能被写得“好”，要说〈字〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "搭配：年龄应说“越来越大”，不能说“越来越多”。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”用“好”或“差”来形容，不能说“越来越多”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，不会随成长变成“越来越多”。"}, {"text": "词汇", "is_correct": true, "explanation": "词汇指孩子掌握的词，随着长大会越来越多，与句意相符。"}], "explanations": {"年龄": "搭配：年龄应说“越来越大”，不能说“越来越多”。", "视力": "搭配：“视力”用“好”或“差”来形容，不能说“越来越多”。", "体温": "语义：体温指身体的温度，不会随成长变成“越来越多”。", "词汇": "词汇指孩子掌握的词，随着长大会越来越多，与句意相符。"}, "sentence_index": 6, "correct_answer": "词汇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "留学生掌握了一颗汉语词汇。", "explanation": "汉语词汇被误当成颗粒状的小东西，好像能一颗颗数。汉语词汇指汉语全部词的总和，是抽象集合，不能这样计数。"}, {"text": "留学生背了一条汉语词汇。", "explanation": "汉语词汇被误当成细长的具体物件，好像能一根根数。汉语词汇指汉语全部词的总和，是抽象集合，不能这样计数。"}, {"text": "留学生有一台汉语词汇。", "explanation": "汉语词汇被误当成机器一类的器械，好像能一台台数。汉语词汇指汉语全部词的总和，是抽象集合，不能这样计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英语的两个词汇非常丰富。", "corrected_sentence": "英语的词汇非常丰富。", "error_description": "“词汇”是集合名词，不能与“两个”搭配计数；应去掉“两个”，说“英语的词汇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个作家的词汇们很有特点。", "corrected_sentence": "这个作家的词汇很有特点。", "error_description": "“词汇”前不能加“们”来表示复数，应去掉“们”，说“这个作家的词汇很有特点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
