INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96456, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "例如；用于列举同类事物。", "primary_collocate": null, "pronunciation": "zhū rú", "ipa": "tʂu˥ ʐu˧˥", "syllable_count": 2, "sentences": [{"text": "学校里有很多社团，诸如音乐、美术和篮球。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常做家务，诸如洗衣服、做饭和打扫房间。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖很多饮料，诸如茶、豆浆和果汁。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有很多商店，诸如书店、花店和面包店。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们很多东西，诸如写字、读书和唱歌。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的交通工具，诸如地铁、公共汽车，都很方便。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月工作很多，诸如开会、写报告，都要认真准备。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢听音乐，诸如流行歌和民歌。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天常见的病，诸如感冒、发烧，要多喝水。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有很多家具，诸如桌子、椅子和床。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诸如此类", "label": "复合"}], "register": "书面", "sense_fingerprint": "相当于“例如”，用于列举同类事物中的几项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea1004ff-ce31-4d4c-a6ba-01a3019f6955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诸如", "is_correct": true, "explanation": "“诸如”引出同类事物中的几个例子，这里列举社团中的音乐、美术和篮球。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象是可以拆开的物件，不能拆音乐、美术这类项目。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理器物，不能修音乐、美术和篮球。"}, {"text": "没有", "is_correct": false, "explanation": "语义：与前句的“有很多社团”矛盾，前后不合。"}], "explanations": {"诸如": "“诸如”引出同类事物中的几个例子，这里列举社团中的音乐、美术和篮球。", "拆": "搭配：“拆”的对象是可以拆开的物件，不能拆音乐、美术这类项目。", "修": "搭配：“修”用于修理器物，不能修音乐、美术和篮球。", "没有": "语义：与前句的“有很多社团”矛盾，前后不合。"}, "sentence_index": 0, "correct_answer": "诸如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家附近有很多商店，书店诸如花店。", "explanation": "这里应该用〈和〉。诸如用于列举同类事物中的几例，书店和花店是并列的两家店，应用和连接。"}, {"text": "我家附近只有三家商店，诸如书店、花店和面包店。", "explanation": "这里应该用〈仅〉。诸如用于列举同类事物中的几例，暗示还有其他的；前文说“只有三家”，是全部，不能再用诸如。"}, {"text": "我家附近一共有三家商店，诸如书店、花店和面包店。", "explanation": "这里应该用〈包括〉。诸如只举同类中的几例，暗示还有没列出的；前文说“一共三家”，是全部，应用包括。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诸如", "is_correct": true, "explanation": "“诸如”引出同类事情的例子，这里列举工作中的开会和写报告。"}, {"text": "赶走", "is_correct": false, "explanation": "搭配：“赶走”的对象是人或动物，不能赶走开会、写报告这类事情。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“开会、写报告”搭配。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：与后句“都要认真准备”矛盾，拒绝了又认真准备，前后不合。"}], "explanations": {"诸如": "“诸如”引出同类事情的例子，这里列举工作中的开会和写报告。", "赶走": "搭配：“赶走”的对象是人或动物，不能赶走开会、写报告这类事情。", "唱": "搭配：“唱”不能与“开会、写报告”搭配。", "拒绝": "语义：与后句“都要认真准备”矛盾，拒绝了又认真准备，前后不合。"}, "sentence_index": 6, "correct_answer": "诸如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间里的摆设，诸如沙发一样漂亮。", "explanation": "这里应该用〈像〉。诸如只用于列举同类事物中的例子，不表示比较相似；说某物像另一物一样要用“像”或“跟…一样”。"}, {"text": "房间里有桌子，诸如椅子和床。", "explanation": "这里应该用〈和〉。诸如用于列举同类事物中的几例，这里“桌子”与“椅子”“床”是并列的家具，应用和连接，不能用诸如。"}, {"text": "房间里的家具很少，诸如桌子、椅子和床。", "explanation": "这里应该用〈只有〉。诸如暗示列出的只是许多同类事物中的几例，与“家具很少”的限定矛盾；说明数量少要用“只有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园旁边有很多餐厅，诸如此类中餐厅、西餐厅和咖啡馆。", "corrected_sentence": "公园旁边有很多餐厅，诸如中餐厅、西餐厅和咖啡馆。", "error_description": "用法错误：“诸如此类”是收尾用的固定说法，不能插在“诸如”和列举项目之间；应说“诸如中餐厅、西餐厅和咖啡馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店里卖很多零食，诸如此类薯片、饼干和糖果。", "corrected_sentence": "店里卖很多零食，诸如薯片、饼干和糖果。", "error_description": "用法错误：“诸如此类”是收尾用的固定说法，要放在列举之后；“此类”不能插在“诸如”和列举的项目之间，应说“诸如薯片、饼干和糖果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
