INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从地下把煤、铁这些东西挖出来。", "primary_collocate": null, "pronunciation": "kāi cǎi", "ipa": "kʰai˥ tsʰai˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座山里的煤已经开采了多年。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在地下开采铁矿。", "target_word": "开采", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里每年开采几百万吨煤。", "target_word": "开采", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开采煤炭很危险，工人要戴安全帽。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座矿山开采了五十年，煤快挖完了。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在开采山下的铁。", "target_word": "开采", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司开采过很多煤，现在换了行业。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去人们用简单的工具开采煤。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的铁很深，开采起来很难。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了开采煤，他们挖了一条长长的井。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开采了", "label": "完成体"}, {"form": "开采过", "label": "经历体"}, {"form": "开采量", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把煤、铁等矿物从地下挖出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14e608b0-7393-4f4f-8031-081eab276426') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开采", "is_correct": true, "explanation": "正确：开采指从地下挖出煤、铁等矿物，与“煤”搭配，符合句意。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：种植用于庄稼、树木，不能说“种植煤”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏识美好的事物，与埋在地下的煤不合。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：驯养用于动物，不能用于煤。"}], "explanations": {"开采": "正确：开采指从地下挖出煤、铁等矿物，与“煤”搭配，符合句意。", "种植": "搭配：种植用于庄稼、树木，不能说“种植煤”。", "欣赏": "语义：欣赏指赏识美好的事物，与埋在地下的煤不合。", "驯养": "搭配：驯养用于动物，不能用于煤。"}, "sentence_index": 0, "correct_answer": "开采"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考古队在这里开采出了一座古墓。", "explanation": "这里应该用〈挖掘〉。开采多用于煤、铁等矿产资源，古墓要用挖掘，不说开采。"}, {"text": "我们在山坡上开采了很多草药。", "explanation": "这里应该用〈采集〉。开采专指采出矿产等矿藏资源，草药不是矿藏，不说开采。"}, {"text": "工人在路边开采了一条长沟。", "explanation": "这里应该用〈挖〉。开采只用于矿产资源，挖沟、挖坑是普通的挖，不说开采。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开采", "is_correct": true, "explanation": "正确：开采与“煤”搭配，表示从地下挖出煤，符合句意。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：饲养用于动物，不能说“饲养煤”。"}, {"text": "组装", "is_correct": false, "explanation": "搭配：组装用于机器、零件，煤不能被组装。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏指用乐器奏乐，与煤无关。"}], "explanations": {"开采": "正确：开采与“煤”搭配，表示从地下挖出煤，符合句意。", "饲养": "搭配：饲养用于动物，不能说“饲养煤”。", "组装": "搭配：组装用于机器、零件，煤不能被组装。", "演奏": "语义：演奏指用乐器奏乐，与煤无关。"}, "sentence_index": 6, "correct_answer": "开采"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民们在田里开采了一大片小麦。", "explanation": "这里应该用〈收割〉。开采用于地下矿产，田里的庄稼要用收割。"}, {"text": "游客们在果园里开采了很多苹果。", "explanation": "这里应该用〈采摘〉。开采只用于地下矿藏，果实要用采摘。"}, {"text": "工人们在山上开采了几棵大树。", "explanation": "这里应该用〈砍伐〉。开采只用于矿藏，树木要用砍伐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这口老井了开采八十年，后来才关闭。", "corrected_sentence": "这口老井开采八十年，后来才关闭。", "error_description": "错误形式是“了开采”，正确形式是“开采”。“了”是动态助词，不能放在动词前，此处多加了一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经在这里开采煤过。", "corrected_sentence": "他们曾经在这里开采过煤。", "error_description": "错误形式是“开采煤过”，正确形式是“开采过煤”。“过”必须紧跟动词，不能放在宾语“煤”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
