INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96470, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挖掘地下矿藏。", "primary_collocate": null, "pronunciation": "kāi cǎi", "ipa": "kʰai˥ tsʰai˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家正在开采地下的石油。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度开采矿藏会破坏环境。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不让公司随便开采矿产。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的金矿已经开采了二十年。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开采天然气需要先钻很深的井。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算开采这片山下的矿藏。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座海底的石油很难开采。", "target_word": "开采", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司拿到了开采这片矿区的许可。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开采过的矿山要重新种树。", "target_word": "开采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的稀土还没有人开采。", "target_word": "开采", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开采了", "label": "完成体"}, {"form": "开采过", "label": "经历体"}, {"form": "开采权", "label": "复合词"}], "register": "中性", "sense_fingerprint": "挖掘石油、天然气、金矿等地下矿藏资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14e608b0-7393-4f4f-8031-081eab276426') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开采", "is_correct": true, "explanation": "正确：开采指从地下采出石油，与“地下的石油”搭配，符合句意。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪用于食物，不能用于石油。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：饲养用于动物，不能用于石油。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏识美好的事物，与埋在地下的石油不合。"}], "explanations": {"开采": "正确：开采指从地下采出石油，与“地下的石油”搭配，符合句意。", "烹饪": "搭配：烹饪用于食物，不能用于石油。", "饲养": "搭配：饲养用于动物，不能用于石油。", "欣赏": "语义：欣赏指赏识美好的事物，与埋在地下的石油不合。"}, "sentence_index": 0, "correct_answer": "开采"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在田里开采了成熟的庄稼。", "explanation": "这里应该用〈收割〉。开采指从地下挖出矿藏，庄稼要用收割。"}, {"text": "工人们在山上开采了许多木材。", "explanation": "这里应该用〈采伐〉。开采用于矿产资源，树木要用采伐。"}, {"text": "渔民在海里开采了大量鱼虾。", "explanation": "这里应该用〈捕捞〉。开采用于地下矿藏，鱼虾要用捕捞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开采", "is_correct": true, "explanation": "正确：“很难开采”说明从海底采出石油困难，与句意一致。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：驯养用于动物，石油不能被驯养。"}, {"text": "组装", "is_correct": false, "explanation": "搭配：组装用于机器零件，石油不能被组装。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏指用乐器奏乐，与石油无关。"}], "explanations": {"开采": "正确：“很难开采”说明从海底采出石油困难，与句意一致。", "驯养": "搭配：驯养用于动物，石油不能被驯养。", "组装": "搭配：组装用于机器零件，石油不能被组装。", "演奏": "语义：演奏指用乐器奏乐，与石油无关。"}, "sentence_index": 6, "correct_answer": "开采"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在山上开采了一些蘑菇。", "explanation": "这里应该用〈采集〉。开采用于地下矿藏，蘑菇要用采集。"}, {"text": "考古队在这里开采出了一批陶器。", "explanation": "这里应该用〈发掘〉。开采用于矿藏，陶器等文物要用发掘。"}, {"text": "妈妈在家开采了一件毛衣。", "explanation": "这里应该用〈织〉。开采用于地下矿藏，毛衣是织出来的，要用织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
