INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有意掩盖真相，不让别人知道。", "primary_collocate": null, "pronunciation": "yǐn mán", "ipa": "in˨˩˦ man˧˥", "syllable_count": 2, "sentences": [{"text": "他向警察隐瞒了真相。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司隐瞒了产品的问题。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想隐瞒自己的年龄。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生不应该对病人隐瞒病情。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他隐瞒着事故的原因，不肯说出来。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你不要再隐瞒了。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他隐瞒过自己的过去。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板故意隐瞒收入，少交了税。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把失败的消息隐瞒了很久。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他隐瞒真相，只是怕大家生气。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐瞒了", "label": "完成体"}, {"form": "隐瞒着", "label": "持续体"}, {"form": "隐瞒过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "故意掩盖真相或事实，不让别人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14e608b0-7393-4f4f-8031-081eab276426') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐瞒", "is_correct": true, "explanation": "正确：隐瞒指有意掩盖真相，与“真相”搭配，符合句意。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：修补用于器物、关系，真相不能被修补。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种指撒下种子，与“真相”无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏识美好的事物，与“真相”不合。"}], "explanations": {"隐瞒": "正确：隐瞒指有意掩盖真相，与“真相”搭配，符合句意。", "修补": "搭配：修补用于器物、关系，真相不能被修补。", "播种": "语义：播种指撒下种子，与“真相”无关。", "欣赏": "语义：欣赏指赏识美好的事物，与“真相”不合。"}, "sentence_index": 0, "correct_answer": "隐瞒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱隐瞒在床底下。", "explanation": "这里应该用〈隐藏〉。隐瞒用于不让人知道的事情，藏实物要用隐藏。"}, {"text": "窗帘隐瞒了阳光。", "explanation": "这里应该用〈遮挡〉。隐瞒的对象是事情或真相，窗帘挡住阳光要用遮挡。"}, {"text": "大雪隐瞒了整条小路。", "explanation": "这里应该用〈覆盖〉。隐瞒是有意不让人知道真相，大雪不能隐瞒，它盖住道路应说覆盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐瞒", "is_correct": true, "explanation": "正确：隐瞒指有意不让人知道，与“过去”搭配，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：测量用于长度、面积等可量化的事物，不能测量过去。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏指用乐器奏乐，与过去无关。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：驯养用于动物，不能用于过去。"}], "explanations": {"隐瞒": "正确：隐瞒指有意不让人知道，与“过去”搭配，符合句意。", "测量": "搭配：测量用于长度、面积等可量化的事物，不能测量过去。", "演奏": "语义：演奏指用乐器奏乐，与过去无关。", "驯养": "搭配：驯养用于动物，不能用于过去。"}, "sentence_index": 6, "correct_answer": "隐瞒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都隐瞒生病的孩子，一刻也不离开他。", "explanation": "这里应该用〈照顾〉。隐瞒是故意不让人知道事情，不能用于照料生病的人。"}, {"text": "公司热情地隐瞒了远道而来的客人。", "explanation": "这里应该用〈接待〉。隐瞒用于事情或真相，不能用于对待客人。"}, {"text": "老朋友隐瞒我度过了最难的时候。", "explanation": "这里应该用〈陪伴〉。隐瞒是有意不让人知道事情，不能用来表示陪伴；句中“度过最难的时候”也不是可以隐瞒的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有隐瞒了这件事。", "corrected_sentence": "他从来没有隐瞒过这件事。", "error_description": "错误形式是“没有……了”，正确形式是“没有……过”。否定过去的经历要用“没有……过”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她隐瞒很好，没人发现。", "corrected_sentence": "她隐瞒得很好，没人发现。", "error_description": "错误形式是“隐瞒很好”，正确形式是“隐瞒得很好”。“隐瞒”后要用“得”引出程度补语，少了“得”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3582298d-e133-4d12-b0b7-b808cfd05dbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡", "is_correct": true, "explanation": "正确：“鲜明”指颜色明亮醒目，“暗淡”指颜色不明亮，二者相对。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不平滑，与颜色的明暗无关。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与颜色的明暗无关。"}, {"text": "清澈", "is_correct": false, "explanation": "“清澈”形容液体或眼神透明，不是“鲜明”的反义词。"}], "correct_answer": "暗淡", "explanations": {"暗淡": "正确：“鲜明”指颜色明亮醒目，“暗淡”指颜色不明亮，二者相对。", "粗糙": "“粗糙”形容表面不平滑，与颜色的明暗无关。", "柔软": "“柔软”形容质地，与颜色的明暗无关。", "清澈": "“清澈”形容液体或眼神透明，不是“鲜明”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡", "is_correct": true, "explanation": "正确：“鲜明”指颜色明亮醒目，“暗淡”指颜色不明亮，二者相对。"}, {"text": "沉重", "is_correct": false, "explanation": "“沉重”形容重量或心情，与颜色的明暗无关。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音，与颜色无关。"}, {"text": "干燥", "is_correct": false, "explanation": "“干燥”形容含水少，与颜色的明暗无关。"}], "correct_answer": "暗淡", "explanations": {"暗淡": "正确：“鲜明”指颜色明亮醒目，“暗淡”指颜色不明亮，二者相对。", "沉重": "“沉重”形容重量或心情，与颜色的明暗无关。", "响亮": "“响亮”形容声音，与颜色无关。", "干燥": "“干燥”形容含水少，与颜色的明暗无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "颜色很亮，一眼就能看清楚。", "primary_collocate": null, "pronunciation": "xiān míng", "ipa": "ɕjɛn˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这朵花的颜色很鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的灯笼在雪里特别鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上画着鲜明的红色和黄色。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件颜色鲜明的裙子。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的那件黄色雨衣很鲜明，一眼就能看清楚。", "target_word": "鲜明", "complexity_tier": "T3", "furigana": "tā mǎi de nà jiàn huángsè yǔyī hěn xiānmíng, yì yǎn jiù néng kàn qīngchu.", "sentence_source": "generated"}, {"text": "秋天的树叶，黄的红的，都很鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里的蓝天白云颜色鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗子的颜色这么鲜明，远远就能看见。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的颜色比以前更鲜明了。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把墙刷成了鲜明的绿色。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鮮明", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鲜明：颜色明亮，一眼就能看清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鲜明", "is_correct": true, "explanation": "正确：鲜明（xiān míng）指颜色明亮，一眼就能看清楚。"}, {"text": "签名", "is_correct": false, "explanation": "qiān（第一声）与 xiān（第一声）声母不同（q 与 x），意思是在文件上写下自己的名字。"}, {"text": "贤明", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是有德行、有见识。"}, {"text": "天明", "is_correct": false, "explanation": "tiān（第一声）与 xiān 声母不同（t 与 x），意思是天亮。"}, {"text": "先民", "is_correct": false, "explanation": "mín（第二声）与 míng（第二声）韵尾不同（n 与 ng），意思是古代的人民。"}], "explanations": {"鲜明": "正确：鲜明（xiān míng）指颜色明亮，一眼就能看清楚。", "签名": "qiān（第一声）与 xiān（第一声）声母不同（q 与 x），意思是在文件上写下自己的名字。", "贤明": "xián（第二声）与 xiān（第一声）声调不同，意思是有德行、有见识。", "天明": "tiān（第一声）与 xiān 声母不同（t 与 x），意思是天亮。", "先民": "mín（第二声）与 míng（第二声）韵尾不同（n 与 ng），意思是古代的人民。"}, "sentence_index": null, "correct_answer": "鲜明"}, "level_3": {"options": [{"text": "鲜明", "is_correct": true, "explanation": "正确：“颜色很鲜明”指颜色明亮，一眼就能看清。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容颜色。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“颜色”能说“深”“浅”“亮”，不能说“颜色很快”。"}, {"text": "低矮", "is_correct": false, "explanation": "语义：“低矮”形容高度，颜色没有高低。"}], "explanations": {"鲜明": "正确：“颜色很鲜明”指颜色明亮，一眼就能看清。", "聪明": "语义：“聪明”形容人的智力，不能用来形容颜色。", "快": "搭配：“颜色”能说“深”“浅”“亮”，不能说“颜色很快”。", "低矮": "语义：“低矮”形容高度，颜色没有高低。"}, "sentence_index": 0, "correct_answer": "鲜明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里传来鲜明的读书声。", "explanation": "这里应该用〈响亮〉。鲜明形容颜色或形象醒目，形容声音要用响亮。"}, {"text": "这碗汤的味道很鲜明，又咸又辣。", "explanation": "这里应该用〈鲜美〉。鲜明形容颜色或形象醒目，不能形容味道。"}, {"text": "电话里传来鲜明的铃声。", "explanation": "这里应该用〈清脆〉。鲜明形容颜色或形象醒目，不能形容铃声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜明", "is_correct": true, "explanation": "正确：“颜色鲜明”指颜色明亮醒目，与“画里的蓝天白云”搭配。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体型或建筑的高度，颜色没有高矮。"}, {"text": "流利", "is_correct": false, "explanation": "语义：“流利”说语言或动作顺畅，不能用于形容颜色。"}, {"text": "长", "is_correct": false, "explanation": "搭配：“颜色”能说“深”“浅”“鲜明”，不能说“颜色很长”。"}], "explanations": {"鲜明": "正确：“颜色鲜明”指颜色明亮醒目，与“画里的蓝天白云”搭配。", "高大": "语义：“高大”形容体型或建筑的高度，颜色没有高矮。", "流利": "语义：“流利”说语言或动作顺畅，不能用于形容颜色。", "长": "搭配：“颜色”能说“深”“浅”“鲜明”，不能说“颜色很长”。"}, "sentence_index": 6, "correct_answer": "鲜明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师讲课的声音很鲜明。", "explanation": "这里应该用〈清晰〉。鲜明形容颜色或形象醒目，形容声音要用清晰。"}, {"text": "这瓶香水的香味很鲜明，闻起来很舒服。", "explanation": "这里应该用〈浓郁〉。鲜明形容颜色或形象醒目，不能形容香味的浓淡。"}, {"text": "这辆自行车的重量很鲜明，骑起来很省力。", "explanation": "这里应该用〈轻〉。鲜明形容颜色或形象醒目，不能形容重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵花的颜色鲜明很，远远就能看到。", "corrected_sentence": "这朵花的颜色鲜明得很，远远就能看到。", "error_description": "“鲜明得很”是程度补语结构，补语标记“得”不能省略；写成“鲜明很”是错误的，应改为“鲜明得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上的颜色慢慢鲜明的起来了。", "corrected_sentence": "墙上的颜色慢慢鲜明起来了。", "error_description": "“鲜明起来”表示颜色逐渐变得鲜明，“起来”是趋向补语，直接接在形容词后面，中间不能加“的”；应改为“慢慢鲜明起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：“鲜明”指界限清楚、突出明显，“模糊”指界限不清，二者相对。"}, {"text": "高尚", "is_correct": false, "explanation": "“高尚”形容品德，与界限是否清楚无关。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或气候，不是“鲜明”的反义词。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”形容事务多，与界限是否清楚无关。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：“鲜明”指界限清楚、突出明显，“模糊”指界限不清，二者相对。", "高尚": "“高尚”形容品德，与界限是否清楚无关。", "温和": "“温和”形容性情或气候，不是“鲜明”的反义词。", "繁忙": "“繁忙”形容事务多，与界限是否清楚无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：“鲜明”指界限清楚、突出明显，“模糊”指界限不清，二者相对。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或事情的难度，与界限是否清楚无关。"}, {"text": "缓慢", "is_correct": false, "explanation": "“缓慢”形容速度，与界限是否清楚无关。"}, {"text": "凌乱", "is_correct": false, "explanation": "“凌乱”形容杂乱，与界限是否清楚的反义关系不成立。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：“鲜明”指界限清楚、突出明显，“模糊”指界限不清，二者相对。", "轻松": "“轻松”形容心情或事情的难度，与界限是否清楚无关。", "缓慢": "“缓慢”形容速度，与界限是否清楚无关。", "凌乱": "“凌乱”形容杂乱，与界限是否清楚的反义关系不成立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "态度、特点、对比等界限清楚，突出明显。", "primary_collocate": null, "pronunciation": "xiān míng", "ipa": "ɕjɛn˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的态度很鲜明，不同意这样做。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子个性鲜明，不怕说话。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种做法的区别十分鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的特点很鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的立场非常鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影里的人物形象很鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的想法和我的对比鲜明。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的风格有鲜明的不同。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事的看法鲜明而清楚。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有自己鲜明的特色。", "target_word": "鲜明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鮮明", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鲜明：态度、特点、对比等界限清楚，突出明显", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鲜明", "is_correct": true, "explanation": "正确：鲜明（xiān míng）指态度、特点等界限清楚，突出明显。"}, {"text": "贤明", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是有德行、有见识。"}, {"text": "先民", "is_correct": false, "explanation": "mín（第二声）与 míng（第二声）韵尾不同（n 与 ng），意思是古代的人民。"}, {"text": "现名", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现在使用的名称。"}, {"text": "天明", "is_correct": false, "explanation": "tiān（第一声）与 xiān 声母不同（t 与 x），意思是天亮。"}], "explanations": {"鲜明": "正确：鲜明（xiān míng）指态度、特点等界限清楚，突出明显。", "贤明": "xián（第二声）与 xiān（第一声）声调不同，意思是有德行、有见识。", "先民": "mín（第二声）与 míng（第二声）韵尾不同（n 与 ng），意思是古代的人民。", "现名": "xiàn（第四声）与 xiān（第一声）声调不同，意思是现在使用的名称。", "天明": "tiān（第一声）与 xiān 声母不同（t 与 x），意思是天亮。"}, "sentence_index": null, "correct_answer": "鲜明"}, "level_3": {"options": [{"text": "鲜明", "is_correct": true, "explanation": "正确：“态度很鲜明”指态度界限清楚，立场明确。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，态度不能用颜色来形容。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容空间范围，态度没有范围可言。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”形容身体形态，不能用来形容态度。"}], "explanations": {"鲜明": "正确：“态度很鲜明”指态度界限清楚，立场明确。", "雪白": "语义：“雪白”形容颜色，态度不能用颜色来形容。", "辽阔": "语义：“辽阔”形容空间范围，态度没有范围可言。", "肥胖": "体貌：“肥胖”形容身体形态，不能用来形容态度。"}, "sentence_index": 0, "correct_answer": "鲜明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里很鲜明，大家都在讨论。", "explanation": "这里应该用〈嘈杂〉。鲜明形容特点、态度等界限清楚，不能用来形容环境的吵闹。"}, {"text": "这块石头摸起来很鲜明。", "explanation": "这里应该用〈粗糙〉。鲜明不能用来形容物体的表面质地。"}, {"text": "这杯水的温度很鲜明，握在手里很暖。", "explanation": "这里应该用〈高〉。鲜明形容颜色、界限或特点突出，不能用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜明", "is_correct": true, "explanation": "正确：“对比鲜明”指差别明显，突出清楚。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体含水多，不能用来形容对比。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容年龄，与两种想法的对比无关。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容身材，不能用来形容对比。"}], "explanations": {"鲜明": "正确：“对比鲜明”指差别明显，突出清楚。", "潮湿": "语义：“潮湿”形容空气或物体含水多，不能用来形容对比。", "年轻": "语义：“年轻”形容年龄，与两种想法的对比无关。", "苗条": "体貌：“苗条”形容身材，不能用来形容对比。"}, "sentence_index": 6, "correct_answer": "鲜明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆里很鲜明，没有人说话。", "explanation": "这里应该用〈寂静〉。鲜明形容特点、态度等界限清楚，不能用来形容环境安静。"}, {"text": "这件事给她的打击很鲜明。", "explanation": "这里应该用〈沉重〉。鲜明不能用来形容打击的程度。"}, {"text": "雨后的空气很鲜明，吸一口很清爽。", "explanation": "这里应该用〈新鲜〉。鲜明形容颜色、界限或特点突出，不能用来形容空气是否清新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他鲜明的表示了反对意见。", "corrected_sentence": "他鲜明地表示了反对意见。", "error_description": "“鲜明”修饰动词“表示”，作状语时应用“地”，写成“的”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的特色越来越鲜明着。", "corrected_sentence": "这家店的特色越来越鲜明了。", "error_description": "“越来越”表示变化，“鲜明”后应接“了”；写成“着”是错误的，“着”表示状态持续，与“越来越”的变化义不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
