INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96483, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一小会儿，或者一下子来了又走的事。", "primary_collocate": null, "pronunciation": "yī zhèn", "ipa": "i˥ tʂən˥˩", "syllable_count": 2, "sentences": [{"text": "外面刮来一阵大风。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上下起一阵小雨。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里传来一阵笑声。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房飘来一阵香味。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的肚子突然一阵疼。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门外响起一阵敲门声。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她心里一阵难过。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上吹来一阵凉风，真舒服。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里响起一阵掌声。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外传来一阵音乐声。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵阵", "label": "重叠"}, {"form": "一阵子", "label": "复合"}], "register": "中性", "sense_fingerprint": "用于风、雨、声音、感觉等来得快去得也快的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea1004ff-ce31-4d4c-a6ba-01a3019f6955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一阵", "is_correct": true, "explanation": "一阵：yī zhèn，一小会儿，或一下子来了又走的事。"}, {"text": "一针", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn（第四声）只差声调，意思是一根针。"}, {"text": "一站", "is_correct": false, "explanation": "zhàn 与 zhèn 韵母不同（-an 与 -en），意思是一站路。"}, {"text": "一丈", "is_correct": false, "explanation": "zhàng 与 zhèn 韵母不同（-ang 与 -en），意思是一丈，约三米多。"}, {"text": "一展", "is_correct": false, "explanation": "zhǎn 与 zhèn 韵母不同且声调不同，意思是展开、展示。"}], "explanations": {"一阵": "一阵：yī zhèn，一小会儿，或一下子来了又走的事。", "一针": "zhēn（第一声）与 zhèn（第四声）只差声调，意思是一根针。", "一站": "zhàn 与 zhèn 韵母不同（-an 与 -en），意思是一站路。", "一丈": "zhàng 与 zhèn 韵母不同（-ang 与 -en），意思是一丈，约三米多。", "一展": "zhǎn 与 zhèn 韵母不同且声调不同，意思是展开、展示。"}, "sentence_index": null, "correct_answer": "一阵"}, "level_3": {"options": [{"text": "一阵", "is_correct": true, "explanation": "“一阵”表示一下子来了又走的风，正好与“刮来”和“大风”相配。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、房屋等大型固定物，不能用来计量风。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能用来计量风。"}, {"text": "一丝", "is_correct": false, "explanation": "语义：“一丝”指极少的一点，与“大风”矛盾。"}], "explanations": {"一阵": "“一阵”表示一下子来了又走的风，正好与“刮来”和“大风”相配。", "一座": "搭配：“座”用于山、桥、房屋等大型固定物，不能用来计量风。", "一张": "搭配：“张”用于平面的东西，不能用来计量风。", "一丝": "语义：“一丝”指极少的一点，与“大风”矛盾。"}, "sentence_index": 0, "correct_answer": "一阵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他参加了一阵比赛。", "explanation": "这里应该用〈一场〉。一阵只用于来去很快的声音、气味、感觉等，比赛是有始有终的活动，应用一场。"}, {"text": "门口站着一阵人。", "explanation": "这里应该用〈一群〉。一阵只用于来去很快的声音、气味、感觉等，不能用来计量站着的人；成群的人应用一群。"}, {"text": "我买了一阵苹果。", "explanation": "这里应该用〈一袋〉。一阵只用于来去很快的声音、气味、感觉等，不能用来计量苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一阵", "is_correct": true, "explanation": "“一阵”表示一下子涌上来又过去的感觉，与“难过”相配。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，不能用来计量“难过”这种感觉。"}, {"text": "一枚", "is_correct": false, "explanation": "搭配：“枚”用于硬币、徽章等小件，不能修饰“难过”。"}, {"text": "一粒", "is_correct": false, "explanation": "语义：“粒”指颗粒状的小东西，与抽象的感觉不相容。"}], "explanations": {"一阵": "“一阵”表示一下子涌上来又过去的感觉，与“难过”相配。", "一根": "搭配：“根”用于细长的东西，不能用来计量“难过”这种感觉。", "一枚": "搭配：“枚”用于硬币、徽章等小件，不能修饰“难过”。", "一粒": "语义：“粒”指颗粒状的小东西，与抽象的感觉不相容。"}, "sentence_index": 6, "correct_answer": "一阵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参加了一阵考试。", "explanation": "这里应该用〈一次〉。一阵只用于来去很快的声音、气味、感觉等，考试是一次性的活动，应用一次。"}, {"text": "他摔了一阵跤，爬起来就走了。", "explanation": "这里应该用〈一次〉。摔跤是一下子完成的动作，不是来去很快的声音、气味或感觉，应用“一次”。"}, {"text": "他带来了一阵水果。", "explanation": "这里应该用〈一篮〉。一阵只用于来去很快的声音、气味、感觉等，不能用来计量水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋外传来一根雷声。", "corrected_sentence": "屋外传来一阵雷声。", "error_description": "量词错误：“根”用于细长的东西，不能用来计量雷声；雷声应用“阵”，应说“一阵雷声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼下传来一阵子歌声。", "corrected_sentence": "楼下传来一阵歌声。", "error_description": "词形错误：“一阵子”指一段时间，不能用来修饰“歌声”，这里应用“一阵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
